        if current < 12:
            with _transaction(conn):
                columns = {
                    str(row[1])
                    for row in conn.execute(
                        "PRAGMA table_info(user_outbox)"
                    ).fetchall()
                }
                if "foreground" not in columns:
                    _executescript_atomic(conn, _MIGRATION_12)
                # Preserve the foreground rows that can be identified from
