    def _outbox_from_row(row: sqlite3.Row | None) -> UserOutboxItem | None:
        if row is None:
            return None
        created_at = _required_row_datetime(
            row["created_at"],
            label="user outbox creation",
            identity=row["outbox_id"],
        )
        return UserOutboxItem(
            outbox_id=row["outbox_id"],
            task_id=row["task_id"],
            event_id=row["event_id"],
            channel=row["channel"],
            bot_id=row["bot_id"],
            external_user_id=row["external_user_id"],
            session_id=row["session_id"],
            agent_id=row["agent_id"],
            reply_target=ReplyTarget.from_value(json_loads(row["reply_target_json"], {})),
            content=row["content"],
            priority=EventPriority(int(row["priority"])),
            delivery_mode=DeliveryMode(row["delivery_mode"]),
            notify_enabled=bool(row["notify_enabled"]) if "notify_enabled" in row.keys() else True,
            foreground=bool(row["foreground"]) if "foreground" in row.keys() else False,
            state=OutboxState(row["state"]),
            presentation=PresentationState(row["presentation"]),
            client_id=row["client_id"],
            attempts=int(row["attempts"]),
            claim_token=row["claim_token"],
            claimed_by=row["claimed_by"],
            lease_expires_at=text_to_datetime(row["lease_expires_at"]),
            next_attempt_at=text_to_datetime(row["next_attempt_at"]),
            last_error=row["last_error"],
            created_at=created_at,
            sent_at=text_to_datetime(row["sent_at"]),
            attachments=tuple(json_loads(row["attachments_json"], []) or []),
            reply_scope_id=(
                row["reply_scope_id"] if "reply_scope_id" in row.keys() else None
            ),
            reply_slot_id=(
                row["reply_slot_id"] if "reply_slot_id" in row.keys() else None
            ),
            reply_ordinal=(
                int(row["reply_ordinal"])
                if "reply_ordinal" in row.keys() and row["reply_ordinal"] is not None
                else None
            ),
            reply_candidate_id=(
                row["reply_candidate_id"]
                if "reply_candidate_id" in row.keys()
                else None
            ),
            reply_fragment_id=(
                row["reply_fragment_id"]
                if "reply_fragment_id" in row.keys()
                else None
            ),
            reply_aggregate_id=(
                row["reply_aggregate_id"]
                if "reply_aggregate_id" in row.keys()
                else None
            ),
            from_user_id=(
                str(row["from_user_id"] or "")
                if "from_user_id" in row.keys()
                else str(row["bot_id"] or "")
            ),
            contextless_client_id=(
                row["contextless_client_id"]
                if "contextless_client_id" in row.keys()
                else None
            ),
            active_wire_variant=(
                str(row["active_wire_variant"] or "primary")
                if "active_wire_variant" in row.keys()
                else "primary"
            ),
            transport_idempotency_key=(
                row["transport_idempotency_key"]
                if "transport_idempotency_key" in row.keys()
                else row["client_id"]
            ),
            sender=(
                json_loads(row["sender_json"], {}) or {}
                if "sender_json" in row.keys()
                else {
                    "channel": str(row["channel"] or ""),
                    "bot_id": str(row["from_user_id"] or row["bot_id"] or ""),
                }
            ),
            delivery_address=(
                DeliveryAddress.from_value(
                    json_loads(row["delivery_address_json"], None)
                )
                if "delivery_address_json" in row.keys()
                else None
            ),
            transport_metadata=(
                json_loads(row["transport_metadata_json"], {}) or {}
                if "transport_metadata_json" in row.keys()
                else {}
            ),
            remote_delivery_id=(
                row["remote_delivery_id"]
                if "remote_delivery_id" in row.keys()
                else None
            ),
        )

    @staticmethod
    def _normalize_command_response_fragments(
        values: Iterable[Any] | None,
    ) -> tuple[dict[str, Any], ...]:
        """Canonicalize the exact explicit wire fragments stored in a receipt."""

        normalized: list[dict[str, Any]] = []
        for ordinal, value in enumerate(values or (), start=1):
            if not isinstance(value, Mapping):
                raise ValueError("command response fragment must be a mapping")
            kind = str(
                value.get("kind", value.get("fragment_kind", "text")) or "text"
            ).strip().lower()
            if kind not in {"text", "media", "bundle"}:
                raise ValueError("command response fragment kind is invalid")
            content = str(
                value.get("content", value.get("text", "")) or ""
            ).strip()
            raw_attachments = value.get("attachments", ()) or ()
            if isinstance(raw_attachments, (str, bytes, bytearray, Mapping)):
                raise ValueError("command response fragment attachments are invalid")
            attachments = list(raw_attachments)
            if not content.strip() and not attachments:
                raise ValueError("command response fragment is empty")
            text_limit = (
                REPLY_TEXT_MAX_CHARS
                if ordinal < REPLY_SCOPE_CAPACITY
                else REPLY_TEXT_MAX_CHARS - len(REPLY_CONTINUATION_SUFFIX)
            )
            if kind in {"text", "bundle"} and len(content) > text_limit:
                raise ValueError(
                    "command response fragment exceeds its deterministic text limit"
                )
            item: dict[str, Any] = {"kind": kind, "content": content}
            if attachments:
                item["attachments"] = attachments
            # Validate that the durable representation is JSON-safe before a
            # receipt effect can commit.
            json_dumps(item)
            normalized.append(item)
        return tuple(normalized)

    @staticmethod
    def _command_receipt_from_row(
        row: sqlite3.Row | None, *, created: bool = False
    ) -> dict[str, Any] | None:
        if row is None:
            return None
        raw_outcome = (
            json_loads(row["outcome_json"], {})
            if "outcome_json" in row.keys()
            else {}
        )
        return {
            "command_id": str(row["command_id"]),
            "channel": str(row["channel"]),
            "bot_id": str(row["bot_id"]),
            "external_user_id": str(row["external_user_id"]),
            "session_id": str(row["session_id"]),
            "external_message_id": str(row["external_message_id"]),
            "command_name": str(row["command_name"]),
            "command_args": tuple(
                str(value)
                for value in (json_loads(row["command_args_json"], []) or [])
            ),
            "command_text": str(row["command_text"] or ""),
            "actor_external_user_id": (
                str(row["actor_external_user_id"] or "")
                if "actor_external_user_id" in row.keys()
                else str(row["external_user_id"] or "")
            ),
            "principal_id": (
                row["principal_id"] if "principal_id" in row.keys() else None
            ),
            "principal_account_id": (
                row["principal_account_id"]
                if "principal_account_id" in row.keys()
                else None
            ),
            "conversation_subject_id": (
                row["conversation_subject_id"]
                if "conversation_subject_id" in row.keys()
                else None
            ),
            "identity_snapshot": (
                json_loads(row["identity_snapshot_json"], {}) or {}
                if "identity_snapshot_json" in row.keys()
                else {}
            ),
            "state": str(row["state"]),
            "response_text": str(row["response_text"] or ""),
            "response_agent_id": str(row["response_agent_id"] or ""),
            "presentation_ids": tuple(
                str(value)
                for value in (
                    json_loads(row["presentation_ids_json"], []) or []
                )
            ),
            "response_fragments": SQLiteStore._normalize_command_response_fragments(
                (json_loads(row["response_fragments_json"], []) or [])
                if "response_fragments_json" in row.keys()
                else ()
            ),
            "outcome": dict(raw_outcome)
            if isinstance(raw_outcome, Mapping)
            else {},
            "created": bool(created),
        }

    @staticmethod
    def _inbound_from_row(row: sqlite3.Row) -> InboundMessage:
        received_at = _required_row_datetime(
            row["received_at"],
            label="inbound receipt",
            identity=row["message_id"],
        )
        identity_snapshot = (
            json_loads(row["identity_snapshot_json"], {}) or {}
            if "identity_snapshot_json" in row.keys()
            else {}
        )
        subject_snapshot = (
            identity_snapshot.get("conversation_subject", {})
            if isinstance(identity_snapshot, Mapping)
            else {}
        )
        destination_snapshot = (
            identity_snapshot.get("destination", {})
            if isinstance(identity_snapshot, Mapping)
            else {}
        )
        if not isinstance(subject_snapshot, Mapping):
            subject_snapshot = {}
        if not isinstance(destination_snapshot, Mapping):
            destination_snapshot = {}
        return InboundMessage(
            channel=row["channel"],
            bot_id=row["bot_id"],
            external_user_id=row["external_user_id"],
            external_message_id=row["external_message_id"],
            text=row["text"],
            session_id=row["session_id"],
            source_sequence=row["source_sequence"],
            context_token=row["context_token"],
            payload=json_loads(row["payload_json"], {}) or {},
            received_at=received_at,
            message_id=row["message_id"],
            status=InboundState(row["status"]),
            task_id=row["task_id"],
            principal_id=(
                row["principal_id"] if "principal_id" in row.keys() else None
            ),
            principal_account_id=(
                row["principal_account_id"]
                if "principal_account_id" in row.keys()
                else None
            ),
            conversation_subject_id=(
                row["conversation_subject_id"]
                if "conversation_subject_id" in row.keys()
                else None
            ),
            conversation_subject_kind=str(
                subject_snapshot.get("kind") or "direct"
            ),
            conversation_subject_scope=str(
                subject_snapshot.get("scope_key") or ""
            ),
            destination_kind=str(destination_snapshot.get("kind") or ""),
            destination_id=str(destination_snapshot.get("id") or ""),
            thread_id=str(destination_snapshot.get("thread_id") or ""),
            root_message_id=str(destination_snapshot.get("root_message_id") or ""),
            transport_metadata=(
                dict(destination_snapshot.get("transport_metadata") or {})
                if isinstance(
                    destination_snapshot.get("transport_metadata"), Mapping
                )
                else {}
            ),
            identity_snapshot=identity_snapshot,
        )

    @classmethod
    def _coerce_inbound(
        cls,
        value: InboundMessage | Mapping[str, Any] | None,
        kwargs: Mapping[str, Any],
    ) -> InboundMessage:
        data: dict[str, Any] = {}
        # ``message_id`` and ``received_at`` are generated by the domain
        # model when a channel omits them.  Remember whether the caller
        # actually asserted either value so an idempotent replay does not
        # conflict merely because coercion allocated a fresh UUID/timestamp.
        message_id_supplied = False
        received_at_supplied = False
        if isinstance(value, InboundMessage):
            # Preserve the immutable domain ID when a channel does not expose
            # a stable external ID, but still run through fallback-key
            # derivation below.  Returning early would collapse every ID-less
            # message into the same empty unique key.
            if value.external_message_id:
                if not kwargs:
                    object.__setattr__(
                        value,
                        "_message_id_supplied",
                        bool(getattr(value, "_message_id_supplied", False)),
                    )
                    object.__setattr__(
                        value,
                        "_received_at_supplied",
                        bool(getattr(value, "_received_at_supplied", False)),
                    )
                    return value
            data.update(
                {
                    name: getattr(value, name)
                    for name in InboundMessage.__dataclass_fields__
                    if name != "task_id"
                }
            )
            message_id_supplied = bool(
                getattr(value, "_message_id_supplied", False)
            )
            received_at_supplied = bool(
                getattr(value, "_received_at_supplied", False)
            )
        elif isinstance(value, Mapping):
            data.update(value)
            # ``message_id`` is also a compatibility alias for an external
            # message ID.  It names the internal immutable envelope only when
            # the mapping separately supplies ``external_message_id``.
            message_id_supplied = bool(
                value.get("external_message_id") and value.get("message_id")
            )
            received_at_supplied = (
                "received_at" in value and value.get("received_at") is not None
            )
        elif value is not None:
            # Channel adapters intentionally use their own immutable envelope
            # type.  Accept matching attributes (and ``to_dict``/dataclass
            # values) at this boundary without importing channel modules into
            # the domain store.
            # Prefer an adapter's store-specific representation.  Generic
            # ``to_dict`` values can contain routing fields such as the
            # currently selected Agent; those are not part of the immutable
            # channel envelope and may legitimately differ on redelivery.
            if hasattr(value, "as_store_dict"):
                try:
                    converted = value.as_store_dict()
                    if isinstance(converted, Mapping):
                        data.update(converted)
                except TypeError:
                    pass
            if not data and hasattr(value, "to_dict"):
                try:
                    converted = value.to_dict()
                    if isinstance(converted, Mapping):
                        data.update(converted)
                except TypeError:
                    pass
            if not data and hasattr(value, "as_dict"):
                converted = value.as_dict()
                if isinstance(converted, Mapping):
                    data.update(converted)
            if not data:
                for name in (
                    "channel", "bot_id", "external_user_id", "external_message_id",
                    "text", "session_id", "source_sequence", "context_token",
                    "received_at", "payload", "message_id", "principal_id",
                    "principal_account_id", "conversation_subject_id",
                    "conversation_subject_kind", "conversation_subject_scope",
                    "destination_kind", "destination_id", "thread_id",
                    "root_message_id", "transport_metadata",
                    "identity_snapshot",
                ):
                    if hasattr(value, name):
                        data[name] = getattr(value, name)
        supplied_kwargs = {
            key: val for key, val in kwargs.items() if val is not None
        }
        if supplied_kwargs.get("message_id") and (
            supplied_kwargs.get("external_message_id")
            or data.get("external_message_id")
        ):
            message_id_supplied = True
        if "received_at" in supplied_kwargs:
            received_at_supplied = True
        data.update(supplied_kwargs)
        # A few channel adapters call the text field ``content`` or ``body``.
        if "text" not in data:
            data["text"] = data.pop("content", data.pop("body", ""))
        if "external_message_id" not in data:
            data["external_message_id"] = data.pop("message_id", "")
        if not data.get("external_message_id"):
            # Stable fallback for channels without a message id.  Persisting
            # this value makes retries deduplicate instead of creating work.
            # Some gateways do not expose a stable message id and may omit
            # both sequence and text for media-only updates.  Include the
            # canonical envelope payload so distinct media updates from the
            # same sender do not collapse into one row.  ``context_token`` is
            # deliberately excluded: it is a rolling transport hint and may
            # change when the channel redelivers the *same* message after a
            # reconnect.  Using it here would turn a harmless replay into a
            # second logical task.
            canonical = json_dumps(
                {
                    key: data.get(key)
                    for key in (
                        "channel",
                        "bot_id",
                        "external_user_id",
                        "session_id",
                        "source_sequence",
                        "text",
                    )
                }
                | {
                    "payload": cls._inbound_payload_snapshot(
                        data.get("payload") or {}
                    )
                }
            )
            data["external_message_id"] = "fallback-" + hashlib.sha256(canonical.encode()).hexdigest()
        data.setdefault("channel", "")
        data.setdefault("bot_id", "")
        data.setdefault("external_user_id", "")
        data.setdefault("session_id", "default")
        if not data.get("session_id"):
            data["session_id"] = "default"
        data.setdefault("payload", {})
        allowed = set(InboundMessage.__dataclass_fields__)
        # Preserve channel-specific diagnostics under payload rather than
        # allowing unknown envelope fields to break durable acceptance.
        extras = {key: data[key] for key in tuple(data) if key not in allowed}
        if extras:
            payload = dict(data.get("payload") or {})
            payload.setdefault("channel_metadata", extras)
            data["payload"] = payload
        result = InboundMessage(
            **{key: data[key] for key in allowed if key in data}
        )
        object.__setattr__(result, "_message_id_supplied", message_id_supplied)
        object.__setattr__(result, "_received_at_supplied", received_at_supplied)
        return result

    @classmethod
    def _validate_inbound_replay_tx(
        cls,
        row: sqlite3.Row,
        message: InboundMessage,
        *,
        trusted_media_wire_fingerprints: Sequence[str] | None = None,
    ) -> None:
        """Fail closed when a dedupe identity is reused for new content.

        The channel identity is the lookup key, not permission to rewrite the
        stored envelope.  ``context_token`` is intentionally a transport hint
        and is therefore ignored on replay; the first committed value remains
        on the durable reply target.  UUIDs and receive timestamps are the two
        other exceptions:
        channel adapters commonly omit them and coercion then generates fresh
        values on every replay, so they are compared only when the caller
        explicitly supplied them.
        """

        expected: dict[str, Any] = {
            "channel": message.channel,
            "bot_id": message.bot_id,
            "external_user_id": message.external_user_id,
            "external_message_id": message.external_message_id,
            "session_id": message.session_id or "default",
            "source_sequence": message.source_sequence,
            "text": message.text,
        }
        if bool(getattr(message, "_message_id_supplied", False)):
            expected["message_id"] = message.message_id
        if bool(getattr(message, "_received_at_supplied", False)):
            expected["received_at"] = _utc_text(message.received_at)

        for column, incoming in expected.items():
            stored = row[column]
            if column == "session_id":
                stored = stored or "default"
            equal = (stored is None and incoming is None) or str(stored) == str(
                incoming
            )
            if not equal:
                raise StoreError(
                    "inbound identity conflicts with immutable envelope "
                    f"({column})"
                )

        # The stored row is authoritative and may carry the adapter's
        # hash-only fingerprint after media was promoted.  A replay payload is
        # untrusted: any fingerprint it supplies must be recomputed from its
        # wire reference rather than accepted as an assertion.
        stored_payload = cls._inbound_payload_snapshot(
            json_loads(row["payload_json"], {}) or {},
            trust_media_fingerprints=True,
        )
        incoming_payload = cls._inbound_payload_snapshot(
            message.payload or {},
            trusted_media_wire_fingerprints=trusted_media_wire_fingerprints,
        )
        if stored_payload != incoming_payload:
            raise StoreError(
                "inbound identity conflicts with immutable envelope (payload)"
            )
        identity_snapshot = (
            json_loads(row["identity_snapshot_json"], {}) or {}
            if "identity_snapshot_json" in row.keys()
            else {}
        )
        subject_snapshot = (
            identity_snapshot.get("conversation_subject", {})
            if isinstance(identity_snapshot, Mapping)
            else {}
        )
        destination_snapshot = (
            identity_snapshot.get("destination", {})
            if isinstance(identity_snapshot, Mapping)
            else {}
        )
        if not isinstance(subject_snapshot, Mapping):
            subject_snapshot = {}
        if not isinstance(destination_snapshot, Mapping):
            destination_snapshot = {}
        supplied_subject = str(message.conversation_subject_id or "").strip()
        if supplied_subject and supplied_subject not in {
            str(subject_snapshot.get("conversation_subject_id") or ""),
            str(subject_snapshot.get("scope_key") or ""),
        }:
            raise StoreError(
                "inbound identity conflicts with immutable envelope "
                "(conversation_subject_id)"
            )
        supplied_kind = str(message.conversation_subject_kind or "direct").strip().lower()
        stored_kind = str(subject_snapshot.get("kind") or "direct").strip().lower()
        if supplied_kind != stored_kind:
            raise StoreError(
                "inbound identity conflicts with immutable envelope "
                "(conversation_subject_kind)"
            )
        for label, supplied, stored in (
            ("destination_kind", message.destination_kind, destination_snapshot.get("kind")),
            ("destination_id", message.destination_id, destination_snapshot.get("id")),
            ("thread_id", message.thread_id, destination_snapshot.get("thread_id")),
        ):
            if supplied and str(supplied) != str(stored or ""):
                raise StoreError(
                    "inbound identity conflicts with immutable envelope "
                    f"({label})"
                )
        if message.transport_metadata and cls._json_snapshot(
            dict(message.transport_metadata)
        ) != cls._json_snapshot(
            destination_snapshot.get("transport_metadata") or {}
        ):
            raise StoreError(
                "inbound identity conflicts with immutable envelope "
                "(transport_metadata)"
            )

    @classmethod
    def _inbound_payload_snapshot(
        cls,
        payload: Any,
        *,
        trust_media_fingerprints: bool = False,
        trusted_media_wire_fingerprints: Sequence[str] | None = None,
    ) -> Any:
        """Canonicalize diagnostic payloads for immutable replay checks.

        Channel adapters may include a rolling transport context token in
        either the payload itself or a nested ``channel_metadata`` object.
        That hint is deliberately excluded from the replay identity.  Other
        payload fields, including media references and protocol sequence data,
        remain strict immutable envelope content.
        """

        snapshot = cls._json_snapshot(
            cls._sanitize_inbound_payload(
                payload,
                trust_media_fingerprints=trust_media_fingerprints,
                trusted_media_wire_fingerprints=trusted_media_wire_fingerprints,
            )
        )
        if not isinstance(snapshot, Mapping):
            return snapshot
        snapshot = dict(snapshot)
        snapshot.pop("context_token", None)
        snapshot.pop("contextToken", None)
        # A command's resolved route is an immutable replay hint persisted by
        # the runtime, not part of the channel envelope identity.  Redelivery
        # may carry a newly resolved route; never reject it as changed wire
        # content, and never let the incoming value overwrite the stored one.
        snapshot.pop("__command_snapshot", None)
        snapshot.pop("__route_snapshot", None)
        if "media" in snapshot:
            snapshot["media"] = list(
                canonical_media_inputs(snapshot.get("media"), include_candidate=True)
            )
        if "attachments" in snapshot:
            snapshot["attachments"] = list(
                canonical_media_inputs(
                    snapshot.get("attachments"), include_candidate=True
                )
            )
        if "images" in snapshot:
            snapshot["images"] = list(
                canonical_media_inputs(
                    snapshot.get("images"), include_candidate=True
                )
            )
        metadata = snapshot.get("channel_metadata")
        if isinstance(metadata, Mapping):
            metadata = dict(metadata)
            metadata.pop("context_token", None)
            metadata.pop("contextToken", None)
            snapshot["channel_metadata"] = metadata
        return snapshot

    @classmethod
    def _sanitize_inbound_payload(
        cls,
        payload: Any,
        *,
        trust_media_fingerprints: bool = False,
        trusted_media_wire_fingerprints: Sequence[str] | None = None,
    ) -> dict[str, Any]:
        """Drop untrusted control snapshots and redact wire media secrets."""

        sanitized = dict(payload) if isinstance(payload, Mapping) else {}
        supplied_wire_fingerprints = sanitized.pop(
            "__media_wire_fingerprints", None
        )
        if trusted_media_wire_fingerprints is not None:
            try:
                trusted_values = list(trusted_media_wire_fingerprints)
            except TypeError as exc:
                raise ValueError("invalid trusted media fingerprints") from exc
            for fingerprint in trusted_values:
                value = str(fingerprint or "").lower()
                if len(value) != 64:
                    raise ValueError("invalid trusted media fingerprint")
                try:
                    int(value, 16)
                except ValueError as exc:
                    raise ValueError("invalid trusted media fingerprint") from exc
            trusted_values = [str(value).lower() for value in trusted_values]
        else:
            trusted_values = None
        sanitized.pop("__command_snapshot", None)
        sanitized.pop("__route_snapshot", None)
        # WeChat's raw model dump duplicates every media object under
        # ``item_list``, including encrypted CDN query parameters and AES
        # keys.  The channel adapter normally removes it after extracting the
        # canonical ``media`` projection; enforce the same boundary here for
        # direct store callers and older adapters.
        sanitized.pop("item_list", None)
        sanitized.pop("itemList", None)
        for key in ("media", "attachments", "images"):
            if key in sanitized:
                raw_values = sanitized.get(key)
                if key == "media":
                    if isinstance(raw_values, Mapping) or isinstance(
                        raw_values, (str, bytes, bytearray)
                    ):
                        raw_values = (raw_values,)
                    try:
                        raw_values = tuple(raw_values or ())
                    except TypeError:
                        raw_values = (raw_values,)

                    # A promoted envelope contains only managed metadata and
                    # may legitimately carry the fingerprint computed by the
                    # trusted channel adapter.  Raw wire media, however, must
                    # always be fingerprinted afresh; otherwise a caller can
                    # pair a changed CDN reference with a copied digest.
                    wire_fields = {
                        "remote_id",
                        "media_id",
                        "id",
                        "encrypted_query_param",
                        "encrypt_query_param",
                        "download_param",
                        "encryption_key",
                        "aes_key",
                        "aes_key_base64",
                        "upload_param",
                    }
                    has_wire_reference = any(
                        not isinstance(value, Mapping)
                        or bool(wire_fields.intersection(value.keys()))
                        for value in raw_values
                    )
                    supplied_list = None
                    if trusted_values is not None:
                        if len(trusted_values) != len(raw_values):
                            raise ValueError(
                                "trusted media fingerprint count conflicts with media"
                            )
                        supplied_list = trusted_values
                    elif trust_media_fingerprints:
                        if isinstance(supplied_wire_fingerprints, (list, tuple)):
                            supplied_list = [
                                str(value).lower()
                                for value in supplied_wire_fingerprints
                            ]
                            if len(supplied_list) != len(raw_values):
                                raise ValueError(
                                    "stored media fingerprint count conflicts with media"
                                )
                        if has_wire_reference:
                            supplied_list = None
                    if supplied_list is None:
                        fingerprints: list[str] = []
                        for value in raw_values:
                            # Keep only a deterministic non-secret digest in
                            # SQLite.  Raw CDN query/key material never crosses
                            # the durable envelope boundary.
                            fingerprints.append(wire_media_fingerprint(value))
                        if fingerprints:
                            sanitized["__media_wire_fingerprints"] = fingerprints
                    else:
                        sanitized["__media_wire_fingerprints"] = supplied_list
                sanitized[key] = list(
                    canonical_media_inputs(
                        raw_values, include_candidate=True
                    )
                )
        return sanitized

    @staticmethod
    def _coerce_reply_target(value: Any, *, fallback: ReplyTarget | None = None) -> ReplyTarget:
        if value is not None and not isinstance(value, (ReplyTarget, Mapping)):
            if hasattr(value, "to_dict"):
                try:
                    value = value.to_dict()
                except TypeError:
                    pass
            elif hasattr(value, "as_dict"):
                value = value.as_dict()
            elif all(hasattr(value, name) for name in ("channel", "bot_id", "external_user_id")):
                value = {
                    name: getattr(value, name, None)
                    for name in ReplyTarget.__dataclass_fields__
                }
        target = ReplyTarget.from_value(value)
        if fallback is not None:
            empty_scope = not any(
                (target.channel, target.bot_id, target.external_user_id)
            )
            target = ReplyTarget(
                channel=target.channel or fallback.channel,
                bot_id=target.bot_id or fallback.bot_id,
                external_user_id=target.external_user_id or fallback.external_user_id,
                session_id=(
                    fallback.session_id
                    if empty_scope and target.session_id in ("", "default")
                    else target.session_id or fallback.session_id or "default"
                ),
                source_message_id=target.source_message_id or fallback.source_message_id,
                source_sequence=(
                    target.source_sequence
                    if target.source_sequence is not None
                    else fallback.source_sequence
                ),
                context_token=target.context_token or fallback.context_token,
                conversation_subject_id=(
                    target.conversation_subject_id
                    or fallback.conversation_subject_id
                ),
                conversation_subject_scope=(
                    target.conversation_subject_scope
                    or fallback.conversation_subject_scope
                ),
                destination_kind=(
                    target.destination_kind or fallback.destination_kind
                ),
                destination_id=target.destination_id or fallback.destination_id,
                thread_id=target.thread_id or fallback.thread_id,
                root_message_id=target.root_message_id or fallback.root_message_id,
                transport_metadata=(
                    dict(target.transport_metadata)
                    if target.transport_metadata
                    else dict(fallback.transport_metadata)
                ),
            )
        return target

    @staticmethod
    def _validate_reply_target_scope(
        target: ReplyTarget,
        *,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
    ) -> None:
        expected = {
            "channel": channel,
            "bot_id": bot_id,
            "external_user_id": external_user_id,
            "session_id": session_id or "default",
        }
        target_has_scope = bool(
            target.channel or target.bot_id or target.external_user_id
        )
        for field, owner in expected.items():
            supplied = getattr(target, field)
            # ReplyTarget() uses ``default`` as its dataclass default.  When
            # all other scope fields are empty that value means "unspecified",
            # not an attempted override of a non-default inbound session.
            if field == "session_id" and supplied == "default" and not target_has_scope:
                continue
            subject_owns_route = (
                field == "external_user_id"
                and bool(
                    target.conversation_subject_scope
                    or target.conversation_subject_id
                )
                and str(
                    target.conversation_subject_scope
                    or target.conversation_subject_id
                ) == str(owner)
            )
            if (
                supplied
                and owner
                and str(supplied) != str(owner)
                and not subject_owns_route
            ):
                raise StoreError(f"reply target conflicts with inbound ownership ({field})")

    @staticmethod
    def _coerce_task(value: AgentTask | Mapping[str, Any] | None, kwargs: Mapping[str, Any]) -> AgentTask:
        if isinstance(value, AgentTask):
            if not kwargs:
                return value
            data: dict[str, Any] = {
                name: getattr(value, name) for name in value.__dataclass_fields__
            }
        elif value is not None and not isinstance(value, Mapping):
            data = {}
            for converter in ("as_dict", "to_dict"):
                method = getattr(value, converter, None)
                if method is not None:
                    try:
                        converted = method()
                    except TypeError:
                        converted = None
                    if isinstance(converted, Mapping):
                        data.update(converted)
                        break
            if not data:
                for name in (
                    "task_id", "execution_id", "agent_id", "conversation_id", "thread_id",
                    "mode_id", "profile_version", "policy_version", "model", "reasoning_effort",
                    "reply_target", "inputs", "request_id", "inbound_message_id", "dedupe_key",
                    "parent_task_id", "child_depth", "metadata",
                    "actor_external_user_id", "principal_id",
                    "principal_account_id", "conversation_subject_id",
                    "identity_snapshot",
                ):
                    if hasattr(value, name):
                        data[name] = getattr(value, name)
        else:
            data = dict(value or {})
        data.update({key: val for key, val in kwargs.items() if val is not None})
        # ``input`` and ``payload`` are common aliases for the immutable task
        # input snapshot.
        if "inputs" not in data:
            data["inputs"] = data.pop("input", data.pop("payload", {}))
        data.setdefault("task_id", "")
        data.setdefault("agent_id", "codex")
        data.setdefault("mode_id", "chat")
        data.setdefault("profile_version", 1)
        data.setdefault("policy_version", 1)
        data.setdefault("model", "")
        data.setdefault("reasoning_effort", "")
        data.setdefault("reply_target", ReplyTarget())
        data.setdefault("inputs", {})
        data.setdefault("conversation_id", "")
        data.setdefault("thread_id", None)
        data.setdefault("execution_id", "")
        data.setdefault("request_id", None)
        data.setdefault("inbound_message_id", None)
        data.setdefault("dedupe_key", None)
        data.setdefault("parent_task_id", None)
        data.setdefault("child_depth", 0)
        data.setdefault("metadata", {})
        data.setdefault("actor_external_user_id", "")
        data.setdefault("principal_id", None)
        data.setdefault("principal_account_id", None)
        data.setdefault("conversation_subject_id", None)
        data.setdefault("identity_snapshot", {})
        # Channel/runtime adapters may provide their own immutable
        # ReplyTarget dataclass.  Normalize by attributes/as_dict before the
        # domain model conversion instead of silently dropping the snapshot.
        data["reply_target"] = SQLiteStore._coerce_reply_target(data["reply_target"])
        # Ignore extra fields from channel-specific dictionaries while keeping
        # the core snapshot strict and predictable.
        allowed = set(AgentTask.__dataclass_fields__)
        return AgentTask(**{key: data[key] for key in allowed})

    @staticmethod
    def _task_select_sql() -> str:
        return """SELECT t.*, t.current_execution_id AS execution_id
                FROM tasks t"""

    @staticmethod
    def _current_agent_incarnation_tx(
        conn: sqlite3.Connection, agent_id: str, profile_version: int | None = None
    ) -> int:
        params: list[Any] = [str(agent_id)]
        profile_clause = ""
        if profile_version is not None:
            profile_clause = " AND profile_version=?"
            params.append(int(profile_version))
        rows = conn.execute(
            "SELECT agent_incarnation FROM agent_lifecycle WHERE agent_id=? "
            "AND lifecycle_state!='tombstoned'" + profile_clause
            + " ORDER BY agent_incarnation DESC",
            params,
        ).fetchall()
        if len(rows) != 1:
            raise StoreError(
                f"Agent incarnation is not uniquely resolvable: {agent_id}"
            )
        return int(rows[0]["agent_incarnation"])

    @classmethod
    def _reserve_invocation_admission_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        agent_id: str,
        agent_incarnation: int,
        account_channel: str,
        account_bot_id: str,
        now: str,
        max_agent_queue: int,
        max_global_queue: int,
        max_account_queue: int,
        max_account_agent_queue: int,
    ) -> int:
        channel_value = str(account_channel or "").strip()
        bot_value = str(account_bot_id or "").strip()
        if not channel_value or not bot_value:
            raise StoreError("invocation account identity is required")
        conn.execute(
            """INSERT INTO agent_admission_counters
                   (agent_id,agent_incarnation,unfinished_count,
                    next_ready_sequence,updated_at)
               VALUES (?,?,0,1,?) ON CONFLICT DO NOTHING""",
            (agent_id, int(agent_incarnation), now),
        )
        conn.execute(
            """INSERT INTO global_agent_admission_counter
                   (singleton,unfinished_count,updated_at) VALUES (1,0,?)
               ON CONFLICT(singleton) DO NOTHING""",
            (now,),
        )
        conn.execute(
            """INSERT INTO account_admission_counters
                   (channel,bot_id,unfinished_count,updated_at)
               VALUES (?,?,0,?) ON CONFLICT DO NOTHING""",
            (channel_value, bot_value, now),
        )
        conn.execute(
            """INSERT INTO agent_account_admission_counters
                   (agent_id,agent_incarnation,channel,bot_id,
                    unfinished_count,last_served_ordinal,updated_at)
               VALUES (?,?,?,?,0,0,?) ON CONFLICT DO NOTHING""",
            (
                agent_id,
                int(agent_incarnation),
                channel_value,
                bot_value,
                now,
            ),
        )
        row = conn.execute(
            "SELECT unfinished_count,next_ready_sequence "
            "FROM agent_admission_counters "
            "WHERE agent_id=? AND agent_incarnation=?",
            (agent_id, int(agent_incarnation)),
        ).fetchone()
        if row is None:
            raise StoreError("Agent admission counter is unavailable")
        global_row = conn.execute(
            "SELECT unfinished_count FROM global_agent_admission_counter "
            "WHERE singleton=1"
        ).fetchone()
        if global_row is None:
            raise StoreError("global Agent admission counter is unavailable")
        account_row = conn.execute(
            "SELECT unfinished_count FROM account_admission_counters "
            "WHERE channel=? AND bot_id=?",
            (channel_value, bot_value),
        ).fetchone()
        stream_row = conn.execute(
            "SELECT unfinished_count FROM agent_account_admission_counters "
            "WHERE agent_id=? AND agent_incarnation=? AND channel=? AND bot_id=?",
            (
                agent_id,
                int(agent_incarnation),
                channel_value,
                bot_value,
            ),
        ).fetchone()
        if account_row is None or stream_row is None:
            raise StoreError("account admission counter is unavailable")
        if int(global_row["unfinished_count"]) >= int(max_global_queue):
            raise QueueFullError("global", int(max_global_queue))
        if int(account_row["unfinished_count"]) >= int(max_account_queue):
            raise QueueFullError("account", int(max_account_queue))
        if int(row["unfinished_count"]) >= int(max_agent_queue):
            raise QueueFullError("agent", int(max_agent_queue))
        if int(stream_row["unfinished_count"]) >= int(
            max_account_agent_queue
        ):
            raise QueueFullError(
                "account_agent", int(max_account_agent_queue)
            )
        sequence = int(row["next_ready_sequence"])
        conn.execute(
            """UPDATE agent_admission_counters
               SET unfinished_count=unfinished_count+1,
                   next_ready_sequence=next_ready_sequence+1,updated_at=?
               WHERE agent_id=? AND agent_incarnation=?""",
            (now, agent_id, int(agent_incarnation)),
        )
        if conn.execute(
            """UPDATE global_agent_admission_counter
               SET unfinished_count=unfinished_count+1,updated_at=?
               WHERE singleton=1 AND unfinished_count < ?""",
            (now, int(max_global_queue)),
        ).rowcount != 1:
            # BEGIN IMMEDIATE serializes writers, so this can only mean the
            # durable counter was corrupted or a future caller bypassed the
            # admission check.  Roll the whole acceptance transaction back.
            raise QueueFullError("global", int(max_global_queue))
        if conn.execute(
            """UPDATE account_admission_counters
               SET unfinished_count=unfinished_count+1,updated_at=?
               WHERE channel=? AND bot_id=? AND unfinished_count < ?""",
            (now, channel_value, bot_value, int(max_account_queue)),
        ).rowcount != 1:
            raise QueueFullError("account", int(max_account_queue))
        if conn.execute(
            """UPDATE agent_account_admission_counters
               SET unfinished_count=unfinished_count+1,updated_at=?
               WHERE agent_id=? AND agent_incarnation=?
                 AND channel=? AND bot_id=? AND unfinished_count < ?""",
            (
                now,
                agent_id,
                int(agent_incarnation),
                channel_value,
                bot_value,
                int(max_account_agent_queue),
            ),
        ).rowcount != 1:
            raise QueueFullError(
                "account_agent", int(max_account_agent_queue)
            )
        return sequence

    @classmethod
    def _release_invocation_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        invocation_id: str,
        state: str,
        now: str,
        last_error: str | None = None,
    ) -> bool:
        row = conn.execute(
            "SELECT agent_id,agent_incarnation,account_channel,account_bot_id,"
            "admission_released_at "
            "FROM agent_invocations WHERE invocation_id=?",
            (invocation_id,),
        ).fetchone()
        if row is None:
            raise StoreError(f"invocation not found: {invocation_id}")
        changed = conn.execute(
            """UPDATE agent_invocations SET state=?,claimed_by=NULL,
                   claim_token=NULL,lease_expires_at=NULL,
                   admission_released_at=?,terminal_at=?,updated_at=?,
                   last_error=COALESCE(?,last_error)
               WHERE invocation_id=? AND admission_released_at IS NULL""",
            (state, now, now, now, last_error, invocation_id),
        ).rowcount
        if changed == 0:
            return False
        if conn.execute(
            """UPDATE agent_admission_counters
               SET unfinished_count=unfinished_count-1,updated_at=?
               WHERE agent_id=? AND agent_incarnation=?
                 AND unfinished_count>0""",
            (now, row["agent_id"], row["agent_incarnation"]),
        ).rowcount != 1:
            raise StoreError("Agent admission counter underflow")
        if conn.execute(
            """UPDATE global_agent_admission_counter
               SET unfinished_count=unfinished_count-1,updated_at=?
               WHERE singleton=1 AND unfinished_count>0""",
            (now,),
        ).rowcount != 1:
            raise StoreError("global Agent admission counter underflow")
        if conn.execute(
            """UPDATE account_admission_counters
               SET unfinished_count=unfinished_count-1,updated_at=?
               WHERE channel=? AND bot_id=? AND unfinished_count>0""",
            (now, row["account_channel"], row["account_bot_id"]),
        ).rowcount != 1:
            raise StoreError("account admission counter underflow")
        if conn.execute(
            """UPDATE agent_account_admission_counters
               SET unfinished_count=unfinished_count-1,updated_at=?
               WHERE agent_id=? AND agent_incarnation=?
                 AND channel=? AND bot_id=? AND unfinished_count>0""",
            (
                now,
                row["agent_id"],
                row["agent_incarnation"],
                row["account_channel"],
                row["account_bot_id"],
            ),
        ).rowcount != 1:
            raise StoreError("Agent-account admission counter underflow")
        return True

    @classmethod
    def _expire_pending_mailboxes_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        now: str,
    ) -> int:
        """Terminalize every elapsed, never-dispatched mailbox exactly once."""

        columns = {
            str(row[1])
            for row in conn.execute(
                "PRAGMA table_info(agent_mailbox)"
            ).fetchall()
        }
        if not {"current_invocation_id", "expires_at"}.issubset(columns):
            # Migration fixtures can intentionally stop before schema v26/v28.
            return 0
        rows = conn.execute(
            """SELECT mailbox_id,current_invocation_id
                 FROM agent_mailbox
                WHERE state='pending' AND expires_at<=?
                ORDER BY expires_at,mailbox_id""",
            (now,),
        ).fetchall()
        reason = "mailbox expired before dispatch"
        for row in rows:
            invocation_id = str(row["current_invocation_id"] or "")
            if not invocation_id:
                raise StoreError("expired mailbox lacks a current invocation")
            changed = conn.execute(
                """UPDATE agent_mailbox
                      SET state='expired',processed_at=?,next_attempt_at=NULL,
                          claimed_by=NULL,claim_token=NULL,
                          lease_expires_at=NULL,
                          last_error=COALESCE(last_error,?)
                    WHERE mailbox_id=? AND state='pending' AND expires_at<=?""",
                (now, reason, row["mailbox_id"], now),
            ).rowcount
            if changed != 1:
                raise StoreError("mailbox expiry lost its aggregate fence")
            if not cls._release_invocation_tx(
                conn,
                invocation_id=invocation_id,
                state=InvocationState.FAILED.value,
                now=now,
                last_error=reason,
            ):
                raise StoreError(
                    "expired mailbox invocation was already released"
                )
        return len(rows)

    @classmethod
    def _create_queued_task_invocation_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        task_id: str,
        now: str,
        max_agent_queue: int = DEFAULT_MAX_AGENT_QUEUE,
        max_global_queue: int = DEFAULT_MAX_GLOBAL_AGENT_QUEUE,
        max_account_queue: int = DEFAULT_MAX_GLOBAL_AGENT_QUEUE,
        max_account_agent_queue: int = DEFAULT_MAX_AGENT_QUEUE,
    ) -> str:
        task = conn.execute("SELECT * FROM tasks WHERE task_id=?", (task_id,)).fetchone()
        if task is None:
            raise StoreError("queued task disappeared before invocation creation")
        existing = task["current_execution_id"]
        if existing:
            invocation = conn.execute(
                "SELECT invocation_id FROM agent_invocations WHERE invocation_id=?",
                (existing,),
            ).fetchone()
            if invocation is None:
                raise StoreError("task current execution lacks invocation")
            return str(existing)
        attempt = int(
            conn.execute(
                "SELECT COALESCE(MAX(attempt),0)+1 FROM task_executions WHERE task_id=?",
                (task_id,),
            ).fetchone()[0]
        )
        execution_id = _uuid()
        sequence = cls._reserve_invocation_admission_tx(
            conn,
            agent_id=str(task["agent_id"]),
            agent_incarnation=int(task["agent_incarnation"]),
            account_channel=str(task["channel"] or "internal"),
            account_bot_id=str(task["bot_id"] or "runtime"),
            now=now,
            max_agent_queue=max_agent_queue,
            max_global_queue=max_global_queue,
            max_account_queue=max_account_queue,
            max_account_agent_queue=max_account_agent_queue,
        )
        conn.execute(
            """INSERT INTO task_executions
                   (execution_id,task_id,attempt,agent_id,agent_incarnation,
                    state,dispatch_backend,created_at,delivery_reply_scope_id)
               VALUES (?,?,?,?,?,'queued','compatibility',?,?)""",
            (
                execution_id, task_id, attempt, task["agent_id"],
                task["agent_incarnation"], now,
                task["pending_delivery_reply_scope_id"],
            ),
        )
        conn.execute(
            """INSERT INTO agent_invocations
                   (invocation_id,work_kind,work_id,agent_id,agent_incarnation,
                    state,dispatch_backend,ready_sequence,task_id,execution_id,
                    next_attempt_at,created_at,updated_at,
                    account_channel,account_bot_id)
               VALUES (?,'task',?,?,?,'queued','compatibility',?,?,?,?,?,?,?,?)""",
            (
                execution_id, execution_id, task["agent_id"],
                task["agent_incarnation"], sequence, task_id, execution_id,
                task["next_attempt_at"], now, now,
                task["channel"] or "internal", task["bot_id"] or "runtime",
            ),
        )
        conn.execute(
            "UPDATE tasks SET current_execution_id=? WHERE task_id=?",
            (execution_id, task_id),
        )
        return execution_id

    @classmethod
    def _create_queued_mailbox_invocation_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        mailbox_id: str,
        now: str,
        max_agent_queue: int = DEFAULT_MAX_AGENT_QUEUE,
        max_global_queue: int = DEFAULT_MAX_GLOBAL_AGENT_QUEUE,
        max_account_queue: int = DEFAULT_MAX_GLOBAL_AGENT_QUEUE,
        max_account_agent_queue: int = DEFAULT_MAX_AGENT_QUEUE,
    ) -> str:
        row = conn.execute(
            "SELECT * FROM agent_mailbox WHERE mailbox_id=?", (mailbox_id,)
        ).fetchone()
        if row is None:
            raise StoreError("mailbox disappeared before invocation creation")
        if row["current_invocation_id"]:
            return str(row["current_invocation_id"])
        account = conn.execute(
            "SELECT channel,bot_id FROM tasks WHERE task_id=?",
            (row["task_id"],),
        ).fetchone()
        account_channel = (
            str(account["channel"])
            if account is not None and str(account["channel"] or "").strip()
            else "internal"
        )
        account_bot_id = (
            str(account["bot_id"])
            if account is not None and str(account["bot_id"] or "").strip()
            else str(row["source_agent_id"] or "runtime")
        )
        invocation_id = _uuid()
        sequence = cls._reserve_invocation_admission_tx(
            conn,
            agent_id=str(row["destination_agent_id"]),
            agent_incarnation=int(row["destination_agent_incarnation"]),
            account_channel=account_channel,
            account_bot_id=account_bot_id,
            now=now,
            max_agent_queue=max_agent_queue,
            max_global_queue=max_global_queue,
            max_account_queue=max_account_queue,
            max_account_agent_queue=max_account_agent_queue,
        )
        conn.execute(
            """INSERT INTO agent_invocations
                   (invocation_id,work_kind,work_id,agent_id,agent_incarnation,
                    state,dispatch_backend,ready_sequence,mailbox_id,
                    next_attempt_at,created_at,updated_at,expires_at,
                    account_channel,account_bot_id)
               VALUES (?,'mailbox',?,?,?,'queued','compatibility',?,?,?,?,?,?,?,?)""",
            (
                invocation_id, row["message_id"], row["destination_agent_id"],
                row["destination_agent_incarnation"], sequence, mailbox_id,
                row["next_attempt_at"], now, now, row["expires_at"],
                account_channel, account_bot_id,
            ),
        )
        conn.execute(
            "UPDATE agent_mailbox SET current_invocation_id=? WHERE mailbox_id=?",
            (invocation_id, mailbox_id),
        )
        return invocation_id

    @classmethod
    def _fetch_task_tx(cls, conn: sqlite3.Connection, task_id: str) -> TaskRecord | None:
        row = conn.execute(f"{cls._task_select_sql()} WHERE t.task_id = ?", (task_id,)).fetchone()
        return cls._task_from_row(row)

    @staticmethod
    def _steering_principal_compatible(
        active: sqlite3.Row,
        snapshot: AgentTask,
    ) -> bool:
        """Keep steering inside one authenticated actor/principal boundary."""

        active_principal = str(active["principal_id"] or "")
        incoming_principal = str(snapshot.principal_id or "")
        if active_principal or incoming_principal:
            return bool(
                active_principal
                and incoming_principal
                and active_principal == incoming_principal
            )
        return bool(
            str(active["actor_external_user_id"] or "")
            == str(snapshot.actor_external_user_id or "")
        )

    @classmethod
    def _steering_context_compatible(
        cls,
        active: sqlite3.Row,
        snapshot: AgentTask,
        *,
        conversation_id: str,
        thread_id: str | None,
        agent_incarnation: int,
    ) -> bool:
        """Compare every execution-authority value relevant to live input."""

        scalar_matches = (
            str(active["agent_id"]) == str(snapshot.agent_id),
            int(active["agent_incarnation"]) == int(agent_incarnation),
            str(active["conversation_id"]) == str(conversation_id),
            str(active["thread_id"] or "") == str(thread_id or ""),
            str(active["mode_id"]) == str(snapshot.mode_id),
            int(active["profile_version"]) == int(snapshot.profile_version),
            int(active["policy_version"]) == int(snapshot.policy_version),
            str(active["model"] or "") == str(snapshot.model or ""),
            str(active["reasoning_effort"] or "")
            == str(snapshot.reasoning_effort or ""),
        )
        if not all(scalar_matches) or not cls._steering_principal_compatible(
            active, snapshot
        ):
            return False
        active_metadata = json_loads(active["metadata_json"], {}) or {}
        incoming_metadata = _snapshot_value(snapshot.metadata, text_key="value")
        if not isinstance(active_metadata, Mapping) or not isinstance(
            incoming_metadata, Mapping
        ):
            return False
        # ``front_agent_id_at_acceptance`` is route provenance, not execution
        # authority. Skills are per-input data accepted by the runner's
        # steering contract, so their descriptors may differ as well. Policy,
        # role, workspace, and every other context field remain exact-match
        # requirements.
        ignored = {
            "front_agent_id_at_acceptance",
            "skill",
            "skill_id",
            "skill_version",
            "skill_hash",
        }
        active_context = {
            key: value
            for key, value in active_metadata.items()
            if key not in ignored
        }
        incoming_context = {
            key: value
            for key, value in incoming_metadata.items()
            if key not in ignored
        }
        return json_dumps(active_context) == json_dumps(incoming_context)

    @staticmethod
    def _task_snapshot_for_steering(
        snapshot: AgentTask,
        *,
        inbound: InboundMessage,
        route_external_user_id: str,
        conversation_id: str,
        thread_id: str | None,
        agent_incarnation: int,
        reply_target: ReplyTarget,
    ) -> dict[str, Any]:
        """Freeze the normal queued-task projection used by race fallback."""

        return {
            "inbound_message_id": inbound.message_id,
            "dedupe_key": snapshot.dedupe_key
            or f"inbound:{inbound.message_id}",
            "channel": inbound.channel,
            "bot_id": inbound.bot_id,
            "external_user_id": str(route_external_user_id),
            "session_id": inbound.session_id or "default",
            "agent_id": snapshot.agent_id,
            "agent_incarnation": int(agent_incarnation),
            "conversation_id": conversation_id,
            "thread_id": thread_id,
            "mode_id": snapshot.mode_id,
            "profile_version": int(snapshot.profile_version),
            "policy_version": int(snapshot.policy_version),
            "model": snapshot.model,
            "reasoning_effort": snapshot.reasoning_effort,
            "reply_target": reply_target.to_dict(),
            "inputs": _snapshot_value(snapshot.inputs),
            "metadata": _snapshot_value(snapshot.metadata, text_key="value"),
            "actor_external_user_id": snapshot.actor_external_user_id,
            "principal_id": snapshot.principal_id,
            "principal_account_id": snapshot.principal_account_id,
            "conversation_subject_id": snapshot.conversation_subject_id,
            "identity_snapshot": _snapshot_value(snapshot.identity_snapshot),
            "parent_task_id": snapshot.parent_task_id,
            "child_depth": int(snapshot.child_depth),
            "request_id": snapshot.request_id,
        }

    @classmethod
    def _insert_steering_fallback_task_tx(
        cls,
        conn: sqlite3.Connection,
        steering: sqlite3.Row,
        *,
        now: str,
        max_agent_queue: int,
        max_global_queue: int,
        max_account_queue: int,
        max_account_agent_queue: int,
    ) -> tuple[TaskRecord, str]:
        """Materialize one frozen steering snapshot as an ordinary task."""

        values = json_loads(steering["task_snapshot_json"], None)
        if not isinstance(values, Mapping):
            raise StoreError("task steering fallback snapshot is invalid")
        values = dict(values)
        fallback_task_id = str(steering["fallback_task_id"] or "")
        inbound_message_id = str(steering["inbound_message_id"] or "")
        if not fallback_task_id or not inbound_message_id:
            raise StoreError("task steering fallback identity is incomplete")
        existing = cls._fetch_task_tx(conn, fallback_task_id)
        if existing is not None:
            if str(existing.inbound_message_id or "") != inbound_message_id:
                raise StoreError("task steering fallback identity conflicts")
            if not existing.execution_id:
                raise StoreError("task steering fallback has no execution")
            return existing, str(existing.execution_id)
        foreign = conn.execute(
            "SELECT task_id FROM tasks WHERE inbound_message_id=?",
            (inbound_message_id,),
        ).fetchone()
        if foreign is not None:
            raise StoreError("task steering inbound already owns another task")
        inbound_row = conn.execute(
            "SELECT * FROM inbound_messages WHERE message_id=?",
            (inbound_message_id,),
        ).fetchone()
        if inbound_row is None:
            raise StoreError("task steering inbound message is unavailable")

        required_text = (
            "channel",
            "bot_id",
            "external_user_id",
            "session_id",
            "agent_id",
            "conversation_id",
            "mode_id",
        )
        if any(not str(values.get(name) or "").strip() for name in required_text):
            raise StoreError("task steering fallback snapshot is incomplete")
        if (
            str(values.get("agent_id")) != str(steering["agent_id"])
            or int(values.get("agent_incarnation") or 0)
            != int(steering["agent_incarnation"])
            or str(values.get("conversation_id"))
            != str(steering["conversation_id"])
            or str(values.get("inbound_message_id")) != inbound_message_id
        ):
            raise StoreError("task steering fallback ownership conflicts")
        target_owner = conn.execute(
            """SELECT thread_id,conversation_id,mode_id,profile_version,
                      policy_version,agent_id,agent_incarnation
                 FROM tasks WHERE task_id=?""",
            (str(steering["target_task_id"]),),
        ).fetchone()
        if target_owner is None:
            raise StoreError("task steering fallback target is unavailable")
        if (
            str(target_owner["conversation_id"]) != str(values["conversation_id"])
            or str(target_owner["mode_id"]) != str(values["mode_id"])
            or int(target_owner["profile_version"])
            != int(values.get("profile_version") or 1)
            or int(target_owner["policy_version"])
            != int(values.get("policy_version") or 1)
            or str(target_owner["agent_id"]) != str(values["agent_id"])
            or int(target_owner["agent_incarnation"])
            != int(values["agent_incarnation"])
        ):
            raise StoreError("task steering fallback context changed")
        frozen_thread = str(values.get("thread_id") or "")
        target_thread = str(target_owner["thread_id"] or "")
        if frozen_thread and target_thread and frozen_thread != target_thread:
            raise StoreError("task steering fallback thread binding conflicts")
        # The provider thread can be learned only after the active turn starts.
        # Inheriting that one compatible binding preserves the running turn's
        # context without accepting any later policy/role/workspace mutation.
        values["thread_id"] = target_thread or frozen_thread or None
        reply_target = cls._coerce_reply_target(values.get("reply_target"))
        cls._validate_reply_target_scope(
            reply_target,
            channel=str(inbound_row["channel"] or ""),
            bot_id=str(inbound_row["bot_id"] or ""),
            external_user_id=str(inbound_row["external_user_id"] or ""),
            session_id=str(inbound_row["session_id"] or "default"),
        )
        inputs = values.get("inputs", {})
        dedupe_key = str(
            values.get("dedupe_key") or f"inbound:{inbound_message_id}"
        )
        conn.execute(
            """INSERT INTO tasks
               (task_id, dedupe_key, inbound_message_id, channel, bot_id,
                external_user_id, session_id, agent_id, agent_incarnation,
                conversation_id, thread_id, mode_id, profile_version,
                policy_version, model, reasoning_effort, reply_target_json,
                inputs_json, metadata_json, actor_external_user_id,
                principal_id, principal_account_id, conversation_subject_id,
                identity_snapshot_json, state, attempts, next_attempt_at,
                parent_task_id, child_depth, request_id, created_at, updated_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                       ?, ?, ?, ?, ?, ?, 'queued', 0, NULL, ?, ?, ?, ?, ?)""",
            (
                fallback_task_id,
                dedupe_key,
                inbound_message_id,
                str(values["channel"]),
                str(values["bot_id"]),
                str(values["external_user_id"]),
                str(values["session_id"] or "default"),
                str(values["agent_id"]),
                int(values["agent_incarnation"]),
                str(values["conversation_id"]),
                values.get("thread_id"),
                str(values["mode_id"]),
                int(values.get("profile_version") or 1),
                int(values.get("policy_version") or 1),
                str(values.get("model") or ""),
                str(values.get("reasoning_effort") or ""),
                json_dumps(reply_target.to_dict()),
                json_dumps(_snapshot_value(inputs)),
                json_dumps(
                    _snapshot_value(values.get("metadata", {}), text_key="value")
                ),
                str(values.get("actor_external_user_id") or ""),
                values.get("principal_id"),
                values.get("principal_account_id"),
                values.get("conversation_subject_id"),
                json_dumps(_snapshot_value(values.get("identity_snapshot", {}))),
                values.get("parent_task_id"),
                int(values.get("child_depth") or 0),
                values.get("request_id"),
                now,
                now,
            ),
        )
        conn.execute(
            "UPDATE inbound_messages SET task_id=?,status='task_queued',stored_at=? "
            "WHERE message_id=?",
            (fallback_task_id, now, inbound_message_id),
        )
        cls._validate_task_input_attachment_access_tx(
            conn,
            task_id=fallback_task_id,
            inbound_message_id=inbound_message_id,
            inputs=inputs,
            agent_id=str(values["agent_id"]),
            channel=str(values["channel"]),
            bot_id=str(values["bot_id"]),
            external_user_id=str(values["external_user_id"]),
            session_id=str(values["session_id"] or "default"),
        )
        cls._retain_task_input_attachments_tx(
            conn,
            task_id=fallback_task_id,
            inputs=inputs,
            created_at=now,
        )
        execution_id = cls._create_queued_task_invocation_tx(
            conn,
            task_id=fallback_task_id,
            now=now,
            max_agent_queue=max_agent_queue,
            max_global_queue=max_global_queue,
            max_account_queue=max_account_queue,
            max_account_agent_queue=max_account_agent_queue,
        )
        created = cls._fetch_task_tx(conn, fallback_task_id)
        if created is None:
            raise StoreError("task steering fallback task disappeared")
        return created, execution_id

    @classmethod
    def _promote_task_steering_row_tx(
        cls,
        conn: sqlite3.Connection,
        steering: sqlite3.Row,
        *,
        now: str,
        max_agent_queue: int,
        max_global_queue: int,
        max_account_queue: int,
        max_account_agent_queue: int,
    ) -> tuple[TaskSteeringRecord, TaskRecord]:
        """Promote one head row and attach its ordered tail to the fallback."""

        steering_id = str(steering["steering_id"])
        original_task_id = str(steering["target_task_id"])
        original_execution_id = str(steering["target_execution_id"])
        sequence = int(steering["sequence"])
        fallback, fallback_execution_id = cls._insert_steering_fallback_task_tx(
            conn,
            steering,
            now=now,
            max_agent_queue=max_agent_queue,
            max_global_queue=max_global_queue,
            max_account_queue=max_account_queue,
            max_account_agent_queue=max_account_agent_queue,
        )
        changed = conn.execute(
            """UPDATE task_steering
                  SET state='promoted',promoted_task_id=?,promoted_at=?,
                      updated_at=?,claimed_by=NULL,claim_token=NULL,
                      lease_expires_at=NULL
                WHERE steering_id=? AND state='pending'""",
            (fallback.task_id, now, now, steering_id),
        ).rowcount
        if changed != 1:
            raise InvalidTransition("task steering promotion lost its state fence")

        # Later pending ordinals become input to the one fallback turn instead
        # of each consuming another queue/admission slot.  Applied, delivering,
        # and uncertain rows retain their original immutable execution fence.
        tail_rows = conn.execute(
            """SELECT steering_id,inbound_message_id
                 FROM task_steering
                WHERE target_task_id=? AND target_execution_id=?
                  AND state='pending' AND sequence>?
                ORDER BY sequence,steering_id""",
            (original_task_id, original_execution_id, sequence),
        ).fetchall()
        if tail_rows:
            tail_ids = [str(row["steering_id"]) for row in tail_rows]
            placeholders = ",".join("?" for _ in tail_ids)
            conn.execute(
                f"""UPDATE task_steering
                       SET target_task_id=?,target_execution_id=?,updated_at=?
                     WHERE steering_id IN ({placeholders}) AND state='pending'""",
                (
                    fallback.task_id,
                    fallback_execution_id,
                    now,
                    *tail_ids,
                ),
            )
            inbound_ids = [str(row["inbound_message_id"]) for row in tail_rows]
            inbound_placeholders = ",".join("?" for _ in inbound_ids)
            conn.execute(
                f"""UPDATE inbound_messages
                       SET task_id=?,status='task_queued',stored_at=?
                     WHERE message_id IN ({inbound_placeholders})""",
                (fallback.task_id, now, *inbound_ids),
            )
        promoted = cls._task_steering_from_row(
            conn.execute(
                "SELECT * FROM task_steering WHERE steering_id=?",
                (steering_id,),
            ).fetchone()
        )
        if promoted is None:
            raise StoreError("promoted task steering disappeared")
        refreshed_fallback = cls._fetch_task_tx(conn, fallback.task_id)
        if refreshed_fallback is None:
            raise StoreError("promoted fallback task disappeared")
        return promoted, refreshed_fallback

    @classmethod
    def _promote_pending_steering_for_execution_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        task_id: str,
        execution_id: str,
        now: str,
        max_agent_queue: int,
        max_global_queue: int,
        max_account_queue: int,
        max_account_agent_queue: int,
        suppress_queue_full: bool = True,
    ) -> tuple[TaskSteeringRecord, TaskRecord] | None:
        """Promote only an unambiguous pending head after an execution ends."""

        head = conn.execute(
            """SELECT * FROM task_steering
                WHERE target_task_id=? AND target_execution_id=?
                  AND state IN ('pending','delivering')
                ORDER BY sequence,steering_id LIMIT 1""",
            (str(task_id), str(execution_id)),
        ).fetchone()
        if head is None or str(head["state"]) != TaskSteeringState.PENDING.value:
            return None
        conn.execute("SAVEPOINT promote_task_steering")
        try:
            result = cls._promote_task_steering_row_tx(
                conn,
                head,
                now=now,
                max_agent_queue=max_agent_queue,
                max_global_queue=max_global_queue,
                max_account_queue=max_account_queue,
                max_account_agent_queue=max_account_agent_queue,
            )
        except QueueFullError:
            conn.execute("ROLLBACK TO SAVEPOINT promote_task_steering")
            conn.execute("RELEASE SAVEPOINT promote_task_steering")
            if not suppress_queue_full:
                raise
            return None
        except BaseException:
            conn.execute("ROLLBACK TO SAVEPOINT promote_task_steering")
            conn.execute("RELEASE SAVEPOINT promote_task_steering")
            raise
        conn.execute("RELEASE SAVEPOINT promote_task_steering")
        return result

    @classmethod
    def _promote_terminal_steering_predecessors_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        agent_id: str,
        agent_incarnation: int,
        conversation_id: str,
        now: str,
        max_agent_queue: int,
        max_global_queue: int,
        max_account_queue: int,
        max_account_agent_queue: int,
    ) -> int:
        """Publish older terminal-turn input before admitting newer work.

        Completion normally promotes a pending steer immediately.  If that
        promotion temporarily hit an admission limit, the durable row remains
        pending.  A later inbound in the same conversation must not acquire an
        earlier ready sequence merely because it arrived before reconciliation.
        Running this targeted repair inside the inbound transaction makes the
        older fallback win, or propagates the exact queue-limit failure so both
        the repair and newer inbound roll back together.
        """

        predecessors = conn.execute(
            """SELECT steering.target_task_id,steering.target_execution_id,
                      MIN(steering.created_at) AS first_created_at
                 FROM task_steering AS steering
                 JOIN tasks AS task
                   ON task.task_id=steering.target_task_id
                 JOIN task_executions AS execution
                   ON execution.execution_id=steering.target_execution_id
                  AND execution.task_id=steering.target_task_id
                WHERE steering.agent_id=?
                  AND steering.agent_incarnation=?
                  AND steering.conversation_id=?
                  AND steering.state='pending'
                  AND task.state NOT IN
                      ('queued','dispatching','running','cancel_requested')
                  AND execution.state NOT IN
                      ('queued','dispatching','running','cancel_requested')
                  AND execution.finished_at IS NOT NULL
                GROUP BY steering.target_task_id,
                         steering.target_execution_id
                ORDER BY MIN(steering.created_at),
                         steering.target_execution_id""",
            (str(agent_id), int(agent_incarnation), str(conversation_id)),
        ).fetchall()
        promoted = 0
        for predecessor in predecessors:
            result = cls._promote_pending_steering_for_execution_tx(
                conn,
                task_id=str(predecessor["target_task_id"]),
                execution_id=str(predecessor["target_execution_id"]),
                now=now,
                max_agent_queue=max_agent_queue,
                max_global_queue=max_global_queue,
                max_account_queue=max_account_queue,
                max_account_agent_queue=max_account_agent_queue,
                suppress_queue_full=False,
            )
            if result is None:
                # A lower delivering ordinal is still ambiguous.  Refuse to
                # let newer work overtake it; lease recovery will eventually
                # fence that delivery and make the pending tail promotable.
                raise InvalidTransition(
                    "terminal task steering predecessor is still delivering"
                )
            promoted += 1
        return promoted

    @classmethod
    def _recover_task_steering_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        now: str,
        process_boundary: bool,
        max_agent_queue: int,
        max_global_queue: int,
        max_account_queue: int,
        max_account_agent_queue: int,
        limit: int = 100,
    ) -> int:
        """Fence abandoned claims and promote terminal-target pending heads."""

        # Migration tests and interrupted-development recovery may
        # deliberately stop before schema v38 is installed. There is no
        # steering state to recover at that older boundary.
        if conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' "
            "AND name='task_steering'"
        ).fetchone() is None:
            return 0

        if process_boundary:
            conn.execute(
                """UPDATE task_steering
                      SET state='delivery_unknown',claimed_by=NULL,
                          claim_token=NULL,lease_expires_at=NULL,updated_at=?
                    WHERE state='delivering'""",
                (now,),
            )
        else:
            conn.execute(
                """UPDATE task_steering
                      SET state='delivery_unknown',claimed_by=NULL,
                          claim_token=NULL,lease_expires_at=NULL,updated_at=?
                    WHERE state='delivering' AND lease_expires_at<=?""",
                (now, now),
            )
        candidates = conn.execute(
            """SELECT pending.target_task_id,pending.target_execution_id,
                      MIN(pending.sequence) AS first_pending_sequence
                 FROM task_steering AS pending
                 JOIN tasks AS task
                   ON task.task_id=pending.target_task_id
                 JOIN task_executions AS execution
                   ON execution.execution_id=pending.target_execution_id
                  AND execution.task_id=pending.target_task_id
                WHERE pending.state='pending'
                  AND task.state NOT IN
                      ('queued','dispatching','running','cancel_requested')
                  AND execution.state NOT IN
                      ('queued','dispatching','running','cancel_requested')
                  AND execution.finished_at IS NOT NULL
                  AND NOT EXISTS (
                      SELECT 1 FROM task_steering AS delivering
                       WHERE delivering.target_task_id=pending.target_task_id
                         AND delivering.target_execution_id=
                             pending.target_execution_id
                         AND delivering.state='delivering'
                         AND delivering.sequence<pending.sequence
                  )
                GROUP BY pending.target_task_id,pending.target_execution_id
                ORDER BY MIN(pending.created_at),pending.target_execution_id
                LIMIT ?""",
            (max(0, int(limit)),),
        ).fetchall()
        promoted_count = 0
        for candidate in candidates:
            result = cls._promote_pending_steering_for_execution_tx(
                conn,
                task_id=str(candidate["target_task_id"]),
                execution_id=str(candidate["target_execution_id"]),
                now=now,
                max_agent_queue=max_agent_queue,
                max_global_queue=max_global_queue,
                max_account_queue=max_account_queue,
                max_account_agent_queue=max_account_agent_queue,
            )
            if result is not None:
                promoted_count += 1
        return promoted_count

    @classmethod
    def _fetch_task_by_dedupe_tx(cls, conn: sqlite3.Connection, dedupe_key: str | None) -> TaskRecord | None:
        if not dedupe_key:
            return None
        row = conn.execute(f"{cls._task_select_sql()} WHERE t.dedupe_key = ?", (dedupe_key,)).fetchone()
        return cls._task_from_row(row)

    @classmethod
    def _confirmation_snapshot_tx(
        cls,
        conn: sqlite3.Connection,
        candidate: sqlite3.Row,
        confirmation_id: str,
    ) -> dict[str, Any]:
        """Build the immutable task projection owned by one candidate.

        A transcription candidate is created from an inbound envelope, while
        the later ``/confirm`` command is a new message and may carry a
        completely different (or absent) input payload.  Reconstructing the
        snapshot here keeps confirmation idempotent across restarts and
        prevents a caller from replacing the original caption/media with
        command-time data.
        """

        route = {
            "channel": str(candidate["channel"] or ""),
            "bot_id": str(candidate["bot_id"] or ""),
            "external_user_id": str(candidate["external_user_id"] or ""),
            "session_id": str(candidate["session_id"] or "default") or "default",
        }
        inbound_id = (
            str(candidate["inbound_message_id"] or "")
            if "inbound_message_id" in candidate.keys()
            else ""
        )
        inbound = None
        if inbound_id:
            inbound = conn.execute(
                "SELECT * FROM inbound_messages WHERE message_id=?",
                (inbound_id,),
            ).fetchone()

        if inbound is not None:
            persisted_inbound = cls._inbound_from_row(inbound)
            original_target = persisted_inbound.target()
            identity_snapshot = dict(persisted_inbound.identity_snapshot or {})
            principal_id = persisted_inbound.principal_id
            principal_account_id = persisted_inbound.principal_account_id
            conversation_subject_id = persisted_inbound.conversation_subject_id
            actor_external_user_id = persisted_inbound.external_user_id
        else:
            # Standalone compatibility candidates predate durable inbound
            # ownership.  Give their eventual task the same direct bot-local
            # subject a normal ingress would receive, while leaving canonical
            # principal identity explicitly unmapped.
            direct_subject = direct_conversation_subject(
                route["channel"], route["bot_id"], route["external_user_id"]
            )
            conn.execute(
                """INSERT OR IGNORE INTO conversation_subjects
                       (conversation_subject_id, channel, bot_id, subject_kind,
                        scope_key, external_chat_id, external_thread_id,
                        parent_subject_id, provenance_json, created_at)
                   VALUES (?, ?, ?, 'direct', ?, '', '', NULL, ?, ?)""",
                (
                    direct_subject.conversation_subject_id,
                    direct_subject.channel,
                    direct_subject.bot_id,
                    direct_subject.scope_key,
                    json_dumps({"source": "confirmation_compatibility"}),
                    str(candidate["created_at"] or _utc_text()),
                ),
            )
            actor_external_user_id = route["external_user_id"]
            principal_id = None
            principal_account_id = None
            conversation_subject_id = direct_subject.conversation_subject_id
            identity_snapshot = {
                "actor": {
                    "channel": route["channel"],
                    "bot_id": route["bot_id"],
                    "external_user_id": actor_external_user_id,
                },
                "principal": {
                    "principal_id": None,
                    "principal_account_id": None,
                    "mapping_revision": None,
                    "source": "unmapped",
                },
                "conversation_subject": {
                    "conversation_subject_id": conversation_subject_id,
                    "kind": "direct",
                    "scope_key": direct_subject.scope_key,
                    "parent_subject_id": None,
                },
                "destination": {
                    "kind": "",
                    "id": "",
                    "thread_id": "",
                    "root_message_id": "",
                    "transport_metadata": {},
                },
            }
            original_target = ReplyTarget(**route)

        subject_snapshot = identity_snapshot.get("conversation_subject", {})
        if not isinstance(subject_snapshot, Mapping):
            subject_snapshot = {}
        conversation_route = {
            **route,
            "external_user_id": str(
                subject_snapshot.get("scope_key") or route["external_user_id"]
            ),
        }

        # Keep only normalized media references.  The inbound payload also
        # contains wire diagnostics and sender metadata which must not become
        # executable Agent input.
        inputs: dict[str, Any] = {
            "text": str(candidate["candidate_text"] or ""),
            "audio_confirmation_id": confirmation_id,
            "attachment_id": candidate["attachment_id"],
            "source": str(candidate["source"] or ""),
        }
        if inbound is not None:
            caption = str(inbound["text"] or "")
            if caption:
                inputs["caption"] = caption
            payload = json_loads(inbound["payload_json"], {}) or {}
            if isinstance(payload, Mapping):
                media = payload.get("media")
                if media:
                    inputs["media"] = list(
                        canonical_media_inputs(media, include_candidate=True)
                    )

        metadata = json_loads(
            candidate["metadata_json"] if "metadata_json" in candidate.keys() else None,
            {},
        ) or {}
        if not isinstance(metadata, Mapping):
            metadata = {}

        agent_id = str(candidate["agent_id"] or "codex")
        mode_id = str(candidate["mode_id"] or "chat")
        profile_version = int(
            candidate["profile_version"]
            if candidate["profile_version"] is not None
            else 1
        )
        policy_version = int(
            candidate["policy_version"]
            if candidate["policy_version"] is not None
            else 1
        )
        return {
            "route": route,
            "conversation_route": conversation_route,
            "inbound_id": inbound_id or None,
            "inbound_task_id": (
                str(inbound["task_id"] or "") if inbound is not None else ""
            ),
            # A candidate can be one of several audio items on the same
            # inbound envelope.  Only the first confirmed item may claim the
            # envelope's one-task FK; later candidates intentionally leave it
            # NULL.
            "expected_inbound_id": (
                inbound_id
                if inbound is not None and not str(inbound["task_id"] or "")
                else None
            ),
            "target": original_target,
            "actor_external_user_id": actor_external_user_id,
            "principal_id": principal_id,
            "principal_account_id": principal_account_id,
            "conversation_subject_id": conversation_subject_id,
            "identity_snapshot": cls._json_snapshot(identity_snapshot),
            "agent_id": agent_id,
            "mode_id": mode_id,
            "profile_version": profile_version,
            "policy_version": policy_version,
            "metadata": cls._json_snapshot(dict(metadata)),
            "inputs": cls._json_snapshot(inputs),
            "conversation_id": canonical_conversation_id(
                conversation_route["channel"],
                conversation_route["bot_id"],
                conversation_route["external_user_id"],
                conversation_route["session_id"],
                agent_id,
            ),
        }

    @classmethod
    def _validate_confirmation_task_tx(
        cls,
        conn: sqlite3.Connection,
        existing: TaskRecord,
        snapshot: Mapping[str, Any],
        confirmation_id: str,
        *,
        consumed: bool = False,
    ) -> None:
        """Fail closed when a confirmation dedupe winner is not its task.

        ``confirmation:<id>`` is an exactly-once identity, not a capability
        to retrieve an arbitrary task.  Every durable field that the
        candidate owns is compared before the candidate can be consumed.
        """

        route = snapshot["route"]
        conversation_route = snapshot.get("conversation_route", route)
        raw = conn.execute(
            "SELECT channel, bot_id, external_user_id, session_id, inbound_message_id, "
            "actor_external_user_id, principal_id, principal_account_id, "
            "conversation_subject_id, identity_snapshot_json "
            "FROM tasks WHERE task_id=?",
            (existing.task_id,),
        ).fetchone()
        if raw is None:
            raise StoreError("confirmation task disappeared")
        for field in ("channel", "bot_id", "external_user_id", "session_id"):
            expected = str(route.get(field) or ("default" if field == "session_id" else ""))
            actual = str(getattr(existing.reply_target, field, "") or "")
            if actual != expected:
                raise StoreError(
                    f"confirmation task identity conflicts ({field})"
                )
            expected_conversation = str(
                conversation_route.get(field)
                or ("default" if field == "session_id" else "")
            )
            stored = str(raw[field] or ("default" if field == "session_id" else ""))
            if stored != expected_conversation:
                raise StoreError(
                    f"confirmation task identity conflicts ({field})"
                )

        if str(existing.agent_id or "") != str(snapshot["agent_id"]):
            raise StoreError("confirmation task identity conflicts (agent_id)")
        if str(existing.mode_id or "") != str(snapshot["mode_id"]):
            raise StoreError("confirmation task identity conflicts (mode_id)")
        if int(existing.profile_version) != int(snapshot["profile_version"]):
            raise StoreError("confirmation task identity conflicts (profile_version)")
        if int(existing.policy_version) != int(snapshot["policy_version"]):
            raise StoreError("confirmation task identity conflicts (policy_version)")
        if not conversation_id_matches(
            existing.conversation_id,
            conversation_route["channel"],
            conversation_route["bot_id"],
            conversation_route["external_user_id"],
            conversation_route["session_id"],
            snapshot["agent_id"],
        ):
            raise StoreError("confirmation task identity conflicts (conversation_id)")
        if str(existing.dedupe_key or "") != f"confirmation:{confirmation_id}":
            raise StoreError("confirmation task identity conflicts (dedupe_key)")

        expected_target = cls._reply_target_snapshot(snapshot["target"].to_dict())
        actual_target = cls._reply_target_snapshot(existing.reply_target.to_dict())
        # ``context_token`` is a rolling transport hint.  It is deliberately
        # excluded from the identity comparison, just as it is for inbound
        # replay validation.
        if isinstance(expected_target, Mapping):
            expected_target = dict(expected_target)
            expected_target.pop("context_token", None)
        if isinstance(actual_target, Mapping):
            actual_target = dict(actual_target)
            actual_target.pop("context_token", None)
        if cls._json_snapshot(actual_target) != cls._json_snapshot(expected_target):
            raise StoreError("confirmation task identity conflicts (reply_target)")

        if cls._json_snapshot(existing.inputs) != cls._json_snapshot(snapshot["inputs"]):
            raise StoreError("confirmation task identity conflicts (inputs)")
        if cls._json_snapshot(existing.metadata) != cls._json_snapshot(snapshot["metadata"]):
            raise StoreError("confirmation task identity conflicts (metadata)")
        for field in (
            "actor_external_user_id",
            "principal_id",
            "principal_account_id",
            "conversation_subject_id",
        ):
            expected_identity = snapshot.get(field)
            if str(raw[field] or "") != str(expected_identity or ""):
                raise StoreError(
                    f"confirmation task identity conflicts ({field})"
                )
        if cls._json_snapshot(
            json_loads(raw["identity_snapshot_json"], {}) or {}
        ) != cls._json_snapshot(snapshot.get("identity_snapshot", {})):
            raise StoreError(
                "confirmation task identity conflicts (identity_snapshot)"
            )

        # A confirmed task is never a child task.  For a multi-candidate
        # inbound, only the first candidate may claim the inbound FK; a replay
        # may therefore legitimately have either no link or this envelope's
        # link, but never a different envelope.
        if existing.parent_task_id is not None or int(existing.child_depth or 0) != 0:
            raise StoreError("confirmation task identity conflicts (parent)")
        if consumed and snapshot.get("inbound_id"):
            if raw["inbound_message_id"] not in (None, snapshot["inbound_id"]):
                raise StoreError("confirmation task identity conflicts (inbound)")
        elif not consumed and raw["inbound_message_id"] != snapshot.get(
            "expected_inbound_id"
        ):
            raise StoreError("confirmation task identity conflicts (inbound)")

    @staticmethod
    def _validate_dedupe_owner(
        existing: TaskRecord,
        *,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
        agent_id: str,
        parent_task_id: str | None,
        conversation_id: str | None = None,
    ) -> None:
        """Reject reuse of a logical dedupe key across ownership scopes.

        A unique key prevents duplicate execution, but by itself it does not
        prevent an untrusted caller from asking for another user's existing
        task.  Mode/policy are intentionally excluded: a replay after a
        control-plane change must return the original immutable task snapshot.
        """

        target = existing.reply_target
        expected = {
            "channel": channel,
            "bot_id": bot_id,
            "external_user_id": external_user_id,
            "session_id": session_id or "default",
        }
        for field, value in expected.items():
            actual = getattr(target, field)
            if str(actual or "") != str(value or ""):
                raise StoreError(f"dedupe key conflicts with task ownership ({field})")
        if str(existing.agent_id or "") != str(agent_id or ""):
            raise StoreError("dedupe key conflicts with task ownership (agent_id)")
        if conversation_id and str(existing.conversation_id) != str(conversation_id):
            if not conversation_id_matches(
                existing.conversation_id,
                channel,
                bot_id,
                external_user_id,
                session_id,
                agent_id,
            ) or not conversation_id_matches(
                conversation_id,
                channel,
                bot_id,
                external_user_id,
                session_id,
                agent_id,
            ):
                raise StoreError("dedupe key conflicts with task conversation")
        # A child request is owned by its exact parent.  Route identity alone
        # is insufficient because two tasks for the same Agent conversation
        # could otherwise reuse one dedupe key and charge the child to the
        # wrong parent's admission counter.
        if str(existing.parent_task_id or "") != str(parent_task_id or ""):
            raise StoreError("dedupe key conflicts with child-task parent")

    @classmethod
    def _validate_child_parent_tx(
        cls,
        conn: sqlite3.Connection,
        task: AgentTask,
        *,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
    ) -> str | None:
        """Validate a child snapshot against its durable parent.

        ``tasks.parent_task_id`` is intentionally a logical relationship (the
        schema cannot use a foreign key without making task history deletion
        destructive).  Every insertion path therefore performs the same
        existence, route-ownership, and depth checks before writing the child.
        The child Agent may differ from the parent; the manager's policy layer
        authorizes that cross-Agent delegation before reaching the store.
        """

        parent_id = str(task.parent_task_id or "")
        if not parent_id:
            return None
        parent = conn.execute(
            "SELECT task_id, channel, bot_id, external_user_id, session_id, "
            "child_depth FROM tasks WHERE task_id=?",
            (parent_id,),
        ).fetchone()
        if parent is None:
            raise NotFoundError(f"parent task not found: {parent_id}")
        expected_scope = {
            "channel": str(channel or ""),
            "bot_id": str(bot_id or ""),
            "external_user_id": str(external_user_id or ""),
            "session_id": str(session_id or "default"),
        }
        for field, expected in expected_scope.items():
            actual = str(parent[field] or ("default" if field == "session_id" else ""))
            if actual != expected:
                raise StoreError(
                    f"child task parent conflicts with ownership ({field})"
                )
        try:
            child_depth = int(task.child_depth)
        except (TypeError, ValueError) as exc:
            raise StoreError("invalid child-task depth") from exc
        expected_depth = int(parent["child_depth"] or 0) + 1
        if child_depth != expected_depth:
            raise StoreError(
                "child-task depth does not follow parent depth "
                f"({expected_depth})"
            )
        return parent_id

    @classmethod
    def _update_child_counter_tx(
        cls,
        conn: sqlite3.Connection,
        parent_task_id: str,
        *,
        now: str,
    ) -> None:
        """Persist a counter that never undercounts durable child rows."""

        durable_count = int(
            conn.execute(
                "SELECT COUNT(*) FROM tasks WHERE parent_task_id=?",
                (parent_task_id,),
            ).fetchone()[0]
        )
        counter = conn.execute(
            "SELECT child_count FROM child_task_counters WHERE parent_task_id=?",
            (parent_task_id,),
        ).fetchone()
        counter_count = int(counter["child_count"]) if counter else 0
        conn.execute(
            """INSERT INTO child_task_counters
               (parent_task_id, child_count, updated_at)
               VALUES (?, ?, ?)
               ON CONFLICT(parent_task_id)
               DO UPDATE SET child_count=excluded.child_count,
                             updated_at=excluded.updated_at""",
            (parent_task_id, max(counter_count, durable_count), now),
        )

    @staticmethod
    def _mapping_snapshot(value: Any) -> dict[str, Any]:
        """Normalize a profile/mode/policy object without importing registries."""
        if value is None:
            return {}
        if isinstance(value, Mapping):
            return dict(value)
        for name in ("as_dict", "to_dict"):
            method = getattr(value, name, None)
            if method is None:
                continue
            try:
                converted = method()
            except TypeError:
                converted = None
            if isinstance(converted, Mapping):
                return dict(converted)
        fields = getattr(value, "__dataclass_fields__", {})
        if fields:
            return {name: getattr(value, name) for name in fields if hasattr(value, name)}
        return {}

    @classmethod
    def _json_snapshot(cls, value: Any) -> Any:
        """Make set/tuple-heavy registry values deterministic JSON values."""
        if isinstance(value, Mapping):
            return {str(key): cls._json_snapshot(item) for key, item in value.items()}
        if isinstance(value, (set, frozenset)):
            return sorted(cls._json_snapshot(item) for item in value)
        if isinstance(value, (tuple, list)):
            return [cls._json_snapshot(item) for item in value]
        return value

    @staticmethod
    def _string_set_json_snapshot(value: Any) -> frozenset[str] | None:
        """Decode one immutable set-valued JSON column without laundering it.

        Profile ACL/capability values and Mode tool values are public
        ``frozenset`` fields.  Older rows can therefore contain a different
        JSON array order from the canonical order emitted by the current
        dataclasses even though they describe the same immutable value.  Keep
        accepting only arrays of strings; malformed JSON, objects, and mixed
        arrays must still conflict rather than being treated as an empty set.
        """

        try:
            decoded = json.loads(value)
        except (TypeError, ValueError):
            return None
        if not isinstance(decoded, list) or not all(
            isinstance(item, str) for item in decoded
        ):
            return None
        return frozenset(decoded)

    @classmethod
    def _definition_metadata_equal(
        cls,
        column: str,
        actual: Any,
        expected: Any,
    ) -> bool:
        """Compare one Profile/Mode field according to its public semantics."""

        if column in {
            "capabilities_json",
            "allowed_peers_json",
            "denied_peers_json",
            "allowed_request_types_json",
            "denied_request_types_json",
            "allowed_tools_json",
            "denied_tools_json",
        }:
            actual_set = cls._string_set_json_snapshot(actual)
            expected_set = cls._string_set_json_snapshot(expected)
            return actual_set is not None and actual_set == expected_set
        if column.endswith("_json"):
            return cls._json_snapshot(json_loads(actual, [])) == cls._json_snapshot(
                json_loads(expected, [])
            )
        return str(actual) == str(expected)

    @classmethod
    def _reply_target_snapshot(cls, value: Any) -> Any:
        """Canonicalize a reply target for durable identity checks.

        A channel context token is a rolling transport hint.  It can change
        when the same inbound message is replayed after reconnecting, so it
        must not make an otherwise identical outbox projection conflict.
        Keep the helper local to the store boundary and accept both naming
        conventions used by channel payloads and older schemas.
        """

        snapshot = cls._json_snapshot(value)
        if not isinstance(snapshot, Mapping):
            return snapshot
        snapshot = dict(snapshot)
        snapshot.pop("context_token", None)
        snapshot.pop("contextToken", None)
        if str(snapshot.get("channel") or "").lower() == "wechat":
            for field in (
                "conversation_subject_id",
                "conversation_subject_scope",
                "destination_kind",
                "destination_id",
                "thread_id",
                "root_message_id",
                "transport_metadata",
            ):
                snapshot.pop(field, None)
        return snapshot

    @classmethod
    def _profile_snapshot_values(
        cls,
        *,
        agent_id: str,
        profile_version: int,
        snapshot: Any,
    ) -> tuple[dict[str, Any], bool]:
        data = cls._mapping_snapshot(snapshot)
        if data:
            snapshot_agent = str(data.get("agent_id", agent_id) or agent_id)
            snapshot_version = int(data.get("profile_version", data.get("version", profile_version)))
            if snapshot_agent != str(agent_id) or snapshot_version != int(profile_version):
                raise StoreError("profile snapshot does not match task ownership")
        def j(name: str, default: Any = ()) -> str:
            return json_dumps(cls._json_snapshot(data.get(name, default)))
        from .policy import normalize_codex_config_profile

        return (
            {
                "display_name": str(data.get("display_name", agent_id) or ""),
                "summary": str(data.get("summary", "") or ""),
                "system_prompt": str(data.get("system_prompt", "") or ""),
                "responsibilities_json": j("responsibilities"),
                "constraints_json": j("constraints"),
                "capabilities_json": j("capabilities"),
                "allowed_peers_json": j("allowed_peers"),
                "denied_peers_json": j("denied_peers"),
                "allowed_request_types_json": j("allowed_request_types"),
                "denied_request_types_json": j("denied_request_types"),
                "max_child_depth": int(data.get("max_child_depth", 0) or 0),
                "max_children_per_task": int(data.get("max_children_per_task", 0) or 0),
                "enabled": int(bool(data.get("enabled", True))),
                "default_mode_id": str(data.get("default_mode_id", "chat") or "chat"),
                "codex_config_profile": normalize_codex_config_profile(
                    data.get("codex_config_profile", "")
                ),
            },
            bool(data),
        )

    @classmethod
    def _mode_snapshot_values(
        cls,
        *,
        agent_id: str,
        mode_id: str,
        policy_version: int,
        snapshot: Any,
    ) -> tuple[dict[str, Any], bool]:
        data = cls._mapping_snapshot(snapshot)
        if data:
            snapshot_mode = str(data.get("mode_id", mode_id) or mode_id)
            snapshot_version = int(
                data.get("policy_version", data.get("mode_policy_version", policy_version))
            )
            if snapshot_mode != str(mode_id) or snapshot_version != int(policy_version):
                raise StoreError("mode snapshot does not match task ownership")
        sandbox = str(data.get("sandbox_policy", "read-only") or "read-only").replace("-", "_")
        return (
            {
                "developer_instructions": str(data.get("developer_instructions", "") or ""),
                "sandbox_policy": sandbox,
                "approval_policy": str(data.get("approval_policy", "deny_all") or "deny_all"),
                "allowed_tools_json": json_dumps(cls._json_snapshot(data.get("allowed_tools", ()))),
                "denied_tools_json": json_dumps(cls._json_snapshot(data.get("denied_tools", ()))),
                "can_write_files": int(bool(data.get("can_write_files", False))),
                "can_execute_commands": int(bool(data.get("can_execute_commands", False))),
                "can_create_child_tasks": int(bool(data.get("can_create_child_tasks", False))),
                "can_send_agent_messages": int(bool(data.get("can_send_agent_messages", False))),
            },
            bool(data),
        )

    @staticmethod
    def _legacy_profile_placeholder(row: sqlite3.Row, *, agent_id: str, profile_version: int) -> bool:
        """Recognize rows written by the pre-snapshot Codex seed only."""
        if str(agent_id) != "codex" or int(profile_version) != 1:
            return False
        return (
            str(row["display_name"] or "") in {"", "codex", "Codex"}
            and str(row["summary"] or "") in {"", "Codex runtime"}
            and not str(row["system_prompt"] or "")
            and all(
                json_loads(row[name], []) in ([], {})
                for name in (
                    "responsibilities_json",
                    "constraints_json",
                    "capabilities_json",
                    "allowed_peers_json",
                    "denied_peers_json",
                    "allowed_request_types_json",
                    "denied_request_types_json",
                )
            )
            and int(row["max_child_depth"] or 0) == 0
            and int(row["max_children_per_task"] or 0) == 0
            and int(row["enabled"] or 0) == 1
            and str(row["default_mode_id"] or "") == "chat"
            and str(row["codex_config_profile"] or "") == ""
        )

    @staticmethod
    def _legacy_mode_placeholder(
        row: sqlite3.Row, *, agent_id: str, mode_id: str, policy_version: int
    ) -> bool:
        """Recognize the exact pre-snapshot rows for built-in Codex modes."""

        if (
            str(agent_id) != "codex"
            or str(mode_id) not in {"chat", "plan", "review", "execute"}
            or int(policy_version) != 1
        ):
            return False
        return (
            not str(row["developer_instructions"] or "")
            and str(row["sandbox_policy"] or "") == "read_only"
            and str(row["approval_policy"] or "") == "deny_all"
            and json_loads(row["allowed_tools_json"], []) == []
            and json_loads(row["denied_tools_json"], []) == []
            and not any(
                bool(row[column])
                for column in (
                    "can_write_files",
                    "can_execute_commands",
                    "can_create_child_tasks",
                    "can_send_agent_messages",
                )
            )
        )

    @classmethod
    def _interim_execute_v1_snapshot(cls, row: sqlite3.Row) -> bool:
        """Recognize the short-lived full-access rewrite of execute@1.

        That release changed an already-published immutable row and then
        failed on its next startup. Repair only the exact known built-in
        snapshot; arbitrary conflicts remain fail-closed.
        """

        from .modes import legacy_builtin_modes

        canonical = legacy_builtin_modes()["execute"]
        values, _ = cls._mode_snapshot_values(
            agent_id="codex",
            mode_id="execute",
            policy_version=1,
            snapshot=canonical,
        )

        for column, expected in values.items():
            actual = row[column]
            if column == "sandbox_policy":
                if str(actual or "") != "full_access":
                    return False
            elif column in {"allowed_tools_json", "denied_tools_json"}:
                actual_tools = cls._string_set_json_snapshot(actual)
                expected_tools = cls._string_set_json_snapshot(expected)
                if actual_tools is None or actual_tools != expected_tools:
                    return False
            elif str(actual) != str(expected):
                return False
        return True

    @classmethod
    def _ensure_profile_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        agent_id: str,
        profile_version: int,
        snapshot: Any = None,
        now: str,
        allow_legacy_seed_upgrade: bool = False,
    ) -> None:
        values, supplied = cls._profile_snapshot_values(
            agent_id=agent_id, profile_version=int(profile_version), snapshot=snapshot
        )
        row = conn.execute(
            "SELECT * FROM agent_profiles WHERE agent_id=? AND profile_version=?",
            (agent_id, int(profile_version)),
        ).fetchone()
        if row is not None:
            if supplied:
                mismatches = []
                for column, expected in values.items():
                    actual = row[column]
                    if not cls._definition_metadata_equal(
                        column, actual, expected
                    ):
                        mismatches.append(column)
                if mismatches:
                    if (
                        allow_legacy_seed_upgrade
                        and cls._legacy_profile_placeholder(
                            row,
                            agent_id=agent_id,
                            profile_version=int(profile_version),
                        )
                    ):
                        assignments = ", ".join(f"{column}=?" for column in values)
                        conn.execute(
                            f"UPDATE agent_profiles SET {assignments} WHERE agent_id=? AND profile_version=?",
                            [*values.values(), agent_id, int(profile_version)],
                        )
                    else:
                        raise StoreError(
                            f"profile version metadata conflicts: {agent_id}@{profile_version}"
                        )
            return
        conn.execute(
            """INSERT INTO agent_profiles
               (agent_id, profile_version, display_name, summary, system_prompt,
                responsibilities_json, constraints_json, capabilities_json,
                allowed_peers_json, denied_peers_json, allowed_request_types_json,
                denied_request_types_json, max_child_depth, max_children_per_task,
                enabled, default_mode_id, codex_config_profile, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                agent_id,
                int(profile_version),
                values["display_name"],
                values["summary"],
                values["system_prompt"],
                values["responsibilities_json"],
                values["constraints_json"],
                values["capabilities_json"],
                values["allowed_peers_json"],
                values["denied_peers_json"],
                values["allowed_request_types_json"],
                values["denied_request_types_json"],
                values["max_child_depth"],
                values["max_children_per_task"],
                values["enabled"],
                values["default_mode_id"],
                values["codex_config_profile"],
                now,
            ),
        )

    @classmethod
    def _ensure_mode_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        agent_id: str,
        mode_id: str,
        policy_version: int,
        snapshot: Any = None,
        now: str,
        allow_legacy_seed_upgrade: bool = False,
    ) -> None:
        values, supplied = cls._mode_snapshot_values(
            agent_id=agent_id,
            mode_id=mode_id,
            policy_version=int(policy_version),
            snapshot=snapshot,
        )
        row = conn.execute(
            "SELECT * FROM agent_modes WHERE agent_id=? AND mode_id=? AND policy_version=?",
            (agent_id, mode_id, int(policy_version)),
        ).fetchone()
        if row is not None:
            if supplied:
                for column, expected in values.items():
                    actual = row[column]
                    equal = cls._definition_metadata_equal(
                        column, actual, expected
                    )
                    if not equal:
                        if (
                            allow_legacy_seed_upgrade
                            and (
                                cls._legacy_mode_placeholder(
                                    row,
                                    agent_id=agent_id,
                                    mode_id=mode_id,
                                    policy_version=int(policy_version),
                                )
                                or (
                                    str(agent_id) == "codex"
                                    and str(mode_id) == "execute"
                                    and int(policy_version) == 1
                                    and cls._interim_execute_v1_snapshot(row)
                                )
                            )
                        ):
                            assignments = ", ".join(f"{column}=?" for column in values)
                            conn.execute(
                                f"UPDATE agent_modes SET {assignments} WHERE agent_id=? AND mode_id=? AND policy_version=?",
                                [*values.values(), agent_id, mode_id, int(policy_version)],
                            )
                            break
                        raise StoreError(
                            f"mode version metadata conflicts: {agent_id}/{mode_id}@{policy_version}"
                        )
            return
        conn.execute(
            """INSERT INTO agent_modes
               (agent_id, mode_id, policy_version, developer_instructions,
                sandbox_policy, approval_policy, allowed_tools_json, denied_tools_json,
                can_write_files, can_execute_commands, can_create_child_tasks,
                can_send_agent_messages, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                agent_id,
                mode_id,
                int(policy_version),
                values["developer_instructions"],
                values["sandbox_policy"],
                values["approval_policy"],
                values["allowed_tools_json"],
                values["denied_tools_json"],
                values["can_write_files"],
                values["can_execute_commands"],
                values["can_create_child_tasks"],
                values["can_send_agent_messages"],
                now,
            ),
        )

    @classmethod
    def _ensure_profile_mode_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        agent_id: str,
        profile_version: int,
        mode_id: str,
        policy_version: int,
        now: str,
        metadata: Any = None,
        profile_snapshot: Any = None,
        mode_snapshot: Any = None,
    ) -> None:
        metadata_map = cls._mapping_snapshot(metadata)
        profile_snapshot = profile_snapshot or metadata_map.get("profile") or metadata_map.get("agent_profile")
        mode_snapshot = mode_snapshot or metadata_map.get("mode")
        if mode_snapshot is None:
            effective = cls._mapping_snapshot(metadata_map.get("effective_policy"))
            if effective:
                mode_snapshot = {
                    "mode_id": mode_id,
                    "policy_version": effective.get("mode_policy_version", policy_version),
                    **{
                        key: effective[key]
                        for key in (
                            "developer_instructions",
                            "sandbox_policy",
                            "approval_policy",
                            "allowed_tools",
                            "denied_tools",
                            "can_write_files",
                            "can_execute_commands",
                            "can_create_child_tasks",
                            "can_send_agent_messages",
                        )
                        if key in effective
                    },
                }
        cls._ensure_profile_tx(
            conn,
            agent_id=agent_id,
            profile_version=int(profile_version),
            snapshot=profile_snapshot,
            now=now,
        )
        cls._project_profile_lifecycle_tx(
            conn,
            agent_id=agent_id,
            profile_version=int(profile_version),
            now_text=now,
            source_kind="task_profile_materialization",
            source_id=compound_id(
                "agent-lifecycle-source",
                ("task-profile", agent_id, int(profile_version)),
            ),
            provenance={"compatibility_path": "ensure_profile_mode"},
        )
        cls._ensure_mode_tx(
            conn,
            agent_id=agent_id,
            mode_id=mode_id,
            policy_version=int(policy_version),
            snapshot=mode_snapshot,
            now=now,
        )

    @classmethod
    def _ensure_transport_conversation_tx(
        cls,
        conn: sqlite3.Connection,
        task: AgentTask,
        *,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
        now: str,
    ) -> str:
        session_id = session_id or "default"
        conversation_id = task.conversation_id
        if not conversation_id:
            conversation_id = canonical_conversation_id(
                channel, bot_id, external_user_id, session_id, task.agent_id
            )
        cls._ensure_profile_mode_tx(
            conn,
            agent_id=task.agent_id,
            profile_version=task.profile_version,
            mode_id=task.mode_id,
            policy_version=task.policy_version,
            now=now,
            metadata=task.metadata,
        )
        existing = conn.execute(
            "SELECT channel, bot_id, external_user_id, session_id, agent_id, mode_id, "
            "profile_version, policy_version, conversation_subject_id "
            "FROM conversations WHERE conversation_id=?",
            (conversation_id,),
        ).fetchone()
        if existing is not None:
            immutable = {
                "channel": channel,
                "bot_id": bot_id,
                "external_user_id": external_user_id,
                "session_id": session_id,
                "agent_id": task.agent_id,
            }
            for column, expected in immutable.items():
                if str(existing[column]) != str(expected):
                    raise StoreError(
                        f"conversation identity conflicts: {conversation_id} ({column})"
                    )
            supplied_subject = str(task.conversation_subject_id or "").strip()
            stored_subject = str(existing["conversation_subject_id"] or "").strip()
            if supplied_subject and stored_subject and supplied_subject != stored_subject:
                raise StoreError(
                    f"conversation identity conflicts: {conversation_id} "
                    "(conversation_subject_id)"
                )
            if supplied_subject and not stored_subject:
                conn.execute(
                    "UPDATE conversations SET conversation_subject_id=? "
                    "WHERE conversation_id=? AND conversation_subject_id IS NULL",
                    (supplied_subject, conversation_id),
                )
            return conversation_id
        candidate_ids = conversation_id_candidates(
            channel, bot_id, external_user_id, session_id, task.agent_id
        )
        canonical_id = candidate_ids[0]
        legacy_id = candidate_ids[-1]
        if conversation_id == canonical_id and legacy_id != canonical_id:
            legacy = conn.execute(
                "SELECT channel, bot_id, external_user_id, session_id, agent_id, "
                "mode_id, profile_version, policy_version "
                "FROM conversations WHERE conversation_id=?",
                (legacy_id,),
            ).fetchone()
            if legacy is not None:
                immutable = {
                    "channel": channel,
                    "bot_id": bot_id,
                    "external_user_id": external_user_id,
                    "session_id": session_id,
                    "agent_id": task.agent_id,
                }
                if all(
                    str(legacy[column]) == str(expected)
                    for column, expected in immutable.items()
                ):
                    return legacy_id
        conn.execute(
            """INSERT OR IGNORE INTO conversations
               (conversation_id, channel, bot_id, external_user_id, session_id,
                agent_id, mode_id, profile_version, policy_version, thread_id,
                created_at, updated_at, conversation_subject_id)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                conversation_id,
                channel,
                bot_id,
                external_user_id,
                session_id,
                task.agent_id,
                task.mode_id,
                int(task.profile_version),
                int(task.policy_version),
                task.thread_id,
                now,
                now,
                task.conversation_subject_id,
            ),
        )
        # ``INSERT OR IGNORE`` can only lose a race after the validation above;
        # re-read and fail closed if another writer inserted a different scope.
        created = conn.execute(
            "SELECT channel, bot_id, external_user_id, session_id, agent_id, mode_id, "
            "profile_version, policy_version, conversation_subject_id "
            "FROM conversations WHERE conversation_id=?",
            (conversation_id,),
        ).fetchone()
        if created is None:
            raise StoreError("conversation insert failed")
        for column, expected in {
            "channel": channel,
            "bot_id": bot_id,
            "external_user_id": external_user_id,
            "session_id": session_id,
            "agent_id": task.agent_id,
        }.items():
            if str(created[column]) != str(expected):
                raise StoreError(f"conversation identity conflicts: {conversation_id} ({column})")
        return conversation_id

    @staticmethod
    def _verified_direct_principal_tx(
        conn: sqlite3.Connection,
        task: AgentTask,
        *,
        channel: str,
        bot_id: str,
        external_user_id: str,
    ) -> str | None:
        """Return a store-proven principal only for an exact direct account."""

        principal_id = str(task.principal_id or "").strip()
        account_id = str(task.principal_account_id or "").strip()
        actor_id = str(task.actor_external_user_id or "").strip()
        if not principal_id and not account_id:
            return None
        if not principal_id or not account_id or not actor_id:
            raise StoreError("task principal identity is incomplete")
        mapping = conn.execute(
            """SELECT pa.principal_id, pa.principal_account_id
                 FROM principal_accounts AS pa
                 JOIN principals AS p ON p.principal_id=pa.principal_id
                WHERE pa.channel=? AND pa.bot_id=? AND pa.external_user_id=?
                  AND pa.active=1 AND p.enabled=1""",
            (str(channel), str(bot_id), actor_id),
        ).fetchone()
        if mapping is None or (
            str(mapping["principal_id"]) != principal_id
            or str(mapping["principal_account_id"]) != account_id
        ):
            raise StoreError(
                "task principal does not match the authenticated account mapping"
            )
        # Group and thread routes intentionally use a chat/topic scope instead
        # of the actor.  Requiring the exact actor here prevents a mapped user
        # from carrying private history into either shared subject.
        if str(external_user_id) != actor_id:
            return None
        subject_id = str(task.conversation_subject_id or "").strip()
        if not subject_id:
            return None
        subject = conn.execute(
            """SELECT subject_kind, channel, bot_id, scope_key
                 FROM conversation_subjects
                WHERE conversation_subject_id=?""",
            (subject_id,),
        ).fetchone()
        if subject is None:
            raise StoreError("task conversation subject is unavailable")
        if (
            str(subject["subject_kind"]) != "direct"
            or str(subject["channel"]) != str(channel)
            or str(subject["bot_id"]) != str(bot_id)
            or str(subject["scope_key"]) != actor_id
        ):
            return None
        return principal_id

    @classmethod
    def _ensure_principal_conversation_binding_tx(
        cls,
        conn: sqlite3.Connection,
        task: AgentTask,
        *,
        principal_id: str,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
        now: str,
    ) -> str:
        """Resolve or create one canonical provider-history anchor."""

        session_value = str(session_id or "default")
        existing = conn.execute(
            """SELECT conversation_id
                 FROM principal_conversation_bindings
                WHERE principal_id=? AND agent_id=? AND session_id=?""",
            (principal_id, task.agent_id, session_value),
        ).fetchone()
        if existing is not None:
            anchor = str(existing["conversation_id"])
            row = conn.execute(
                "SELECT agent_id, session_id FROM conversations "
                "WHERE conversation_id=?",
                (anchor,),
            ).fetchone()
            if row is None or (
                str(row["agent_id"]) != str(task.agent_id)
                or str(row["session_id"]) != session_value
            ):
                raise StoreError("principal conversation anchor is invalid")
            return anchor

        anchor = principal_conversation_id(
            principal_id,
            session_value,
            task.agent_id,
        )
        row = conn.execute(
            "SELECT agent_id, session_id FROM conversations WHERE conversation_id=?",
            (anchor,),
        ).fetchone()
        if row is None:
            conn.execute(
                """INSERT INTO conversations
                       (conversation_id, channel, bot_id, external_user_id,
                        session_id, agent_id, mode_id, profile_version,
                        policy_version, thread_id, created_at, updated_at,
                        conversation_subject_id)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    anchor,
                    str(channel),
                    str(bot_id),
                    str(external_user_id),
                    session_value,
                    str(task.agent_id),
                    str(task.mode_id),
                    int(task.profile_version),
                    int(task.policy_version),
                    task.thread_id,
                    now,
                    now,
                    task.conversation_subject_id,
                ),
            )
        elif (
            str(row["agent_id"]) != str(task.agent_id)
            or str(row["session_id"]) != session_value
        ):
            raise StoreError("principal conversation identity conflicts")
        try:
            conn.execute(
                """INSERT INTO principal_conversation_bindings
                       (principal_id, agent_id, session_id, conversation_id,
                        binding_kind, configured_by, created_at)
                   VALUES (?, ?, ?, ?, 'canonical',
                           'runtime:verified-principal', ?)""",
                (
                    principal_id,
                    str(task.agent_id),
                    session_value,
                    anchor,
                    now,
                ),
            )
        except sqlite3.IntegrityError as exc:
            raise StoreError("principal conversation binding conflicts") from exc
        return anchor

    @classmethod
    def _ensure_conversation_tx(
        cls,
        conn: sqlite3.Connection,
        task: AgentTask,
        *,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
        now: str,
    ) -> str:
        """Ensure transport provenance, then select trusted provider history."""

        session_value = str(session_id or "default")
        principal_id = cls._verified_direct_principal_tx(
            conn,
            task,
            channel=channel,
            bot_id=bot_id,
            external_user_id=external_user_id,
        )
        if principal_id is None:
            return cls._ensure_transport_conversation_tx(
                conn,
                task,
                channel=channel,
                bot_id=bot_id,
                external_user_id=external_user_id,
                session_id=session_value,
                now=now,
            )

        binding = conn.execute(
            """SELECT conversation_id
                 FROM principal_conversation_bindings
                WHERE principal_id=? AND agent_id=? AND session_id=?""",
            (principal_id, task.agent_id, session_value),
        ).fetchone()
        anchor = str(binding["conversation_id"]) if binding is not None else ""
        local_candidates = conversation_id_candidates(
            channel,
            bot_id,
            external_user_id,
            session_value,
            task.agent_id,
        )
        requested = str(task.conversation_id or "").strip()
        if requested and requested not in {*local_candidates, anchor}:
            raise StoreError(
                "principal task conversation conflicts with its transport scope"
            )
        local_requested = (
            requested if requested in local_candidates else local_candidates[0]
        )
        local_task = cls._coerce_task(
            task,
            {"conversation_id": local_requested},
        )
        cls._ensure_transport_conversation_tx(
            conn,
            local_task,
            channel=channel,
            bot_id=bot_id,
            external_user_id=external_user_id,
            session_id=session_value,
            now=now,
        )
        return cls._ensure_principal_conversation_binding_tx(
            conn,
            task,
            principal_id=principal_id,
            channel=channel,
            bot_id=bot_id,
            external_user_id=external_user_id,
            session_id=session_value,
            now=now,
        )

    @staticmethod
    def _role_snapshot_from_row(row: sqlite3.Row) -> dict[str, Any]:
        """Rebuild and verify one immutable session-role database row."""

        try:
            snapshot = build_role_snapshot(
                role_version=row["role_version"],
                normalization_version=str(row["normalization_version"]),
                kind=str(row["kind"]),
                normalized_content=row["normalized_content"],
                persona_composition_version=str(
                    row["persona_composition_version"]
                ),
            )
        except RoleValidationError as exc:
            raise StoreError("stored session role is invalid") from exc
        if (
            str(row["content_hash"] or "") != snapshot["content_hash"]
            or str(row["snapshot_hash"] or "") != snapshot["snapshot_hash"]
        ):
            raise StoreError("stored session role hash conflicts")
        return snapshot

    @classmethod
    def _task_role_snapshot_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        metadata: Any,
        channel: str,
        bot_id: str,
        external_user_id: str,
        session_id: str,
        agent_id: str,
    ) -> dict[str, Any]:
        """Validate a task's pinned role and its referenced immutable row.

        Missing metadata is the v19 compatibility form and maps to the exact
        implicit-default snapshot.  An explicit positive version must match
        the role row in this task's user/session/Agent scope byte for byte.
        """

        metadata_map = metadata if isinstance(metadata, Mapping) else {}
        if "session_role" not in metadata_map:
            snapshot = dict(_IMPLICIT_DEFAULT_ROLE)
        else:
            raw = metadata_map["session_role"]
            try:
                snapshot = validate_role_snapshot(raw)
            except RoleValidationError as exc:
                raise StoreError("task session role snapshot is invalid") from exc
        scope = (
            str(channel or ""),
            str(bot_id or ""),
            str(external_user_id or ""),
            str(session_id or "default"),
            str(agent_id or ""),
        )
        if int(snapshot["role_version"]) == 0:
            if snapshot != _IMPLICIT_DEFAULT_ROLE:
                raise StoreError("task implicit session role conflicts")
            conn.execute(
                """INSERT OR IGNORE INTO session_agent_roles (
                       channel, bot_id, external_user_id, session_id, agent_id,
                       role_version, normalization_version, kind,
                       normalized_content, content_hash,
                       persona_composition_version, snapshot_hash,
                       created_by, created_at
                   ) VALUES (?, ?, ?, ?, ?, 0, ?, 'default', '', ?, ?, ?, NULL, NULL)""",
                (
                    *scope,
                    snapshot["normalization_version"],
                    snapshot["content_hash"],
                    snapshot["persona_composition_version"],
                    snapshot["snapshot_hash"],
                ),
            )
            stored_row = conn.execute(
                """SELECT * FROM session_agent_roles
                   WHERE channel=? AND bot_id=? AND external_user_id=?
                     AND session_id=? AND agent_id=? AND role_version=0""",
                scope,
            ).fetchone()
            if stored_row is None or cls._role_snapshot_from_row(
                stored_row
            ) != snapshot:
                raise StoreError("task implicit session role row conflicts")
            return snapshot
        row = conn.execute(
            """SELECT * FROM session_agent_roles
               WHERE channel=? AND bot_id=? AND external_user_id=?
                 AND session_id=? AND agent_id=? AND role_version=?""",
            (*scope, int(snapshot["role_version"])),
        ).fetchone()
        if row is None:
            raise StoreError("task session role version is unavailable")
        stored = cls._role_snapshot_from_row(row)
        if stored != snapshot:
            raise StoreError("task session role snapshot conflicts")
        return snapshot

    @staticmethod
    def _thread_binding_tx(
        conn: sqlite3.Connection,
        *,
        conversation_id: str,
        mode_id: str,
        profile_version: int,
        policy_version: int,
        role_version: int = 0,
        role_snapshot_hash: str = _IMPLICIT_DEFAULT_ROLE["snapshot_hash"],
        persona_composition_version: str = ROLE_PERSONA_COMPOSITION_VERSION,
    ) -> str | None:
        row = conn.execute(
            """SELECT thread_id FROM thread_bindings
               WHERE conversation_id=? AND mode_id=? AND profile_version=?
                 AND policy_version=? AND role_version=?
                 AND role_snapshot_hash=?
                 AND persona_composition_version=?""",
            (
                conversation_id,
                mode_id,
                int(profile_version),
                int(policy_version),
                int(role_version),
                str(role_snapshot_hash),
                str(persona_composition_version),
            ),
        ).fetchone()
        return str(row["thread_id"]) if row is not None else None

    @classmethod
    def _resolve_task_thread_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        supplied_thread_id: Any,
        conversation_id: str,
        mode_id: str,
        profile_version: int,
        policy_version: int,
        role_version: int,
        role_snapshot_hash: str,
        persona_composition_version: str,
    ) -> str | None:
        """Resolve only the provider thread durably bound to this exact task.

        A task snapshot is not an authority to import an arbitrary provider
        thread.  Explicit IDs are compatibility assertions and are accepted
        only when the store already has the identical binding; unbound and
        foreign IDs fail before the task can reach a runtime.
        """

        bound_thread_id = cls._thread_binding_tx(
            conn,
            conversation_id=conversation_id,
            mode_id=mode_id,
            profile_version=profile_version,
            policy_version=policy_version,
            role_version=role_version,
            role_snapshot_hash=role_snapshot_hash,
            persona_composition_version=persona_composition_version,
        )
        if supplied_thread_id:
            supplied = str(supplied_thread_id)
            if bound_thread_id is None:
                raise StoreError(
                    "explicit task thread is not bound to its exact context"
                )
            if supplied != bound_thread_id:
                raise StoreError("explicit task thread binding conflicts")
        return bound_thread_id

    @staticmethod
    def _transition_inbound_tx(
        conn: sqlite3.Connection,
        message_id: str,
        target: InboundState,
        *,
        now: str,
        task_id: str | None = None,
    ) -> bool:
        """Apply one inbound transition inside an existing transaction."""

        row = conn.execute(
            "SELECT status FROM inbound_messages WHERE message_id=?",
            (message_id,),
        ).fetchone()
        if row is None:
            return False
        current = InboundState(str(row["status"]))
        if current == target:
            return False
        if target not in _ALLOWED_INBOUND_TRANSITIONS[current]:
            raise InvalidTransition(
                f"invalid inbound transition {current.value!r} -> {target.value!r}"
            )
        assignments = ["status=?", "stored_at=?"]
        values: list[Any] = [target.value, now]
        if task_id is not None:
            assignments.append("task_id=?")
            values.append(task_id)
        return conn.execute(
            "UPDATE inbound_messages SET " + ", ".join(assignments)
            + " WHERE message_id=? AND status=?",
            [*values, message_id, current.value],
        ).rowcount == 1

    @classmethod
    def _advance_confirmation_inbound_tx(
        cls,
        conn: sqlite3.Connection,
        message_id: str | None,
        target: InboundState,
        *,
        now: str,
        task_id: str | None = None,
    ) -> bool:
        """Advance a linked audio ingress row without regressing siblings.

        Older candidate rows may point at an inbound that is still ``stored``;
        newer creation moves it to ``awaiting_confirmation`` atomically.  This
        helper bridges that legacy gap, while treating a later aggregate state
        (for example one sibling already consumed) as authoritative.
        """

        if not message_id:
            return False
        row = conn.execute(
            "SELECT status FROM inbound_messages WHERE message_id=?",
            (message_id,),
        ).fetchone()
        if row is None:
            return False
        current = InboundState(str(row["status"]))
        changed = False
        if current == InboundState.STORED and target != InboundState.AWAITING_CONFIRMATION:
            changed = cls._transition_inbound_tx(
                conn,
                message_id,
                InboundState.AWAITING_CONFIRMATION,
                now=now,
            ) or changed
            current = InboundState.AWAITING_CONFIRMATION
        if target == InboundState.TASK_QUEUED and current == InboundState.AWAITING_CONFIRMATION:
            changed = cls._transition_inbound_tx(
                conn,
                message_id,
                InboundState.CONFIRMED,
                now=now,
            ) or changed
            current = InboundState.CONFIRMED
        if current == target:
            return changed
        if target not in _ALLOWED_INBOUND_TRANSITIONS[current]:
            # A sibling candidate may already have advanced this aggregate
            # ingress row.  Never regress confirmed/task-owned input because a
            # different candidate was rejected later.
            return changed
        return cls._transition_inbound_tx(
            conn,
            message_id,
            target,
            now=now,
            task_id=task_id,
        ) or changed

    @classmethod
    def _advance_terminal_confirmation_inbound_tx(
        cls,
        conn: sqlite3.Connection,
        message_id: str | None,
        confirmation_id: str,
        target: InboundState,
        *,
        now: str,
    ) -> bool:
        """Project a terminal candidate only after all siblings are terminal."""

        if target not in {InboundState.REJECTED, InboundState.EXPIRED}:
            raise ValueError("terminal confirmation target must be rejected or expired")
        if message_id:
            sibling = conn.execute(
                "SELECT 1 FROM transcription_candidates "
                "WHERE inbound_message_id=? AND confirmation_id<>? "
                "AND status IN ('pending','confirmed') LIMIT 1",
                (message_id, confirmation_id),
            ).fetchone()
            if sibling is not None:
                return False
        return cls._advance_confirmation_inbound_tx(
            conn,
            message_id,
            target,
            now=now,
        )

    @classmethod
    def _ensure_inbound_identity_tx(
        cls,
        conn: sqlite3.Connection,
        message: InboundMessage,
        *,
        now: str,
    ) -> dict[str, Any]:
        """Resolve and persist trusted v36 identity provenance for ingress.

        The transport actor remains ``external_user_id``.  A separately
        authenticated conversation subject supplies the route scope for group
        and thread messages, while canonical principals are looked up only by
        the exact durable account triple.  Caller-supplied principal values
        are accepted solely when they match that owner-configured mapping.
        """

        channel = cls._required_store_identity(message.channel, "channel")
        bot_id = cls._required_store_identity(message.bot_id, "bot_id")
        actor_id = cls._required_store_identity(
            message.external_user_id, "external_user_id"
        )
        subject_kind = str(message.conversation_subject_kind or "direct").strip().lower()
        if subject_kind not in {"direct", "group", "thread"}:
            raise StoreError("conversation subject kind is invalid")

        supplied_subject_id = str(message.conversation_subject_id or "").strip()
        supplied_subject_scope = str(
            message.conversation_subject_scope or ""
        ).strip()
        existing_subject = None
        if supplied_subject_id:
            existing_subject = conn.execute(
                "SELECT * FROM conversation_subjects "
                "WHERE conversation_subject_id=?",
                (supplied_subject_id,),
            ).fetchone()
        if existing_subject is not None:
            if (
                str(existing_subject["channel"]) != channel
                or str(existing_subject["bot_id"]) != bot_id
                or str(existing_subject["subject_kind"]) != subject_kind
            ):
                raise StoreError("conversation subject conflicts with inbound ownership")
            subject_id = str(existing_subject["conversation_subject_id"])
            route_scope = str(existing_subject["scope_key"])
            if supplied_subject_scope and supplied_subject_scope != route_scope:
                raise StoreError(
                    "conversation subject scope conflicts with inbound ownership"
                )
        elif supplied_subject_id:
            # Channel adapters provide an authenticated, bot-local scope.  It
            # is intentionally unrelated to principal identity and therefore
            # safe to retain as both the first durable subject ID and route
            # scope.  Explicit subject records may use a different opaque ID;
            # the existing-row branch above recovers their stored scope key.
            subject_id = supplied_subject_id
            route_scope = supplied_subject_scope or supplied_subject_id
        elif supplied_subject_scope:
            subject_id = supplied_subject_scope
            route_scope = supplied_subject_scope
        else:
            if subject_kind != "direct":
                raise StoreError(
                    "group/thread inbound requires an authenticated conversation subject"
                )
            direct = direct_conversation_subject(channel, bot_id, actor_id)
            subject_id = direct.conversation_subject_id
            route_scope = direct.scope_key

        transport_metadata = (
            dict(message.transport_metadata)
            if isinstance(message.transport_metadata, Mapping)
            else {}
        )
        external_chat_id = str(
            transport_metadata.get("chat_id")
            or (message.destination_id if subject_kind != "direct" else "")
            or ""
        )
        external_thread_id = str(
            message.thread_id
            or transport_metadata.get("thread_id")
            or transport_metadata.get("root_id")
            or ""
        )
        parent_subject_id: str | None = None
        if subject_kind == "thread":
            if not external_thread_id:
                raise StoreError("thread conversation subject requires a thread ID")
            if not external_chat_id:
                raise StoreError("thread conversation subject requires a chat ID")
            if channel.lower() in {"lark", "feishu"}:
                parent = group_conversation_subject(
                    channel, bot_id, external_chat_id
                )
                parent_subject_id = parent.conversation_subject_id
                parent_scope = parent.scope_key
            else:
                parent = direct_conversation_subject(
                    channel, bot_id, external_chat_id
                )
                parent_subject_id = parent.conversation_subject_id
                parent_scope = parent.scope_key
            conn.execute(
                """INSERT OR IGNORE INTO conversation_subjects
                       (conversation_subject_id, channel, bot_id, subject_kind,
                        scope_key, external_chat_id, external_thread_id,
                        parent_subject_id, provenance_json, created_at)
                   VALUES (?, ?, ?, 'group', ?, ?, '', NULL, ?, ?)""",
                (
                    parent_subject_id,
                    channel,
                    bot_id,
                    parent_scope,
                    external_chat_id,
                    json_dumps({"source": "authenticated_inbound"}),
                    now,
                ),
            )

        conn.execute(
            """INSERT OR IGNORE INTO conversation_subjects
                   (conversation_subject_id, channel, bot_id, subject_kind,
                    scope_key, external_chat_id, external_thread_id,
                    parent_subject_id, provenance_json, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (
                subject_id,
                channel,
                bot_id,
                subject_kind,
                route_scope,
                external_chat_id,
                external_thread_id,
                parent_subject_id,
                json_dumps({"source": "authenticated_inbound"}),
                now,
            ),
        )
        stored_subject = conn.execute(
            "SELECT * FROM conversation_subjects WHERE conversation_subject_id=?",
            (subject_id,),
        ).fetchone()
        if stored_subject is None:
            raise StoreError("conversation subject insert failed")
        for column, expected in (
            ("channel", channel),
            ("bot_id", bot_id),
            ("subject_kind", subject_kind),
            ("scope_key", route_scope),
        ):
            if str(stored_subject[column]) != str(expected):
                raise StoreError(
                    f"conversation subject conflicts with inbound ownership ({column})"
                )

        mapping = conn.execute(
            """SELECT pa.*, p.enabled AS principal_enabled
               FROM principal_accounts AS pa
               JOIN principals AS p ON p.principal_id=pa.principal_id
               WHERE pa.channel=? AND pa.bot_id=? AND pa.external_user_id=?
                 AND pa.active=1 AND p.enabled=1""",
            (channel, bot_id, actor_id),
        ).fetchone()
        supplied_principal = str(message.principal_id or "").strip()
        supplied_account = str(message.principal_account_id or "").strip()
        if bool(supplied_principal) != bool(supplied_account):
            raise StoreError(
                "principal_id and principal_account_id must be supplied together"
            )
        if supplied_principal:
            if mapping is None or (
                supplied_principal != str(mapping["principal_id"])
                or supplied_account != str(mapping["principal_account_id"])
            ):
                raise StoreError(
                    "inbound principal does not match the authenticated account mapping"
                )
        principal_id = str(mapping["principal_id"]) if mapping is not None else None
        principal_account_id = (
            str(mapping["principal_account_id"]) if mapping is not None else None
        )
        mapping_revision = (
            int(mapping["mapping_revision"]) if mapping is not None else None
        )
        snapshot = {
            "actor": {
                "channel": channel,
                "bot_id": bot_id,
                "external_user_id": actor_id,
            },
            "principal": {
                "principal_id": principal_id,
                "principal_account_id": principal_account_id,
                "mapping_revision": mapping_revision,
                "source": "configured" if mapping is not None else "unmapped",
            },
            "conversation_subject": {
                "conversation_subject_id": subject_id,
                "kind": subject_kind,
                "scope_key": route_scope,
                "parent_subject_id": parent_subject_id,
            },
            "destination": {
                "kind": str(message.destination_kind or ""),
                "id": str(message.destination_id or ""),
                "thread_id": external_thread_id,
                "root_message_id": str(
                    message.root_message_id
                    or transport_metadata.get("root_id")
                    or ""
                ),
                "transport_metadata": transport_metadata,
            },
        }
        return {
            "principal_id": principal_id,
            "principal_account_id": principal_account_id,
            "conversation_subject_id": subject_id,
            "route_scope": route_scope,
            "identity_snapshot": snapshot,
        }

    # ------------------------------------------------------------------
    # Ingress and task creation
    # ------------------------------------------------------------------
    async def store_inbound(
        self,
        inbound: InboundMessage | Mapping[str, Any] | None = None,
        *,
        cursor: str | None = None,
        channel_cursor: str | None = None,
        cursor_channel: str | None = None,
        cursor_bot_id: str | None = None,
        _trusted_media_wire_fingerprints: Sequence[str] | None = None,
        **kwargs: Any,
    ) -> InboundMessage:
        """Persist one normalized inbound envelope, idempotently.

        The insert is committed before this method returns.  A duplicate
        identity returns the original immutable row rather than overwriting
        channel data.
        """

        inbound_keys = {
            "channel", "bot_id", "external_user_id", "external_message_id",
            "text", "content", "body", "session_id", "source_sequence",
            "context_token", "payload", "received_at", "message_id",
            "principal_id", "principal_account_id", "conversation_subject_id",
            "conversation_subject_kind", "destination_kind", "destination_id",
            "conversation_subject_scope", "thread_id", "root_message_id",
            "transport_metadata", "identity_snapshot",
        }
        message = self._coerce_inbound(
            inbound,
            {key: value for key, value in kwargs.items() if key in inbound_keys},
        )
        stored_payload = self._sanitize_inbound_payload(
            message.payload,
            trusted_media_wire_fingerprints=(
                _trusted_media_wire_fingerprints
            ),
        )
        cursor_value = cursor if cursor is not None else channel_cursor
        now = self._now()

        def op(conn: sqlite3.Connection) -> InboundMessage:
            with _transaction(conn):
                identity = self._ensure_inbound_identity_tx(
                    conn, message, now=now
                )
                insert_cursor = conn.execute(
                    """INSERT OR IGNORE INTO inbound_messages
                       (message_id, channel, bot_id, external_user_id,
                        external_message_id, session_id, source_sequence,
                        context_token, text, payload_json, status,
                        received_at, stored_at, principal_id,
                        principal_account_id, conversation_subject_id,
                        identity_snapshot_json)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        message.message_id,
                        message.channel,
                        message.bot_id,
                        message.external_user_id,
                        message.external_message_id,
                        message.session_id,
                        message.source_sequence,
                        message.context_token,
                        message.text,
                        json_dumps(stored_payload),
                        # ``store_inbound`` is the durable ``received ->
                        # stored`` transition.  A freshly-normalized
                        # envelope carries ``received`` by default, but it
                        # must not remain in that transient state after the
                        # commit.  Preserve an explicit later state for
                        # callers replaying a persisted row.
                        (
                            InboundState.STORED.value
                            if _enum_value(message.status) == InboundState.RECEIVED.value
                            else _enum_value(message.status, InboundState.STORED.value)
                        ),
                        _utc_text(message.received_at),
                        now,
                        identity["principal_id"],
                        identity["principal_account_id"],
                        identity["conversation_subject_id"],
                        json_dumps(identity["identity_snapshot"]),
                    ),
                )
                row = conn.execute(
                    "SELECT * FROM inbound_messages WHERE channel = ? AND bot_id = ? AND external_message_id = ?",
                    message.dedupe_identity,
                ).fetchone()
                if row is None:
                    raise StoreError("failed to persist inbound message")
                if insert_cursor.rowcount == 0:
                    self._validate_inbound_replay_tx(
                        row,
                        message,
                        trusted_media_wire_fingerprints=(
                            _trusted_media_wire_fingerprints
                        ),
                    )
                # The channel identity key deliberately follows the protocol
                # `(channel, bot, external_message_id)`, but a malformed or
                # sender-scoped ID must never let one user's envelope alias
                # another user's task.  Treat a scope mismatch as a hard
                # ownership conflict rather than a harmless duplicate.
                if (
                    str(row["external_user_id"] or "")
                    != str(message.external_user_id or "")
                    or str(row["session_id"] or "default")
                    != str(message.session_id or "default")
                ):
                    raise StoreError(
                        "inbound identity conflicts with an existing user/session"
                    )
                self._ensure_reply_scope_for_inbound_row_tx(conn, row)
                self._retain_inbound_attachments_tx(
                    conn,
                    message_id=str(row["message_id"]),
                    attachments=self._input_attachment_values(
                        json_loads(row["payload_json"], {}) or {}
                    ),
                    channel=str(row["channel"] or ""),
                    bot_id=str(row["bot_id"] or ""),
                    external_user_id=str(row["external_user_id"] or ""),
                    session_id=str(row["session_id"] or "default"),
                    source_message_id=str(row["external_message_id"] or ""),
                    agent_id=None,
                    created_at=row["stored_at"],
                )
                cursor_scope = (
                    cursor_channel or message.channel,
                    cursor_bot_id or message.bot_id,
                )
                existing_cursor = conn.execute(
                    "SELECT cursor FROM channel_cursors WHERE channel=? AND bot_id=?",
                    cursor_scope,
                ).fetchone()
                # The message row makes a duplicate cursor safe to repair,
                # while numeric checkpoints are never allowed to regress.
                current_cursor = (
                    str(existing_cursor["cursor"])
                    if existing_cursor is not None
                    else None
                )
                if _cursor_should_advance(current_cursor, cursor_value):
                    conn.execute(
                        """INSERT INTO channel_cursors(channel, bot_id, cursor, updated_at)
                           VALUES (?, ?, ?, ?)
                           ON CONFLICT(channel, bot_id)
                           DO UPDATE SET cursor=excluded.cursor, updated_at=excluded.updated_at""",
                        (
                            cursor_scope[0],
                            cursor_scope[1],
                            str(cursor_value),
                            now,
                        ),
                    )
                return self._inbound_from_row(row)

        return await self._call(op)

    # Aliases used by channel adapters.
    record_inbound = store_inbound
    persist_inbound = store_inbound

    @classmethod
    def _delivery_reply_scope_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        target: ReplyTarget,
        reply_scope_id: str | None,
    ) -> sqlite3.Row | None:
        scope = (
            conn.execute(
                "SELECT * FROM reply_scopes WHERE reply_scope_id=?",
                (str(reply_scope_id),),
            ).fetchone()
            if reply_scope_id
            else cls._reply_scope_for_target_tx(conn, target)
        )
        if scope is None:
            return None
        if (
            str(scope["channel"]),
            str(scope["bot_id"]),
            str(scope["external_user_id"]),
            str(scope["session_id"] or "default"),
        ) != (
            str(target.channel),
            str(target.bot_id),
            str(target.external_user_id),
            str(target.session_id or "default"),
        ):
            raise StoreError("delivery reply scope conflicts with task recipient")
        return scope

    @classmethod
    def _project_initial_task_reply_tx(
        cls,
        conn: sqlite3.Connection,
        *,
        initial_reply: Any,
        task: TaskRecord,
        fallback_target: ReplyTarget,
        delivery_reply_scope_id: str | None,
        now: str,
    ) -> tuple[str, bool]:
        """Reserve a command acknowledgement before queued work is visible."""

        data: dict[str, Any] = {}
        if isinstance(initial_reply, Mapping):
            data.update(initial_reply)
        elif initial_reply is not None:
            for name in (
                "target",
                "reply_target",
                "source_key",
                "idempotency_key",
                "content",
                "text",
                "attachments",
                "priority",
                "delivery_mode",
                "outbox_id",
                "delivery_id",
                "client_id",
                "contextless_client_id",
                "from_user_id",
                "reply_scope_id",
                "agent_id",
            ):
                if hasattr(initial_reply, name):
                    data[name] = getattr(initial_reply, name)
            converter = getattr(initial_reply, "to_dict", None) or getattr(
                initial_reply, "as_dict", None
            )
            if converter is not None:
                try:
                    converted = converter()
                except TypeError:
                    converted = None
                if isinstance(converted, Mapping):
                    data.update(converted)
        target = cls._coerce_reply_target(
            data.get("target", data.get("reply_target")), fallback=fallback_target
        )
        source_key = str(
            data.get("source_key")
            or data.get("idempotency_key")
            or data.get("outbox_id")
            or data.get("delivery_id")
            or ""
        ).strip()
        if not source_key:
            raise ValueError("initial task reply source_key is required")
        raw_attachments = data.get("attachments", ()) or ()
        if isinstance(raw_attachments, (str, bytes, bytearray, Mapping)):
            attachments = (raw_attachments,)
        else:
            attachments = tuple(raw_attachments)
        scope_value = str(
            delivery_reply_scope_id or data.get("reply_scope_id") or ""
        ) or None
        scope = cls._delivery_reply_scope_tx(
            conn, target=target, reply_scope_id=scope_value
        )
        if scope is None:
            raise NotFoundError(
                "initial task reply does not identify a stored inbound scope"
            )
        projection = cls._project_reply_candidate_tx(
            conn,
            target=target,
            source_key=source_key,
            content=str(data.get("content", data.get("text", "")) or ""),
            attachments=attachments,
            reply_scope_id=str(scope["reply_scope_id"]),
            # This is an independent command response, not task output.  Its
            # identity must match the Gateway's immediate delivery replay.
            agent_id=str(data.get("agent_id") or task.agent_id),
            task_id=None,
            priority=data.get("priority", EventPriority.NORMAL),
            delivery_mode=data.get(
                "delivery_mode", DeliveryMode.PUSH_ELIGIBLE
            ),
            notify_enabled=True,
            foreground=True,
            preferred_outbox_id=(
                str(data.get("outbox_id") or data.get("delivery_id") or "")
                or None
            ),
            preferred_client_id=str(data.get("client_id") or "") or None,
            preferred_contextless_client_id=(
                str(data.get("contextless_client_id") or "") or None
            ),
            from_user_id=str(data.get("from_user_id") or target.bot_id or ""),
            now=now,
        )
        if not projection.slots or not projection.outbox_items:
            raise StoreError(
                "initial task reply could not reserve a canonical send slot"
            )
        return str(scope["reply_scope_id"]), bool(projection.replayed)

    async def create_task(
        self,
        task: AgentTask | Mapping[str, Any] | None = None,
        *,
        inbound_message_id: str | None = None,
        dedupe_key: str | None = None,
        channel: str = "",
        bot_id: str = "",
        external_user_id: str = "",
        session_id: str | None = None,
        initial_reply: Any = None,
        delivery_reply_scope_id: str | None = None,
        _reserve_child_parent_id: str | None = None,
        _reserve_child_max: int | None = None,
        **kwargs: Any,
    ) -> TaskRecord:
        """Create a queued task, returning the existing row for duplicates."""

        values = dict(kwargs)
        if inbound_message_id is not None:
            values["inbound_message_id"] = inbound_message_id
        if dedupe_key is not None:
            values["dedupe_key"] = dedupe_key
        # Explicit keyword arguments take precedence, but omitted/empty
        # convenience defaults must not erase channel identity carried by a
        # task mapping or ReplyTarget.
        if channel:
            values["channel"] = channel
        if bot_id:
            values["bot_id"] = bot_id
        if external_user_id:
            values["external_user_id"] = external_user_id
        if session_id:
            values["session_id"] = session_id
        task_snapshot = self._coerce_task(task, values)
        # Route identity is not part of AgentTask's dataclass fields.  Capture
        # top-level mapping keys before coercion, then derive omitted scope
        # from the immutable ReplyTarget so direct mapping callers cannot
        # accidentally create an empty/shared conversation.
        task_route: Mapping[str, Any] = task if isinstance(task, Mapping) else {}
        target_route = task_snapshot.reply_target
        mapped_channel = str(task_route.get("channel") or "")
        mapped_bot_id = str(task_route.get("bot_id") or "")
        mapped_user_id = str(task_route.get("external_user_id") or "")
        mapped_session_id = str(task_route.get("session_id") or "")
        # Use the normalized snapshot for race recovery too.  Callers often
        # place these identities inside the task mapping rather than in the
        # convenience keyword arguments.
        effective_dedupe_key = task_snapshot.dedupe_key or dedupe_key
        effective_inbound_id = task_snapshot.inbound_message_id or inbound_message_id
        now = self._now()

        def prepare_initial_delivery_tx(
            conn: sqlite3.Connection, record: TaskRecord
        ) -> TaskRecord:
            scope_id: str | None = None
            replayed = True
            if initial_reply is not None:
                scope_id, replayed = self._project_initial_task_reply_tx(
                    conn,
                    initial_reply=initial_reply,
                    task=record,
                    fallback_target=record.reply_target,
                    delivery_reply_scope_id=delivery_reply_scope_id,
                    now=now,
                )
            elif delivery_reply_scope_id:
                scope = self._delivery_reply_scope_tx(
                    conn,
                    target=record.reply_target,
                    reply_scope_id=delivery_reply_scope_id,
                )
                if scope is None:
                    raise NotFoundError(
                        "task delivery scope does not identify a stored inbound"
                    )
                scope_id = str(scope["reply_scope_id"])
            if scope_id is None:
                return record
            if record.state == TaskState.QUEUED:
                stored_pending = str(
                    record.pending_delivery_reply_scope_id or ""
                )
                if stored_pending and stored_pending != scope_id:
                    raise StoreError(
                        "queued task delivery reply scope conflicts"
                    )
                conn.execute(
                    "UPDATE tasks SET pending_delivery_reply_scope_id=? "
                    "WHERE task_id=? AND state='queued'",
                    (scope_id, record.task_id),
                )
                refreshed = self._fetch_task_tx(conn, record.task_id)
                if refreshed is None:
                    raise StoreError("task disappeared while preparing delivery")
                return refreshed
            if not replayed:
                # A task already visible to a dispatcher cannot acquire its
                # first acknowledgement after the claim.  Roll the new
                # projection back and force the caller to reconcile.
                raise StoreError(
                    "task was claimed before its initial reply reservation"
                )
            execution = conn.execute(
                "SELECT delivery_reply_scope_id FROM task_executions "
                "WHERE task_id=? ORDER BY attempt DESC LIMIT 1",
                (record.task_id,),
            ).fetchone()
            if (
                execution is not None
                and execution["delivery_reply_scope_id"] is not None
                and str(execution["delivery_reply_scope_id"]) != scope_id
            ):
                raise StoreError("task execution delivery reply scope conflicts")
            return record

        def op(conn: sqlite3.Connection) -> TaskRecord | None:
            with _transaction(conn):
                snapshot = task_snapshot
                inbound_id = snapshot.inbound_message_id
                inbound_row: sqlite3.Row | None = None
                inbound_actor_id = ""
                if inbound_id:
                    inbound_row = conn.execute(
                        "SELECT channel, bot_id, external_user_id, session_id, message_id, "
                        "external_message_id, source_sequence, context_token, "
                        "principal_id, principal_account_id, conversation_subject_id, "
                        "identity_snapshot_json "
                        "FROM inbound_messages WHERE message_id = ?",
                        (inbound_id,),
                    ).fetchone()
                    if inbound_row is None:
                        raise NotFoundError(
                            f"inbound message not found: {inbound_id}"
                        )
                    if inbound_row is not None:
                        inbound_actor_id = str(inbound_row["external_user_id"] or "")
                        inbound_identity = (
                            json_loads(inbound_row["identity_snapshot_json"], {}) or {}
                        )
                        inbound_subject = (
                            inbound_identity.get("conversation_subject", {})
                            if isinstance(inbound_identity, Mapping)
                            else {}
                        )
                        if not isinstance(inbound_subject, Mapping):
                            inbound_subject = {}
                        inbound_route_user = str(
                            inbound_subject.get("scope_key")
                            or inbound_actor_id
                        )
                        for supplied, persisted, field in (
                            (snapshot.actor_external_user_id, inbound_actor_id, "actor_external_user_id"),
                            (snapshot.principal_id, inbound_row["principal_id"], "principal_id"),
                            (
                                snapshot.principal_account_id,
                                inbound_row["principal_account_id"],
                                "principal_account_id",
                            ),
                            (
                                snapshot.conversation_subject_id,
                                inbound_row["conversation_subject_id"],
                                "conversation_subject_id",
                            ),
                        ):
                            if supplied and str(supplied) != str(persisted or ""):
                                raise StoreError(
                                    f"task identity conflicts with inbound ownership ({field})"
                                )
                        snapshot = self._coerce_task(
                            snapshot,
                            {
                                "actor_external_user_id": inbound_actor_id,
                                "principal_id": inbound_row["principal_id"],
                                "principal_account_id": inbound_row["principal_account_id"],
                                "conversation_subject_id": inbound_row["conversation_subject_id"],
                                "identity_snapshot": inbound_identity,
                            },
                        )
                        # A linked inbound envelope owns its channel scope.
                        # Explicit convenience fields or a ReplyTarget may
                        # not redirect that durable message, even when the
                        # dedupe lookup would otherwise return an existing
                        # task before insertion.
                        for supplied, persisted, field in (
                            (channel or mapped_channel, inbound_row["channel"], "channel"),
                            (bot_id or mapped_bot_id, inbound_row["bot_id"], "bot_id"),
                            (
                                external_user_id or mapped_user_id,
                                inbound_route_user,
                                "external_user_id",
                            ),
                            (
                                session_id or mapped_session_id,
                                inbound_row["session_id"] or "default",
                                "session_id",
                            ),
                        ):
                            if (
                                supplied
                                and str(supplied)
                                not in {str(persisted), inbound_actor_id}
                            ):
                                raise StoreError(
                                    f"task scope conflicts with inbound ownership ({field})"
                                )
                        self._validate_reply_target_scope(
                            self._coerce_reply_target(snapshot.reply_target),
                            channel=inbound_row["channel"],
                            bot_id=inbound_row["bot_id"],
                            external_user_id=inbound_route_user,
                            session_id=inbound_row["session_id"] or "default",
                        )
                        channel_value = (
                            channel or mapped_channel or inbound_row["channel"] or target_route.channel
                        )
                        bot_value = (
                            bot_id or mapped_bot_id or inbound_row["bot_id"] or target_route.bot_id
                        )
                        user_value = (
                            external_user_id
                            or mapped_user_id
                            or inbound_route_user
                            or target_route.external_user_id
                        )
                        if user_value == inbound_actor_id:
                            user_value = inbound_route_user
                        session_value = (
                            session_id
                            or mapped_session_id
                            or inbound_row["session_id"]
                            or target_route.session_id
                            or "default"
                        )
                    else:
                        channel_value, bot_value, user_value, session_value = (
                            channel or mapped_channel or target_route.channel,
                            bot_id or mapped_bot_id or target_route.bot_id,
                            external_user_id or mapped_user_id or target_route.external_user_id,
                            session_id or mapped_session_id or target_route.session_id or "default",
                        )
                else:
                    channel_value, bot_value, user_value, session_value = (
                        channel or mapped_channel or target_route.channel,
                        bot_id or mapped_bot_id or target_route.bot_id,
                        external_user_id or mapped_user_id or target_route.external_user_id,
                        session_id or mapped_session_id or target_route.session_id or "default",
                    )
                    subject_data = (
                        snapshot.identity_snapshot.get("conversation_subject", {})
                        if isinstance(snapshot.identity_snapshot, Mapping)
                        else {}
                    )
                    if not isinstance(subject_data, Mapping):
                        subject_data = {}
                    subject_kind = str(
                        subject_data.get("kind")
                        or (
                            "thread"
                            if target_route.thread_id
                            else "group"
                            if target_route.destination_kind in {"group", "thread"}
                            else "direct"
                        )
                    )
                    actor_value = str(
                        snapshot.actor_external_user_id
                        or target_route.external_user_id
                        or user_value
                    )
                    transport_scope_supplied = any(
                        str(value or "").strip()
                        for value in (
                            channel_value,
                            bot_value,
                            user_value,
                            actor_value,
                            snapshot.principal_id,
                            snapshot.principal_account_id,
                            snapshot.conversation_subject_id,
                            target_route.conversation_subject_id,
                            target_route.conversation_subject_scope,
                            target_route.destination_kind,
                            target_route.destination_id,
                            target_route.thread_id,
                            target_route.root_message_id,
                        )
                    )
                    if transport_scope_supplied:
                        standalone_identity = self._ensure_inbound_identity_tx(
                            conn,
                            InboundMessage(
                                channel=str(channel_value),
                                bot_id=str(bot_value),
                                external_user_id=actor_value,
                                external_message_id="identity-only",
                                session_id=str(session_value or "default"),
                                principal_id=snapshot.principal_id,
                                principal_account_id=snapshot.principal_account_id,
                                conversation_subject_id=(
                                    snapshot.conversation_subject_id
                                    or target_route.conversation_subject_id
                                    or None
                                ),
                                conversation_subject_scope=(
                                    target_route.conversation_subject_scope
                                ),
                                conversation_subject_kind=subject_kind,
                                destination_kind=target_route.destination_kind,
                                destination_id=target_route.destination_id,
                                thread_id=target_route.thread_id,
                                root_message_id=target_route.root_message_id,
                                transport_metadata=target_route.transport_metadata,
                            ),
                            now=now,
                        )
                        snapshot = self._coerce_task(
                            snapshot,
                            {
                                "actor_external_user_id": actor_value,
                                "principal_id": standalone_identity[
                                    "principal_id"
                                ],
                                "principal_account_id": standalone_identity[
                                    "principal_account_id"
                                ],
                                "conversation_subject_id": standalone_identity[
                                    "conversation_subject_id"
                                ],
                                "identity_snapshot": standalone_identity[
                                    "identity_snapshot"
                                ],
                            },
                        )
                        user_value = str(standalone_identity["route_scope"])
                if not snapshot.dedupe_key and inbound_id:
                    dedupe = f"inbound:{inbound_id}"
                else:
                    dedupe = snapshot.dedupe_key
                conversation_id = self._ensure_conversation_tx(
                    conn,
                    snapshot,
                    channel=channel_value,
                    bot_id=bot_value,
                    external_user_id=user_value,
                    session_id=session_value,
                    now=now,
                )
                role_snapshot = self._task_role_snapshot_tx(
                    conn,
                    metadata=snapshot.metadata,
                    channel=channel_value,
                    bot_id=bot_value,
                    external_user_id=user_value,
                    session_id=session_value,
                    agent_id=snapshot.agent_id,
                )
                role_version, role_hash, persona_version = role_binding_key(
                    role_snapshot
                )
                thread_id = self._resolve_task_thread_tx(
                    conn,
                    supplied_thread_id=snapshot.thread_id,
                    conversation_id=conversation_id,
                    mode_id=snapshot.mode_id,
                    profile_version=snapshot.profile_version,
                    policy_version=snapshot.policy_version,
                    role_version=role_version,
                    role_snapshot_hash=role_hash,
                    persona_composition_version=persona_version,
                )
                existing = self._fetch_task_by_dedupe_tx(conn, dedupe)
                if existing is not None:
                    self._validate_dedupe_owner(
                        existing,
                        channel=channel_value,
                        bot_id=bot_value,
                        external_user_id=user_value,
                        session_id=session_value,
                        agent_id=snapshot.agent_id,
                        parent_task_id=snapshot.parent_task_id,
                        conversation_id=conversation_id,
                    )
                    self._retain_task_input_attachments_tx(
                        conn,
                        task_id=existing.task_id,
                        inputs=existing.inputs,
                        created_at=existing.created_at,
                    )
                    return prepare_initial_delivery_tx(conn, existing)
                # A task may be deduplicated by inbound id even when callers
                # supplied a different dedupe key (the schema enforces this).
                if inbound_id:
                    row = conn.execute(
                        f"{self._task_select_sql()} WHERE t.inbound_message_id = ?",
                        (inbound_id,),
                    ).fetchone()
                    existing = self._task_from_row(row)
                    if existing is not None:
                        self._validate_dedupe_owner(
                            existing,
                            channel=channel_value,
                            bot_id=bot_value,
                            external_user_id=user_value,
                            session_id=session_value,
                            agent_id=snapshot.agent_id,
                            parent_task_id=snapshot.parent_task_id,
                            conversation_id=conversation_id,
                        )
                        return prepare_initial_delivery_tx(conn, existing)
                task_id = snapshot.task_id or _uuid()
                # Child admission and task insertion must share one durable
                # transaction.  A process crash between a standalone counter
                # reservation and INSERT would otherwise leak a child slot
                # forever.  The duplicate checks above intentionally precede
                # this block so replaying an already-created child does not
                # increment the counter a second time.
                child_parent_id = (
                    str(snapshot.parent_task_id)
                    if snapshot.parent_task_id
                    else None
                )
                if _reserve_child_parent_id is not None:
                    parent_id = str(_reserve_child_parent_id)
                    if str(snapshot.parent_task_id or "") != parent_id:
                        raise StoreError(
                            "child reservation parent does not match task snapshot"
                        )
                    child_parent_id = parent_id
                if child_parent_id is not None:
                    # Validate the logical parent relationship on every task
                    # insertion path, including compatibility callers that do
                    # not use ``create_child_task``.
                    self._validate_child_parent_tx(
                        conn,
                        snapshot,
                        channel=channel_value,
                        bot_id=bot_value,
                        external_user_id=user_value,
                        session_id=session_value,
                    )

                current_count: int | None = None
                if child_parent_id is not None:
                    counter = conn.execute(
                        "SELECT child_count FROM child_task_counters "
                        "WHERE parent_task_id=?", (child_parent_id,)
                    ).fetchone()
                    durable_count = int(
                        conn.execute(
                            "SELECT COUNT(*) FROM tasks WHERE parent_task_id=?",
                            (child_parent_id,),
                        ).fetchone()[0]
                    )
                    # Legacy standalone reservations and direct task inserts
                    # can leave either side ahead.  Admission must account for
                    # both until startup reconciliation repairs the counter.
                    current_count = max(
                        int(counter["child_count"]) if counter else 0,
                        durable_count,
                    )
                    if _reserve_child_parent_id is not None:
                        max_children = (
                            int(_reserve_child_max)
                            if _reserve_child_max is not None
                            else -1
                        )
                        if max_children >= 0 and current_count >= max_children:
                            raise PermissionError(
                                "maximum child-task count exceeded"
                            )
                identity_destination = (
                    snapshot.identity_snapshot.get("destination", {})
                    if isinstance(snapshot.identity_snapshot, Mapping)
                    else {}
                )
                if not isinstance(identity_destination, Mapping):
                    identity_destination = {}
                reply_target = self._coerce_reply_target(
                    snapshot.reply_target,
                    fallback=ReplyTarget(
                        channel=channel_value,
                        bot_id=bot_value,
                        external_user_id=inbound_actor_id or user_value,
                        session_id=session_value,
                        source_message_id=(
                            inbound_row["external_message_id"]
                            if inbound_id and inbound_row is not None
                            else inbound_id
                        ),
                        source_sequence=(
                            inbound_row["source_sequence"]
                            if inbound_id and inbound_row is not None
                            else None
                        ),
                        context_token=(
                            inbound_row["context_token"]
                            if inbound_id and inbound_row is not None
                            else None
                        ),
                        conversation_subject_id=str(
                            snapshot.conversation_subject_id or ""
                        ),
                        conversation_subject_scope=str(user_value or ""),
                        destination_kind=str(
                            identity_destination.get("kind") or ""
                        ),
                        destination_id=str(
                            identity_destination.get("id") or ""
                        ),
                        thread_id=str(
                            identity_destination.get("thread_id") or ""
                        ),
                        root_message_id=str(
                            identity_destination.get("root_message_id") or ""
                        ),
                        transport_metadata=(
                            dict(
                                identity_destination.get("transport_metadata")
                                or {}
                            )
                            if isinstance(
                                identity_destination.get("transport_metadata"),
                                Mapping,
                            )
                            else {}
                        ),
                    ),
                )
                self._validate_reply_target_scope(
                    reply_target,
                    channel=channel_value,
                    bot_id=bot_value,
                    external_user_id=user_value,
                    session_id=session_value,
                )
                agent_incarnation = self._current_agent_incarnation_tx(
                    conn,
                    snapshot.agent_id,
                    int(snapshot.profile_version),
                )
                conn.execute(
                    """INSERT INTO tasks
                       (task_id, dedupe_key, inbound_message_id, channel, bot_id,
                        external_user_id, session_id, agent_id, agent_incarnation, conversation_id,
                        thread_id, mode_id, profile_version, policy_version,
                        model, reasoning_effort, reply_target_json, inputs_json,
                        metadata_json, actor_external_user_id, principal_id,
                        principal_account_id, conversation_subject_id,
                        identity_snapshot_json,
                        state, attempts, next_attempt_at, parent_task_id,
                        child_depth, request_id, created_at, updated_at)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                               ?, ?, ?, ?, ?,
                               'queued', 0, ?, ?, ?, ?, ?, ?)""",
                    (
                        task_id,
                        dedupe,
                        inbound_id,
                        channel_value,
                        bot_value,
                        user_value,
                        session_value,
                        snapshot.agent_id,
                        agent_incarnation,
                        conversation_id,
                        thread_id,
                        snapshot.mode_id,
                        int(snapshot.profile_version),
                        int(snapshot.policy_version),
                        snapshot.model,
                        snapshot.reasoning_effort,
                        json_dumps(reply_target.to_dict()),
                        json_dumps(_snapshot_value(snapshot.inputs)),
                        json_dumps(_snapshot_value(snapshot.metadata, text_key="value")),
                        snapshot.actor_external_user_id or inbound_actor_id or user_value,
                        snapshot.principal_id,
                        snapshot.principal_account_id,
                        snapshot.conversation_subject_id,
                        json_dumps(_snapshot_value(snapshot.identity_snapshot)),
                        None,
                        snapshot.parent_task_id,
                        int(snapshot.child_depth),
                        snapshot.request_id,
                        now,
                        now,
                    ),
                )
                if inbound_id:
                    # Publish the task owner inside this transaction before
                    # validating inbound media refs.  Any validation failure
                    # rolls this provisional link back with the task insert.
                    conn.execute(
                        "UPDATE inbound_messages SET task_id = ?, status = 'task_queued' WHERE message_id = ?",
                        (task_id, inbound_id),
                    )
                self._validate_task_input_attachment_access_tx(
                    conn,
                    task_id=task_id,
                    inbound_message_id=inbound_id,
                    inputs=snapshot.inputs,
                    agent_id=snapshot.agent_id,
                    channel=channel_value,
                    bot_id=bot_value,
                    external_user_id=user_value,
                    session_id=session_value,
                )
                if child_parent_id is not None:
                    # Keep the counter an exact lower bound for durable child
                    # rows.  If a compatibility caller reserved a slot before
                    # this insert, the pre-existing count already includes
                    # that slot; taking ``max`` avoids double charging it.
                    self._update_child_counter_tx(
                        conn, child_parent_id, now=now
                    )
                self._retain_task_input_attachments_tx(
                    conn,
                    task_id=task_id,
                    inputs=snapshot.inputs,
                    created_at=now,
                )
                self._create_queued_task_invocation_tx(
                    conn,
                    task_id=task_id,
                    now=now,
                    max_agent_queue=self.max_agent_queue,
                    max_global_queue=self.max_global_queue,
                    max_account_queue=self.max_account_queue,
                    max_account_agent_queue=self.max_account_agent_queue,
                )
                created = self._fetch_task_tx(conn, task_id)
                if created is None:
                    raise StoreError("failed to create task")
                return prepare_initial_delivery_tx(conn, created)

        requested_subject = (
            task_snapshot.identity_snapshot.get("conversation_subject", {})
            if isinstance(task_snapshot.identity_snapshot, Mapping)
            else {}
        )
        if not isinstance(requested_subject, Mapping):
            requested_subject = {}
        requested_user_id = str(
            requested_subject.get("scope_key")
            or (
                target_route.conversation_subject_id
                if target_route.destination_kind in {"group", "thread"}
                else ""
            )
            or external_user_id
            or mapped_user_id
            or target_route.external_user_id
        )
        requested_scope = (
            channel or mapped_channel or target_route.channel,
            bot_id or mapped_bot_id or target_route.bot_id,
            requested_user_id,
            session_id or mapped_session_id or target_route.session_id or "default",
        )
        requested_conversation = task_snapshot.conversation_id or canonical_conversation_id(
            *requested_scope, task_snapshot.agent_id
        )
        try:
            return await self._call(op)
        except sqlite3.IntegrityError as exc:
            # A concurrent writer may win the dedupe race between our lookup
            # and INSERT.  Return that winner whenever possible.
            if effective_dedupe_key:
                existing = await self.get_task_by_dedupe(effective_dedupe_key)
                if existing is not None:
                    self._validate_dedupe_owner(
                        existing,
                        channel=requested_scope[0],
                        bot_id=requested_scope[1],
                        external_user_id=requested_scope[2],
                        session_id=requested_scope[3],
                        agent_id=task_snapshot.agent_id,
                        parent_task_id=task_snapshot.parent_task_id,
                        conversation_id=requested_conversation,
                    )
                    return existing
            if effective_inbound_id:
                existing = await self.get_task_by_inbound(effective_inbound_id)
                if existing is not None:
                    self._validate_dedupe_owner(
                        existing,
                        channel=requested_scope[0],
                        bot_id=requested_scope[1],
                        external_user_id=requested_scope[2],
                        session_id=requested_scope[3],
                        agent_id=task_snapshot.agent_id,
                        parent_task_id=task_snapshot.parent_task_id,
                        conversation_id=requested_conversation,
                    )
                    return existing
            raise StoreError(str(exc)) from exc

    enqueue_task = create_task

    async def create_child_task(
        self,
        task: AgentTask | Mapping[str, Any] | None = None,
        *,
        parent_task_id: str,
        max_children: int,
        **kwargs: Any,
    ) -> TaskRecord:
        """Insert a child task while reserving its parent slot atomically.

        This is deliberately a store operation instead of a manager-level
        ``reserve`` followed by ``create_task``.  Both the counter increment
        and task row are committed (or rolled back) together, so a crash can
        never leave an admission slot without a corresponding durable task.
        """

        kwargs.setdefault("parent_task_id", str(parent_task_id))
        return await self.create_task(
            task,
            _reserve_child_parent_id=str(parent_task_id),
            _reserve_child_max=int(max_children),
            **kwargs,
        )

    async def accept_inbound(
        self,
        inbound: InboundMessage | Mapping[str, Any] | None = None,
        *,
        task: AgentTask | Mapping[str, Any] | None = None,
        create_task: bool = True,
        transcription_candidates: Iterable[Mapping[str, Any]] | Mapping[str, Any] | None = None,
        audio_candidates: Iterable[Mapping[str, Any]] | Mapping[str, Any] | None = None,
        command_snapshot: Mapping[str, Any] | None = None,
        cursor: str | None = None,
        channel_cursor: str | None = None,
        cursor_channel: str | None = None,
        cursor_bot_id: str | None = None,
        _trusted_media_wire_fingerprints: Sequence[str] | None = None,
        **kwargs: Any,
    ) -> InboundAcceptance:
        """Durably store ingress and create at most one task in one transaction."""

        inbound_keys = {
            "channel", "bot_id", "external_user_id", "external_message_id",
            "text", "content", "body", "session_id", "source_sequence",
            "context_token", "payload", "received_at", "message_id",
            "principal_id", "principal_account_id", "conversation_subject_id",
            "conversation_subject_kind", "destination_kind", "destination_id",
            "conversation_subject_scope", "thread_id", "root_message_id",
            "transport_metadata", "identity_snapshot",
        }
        message = self._coerce_inbound(
            inbound,
            {key: value for key, value in kwargs.items() if key in inbound_keys},
        )
        cursor_value = cursor if cursor is not None else channel_cursor
        task_values: dict[str, Any] = {}
        if isinstance(task, Mapping):
            task_values.update(task)
        elif isinstance(task, AgentTask):
            task_values = {name: getattr(task, name) for name in task.__dataclass_fields__}
        # Explicit task fields can be passed alongside the inbound envelope.
        for key in (
            "agent_id", "conversation_id", "thread_id", "mode_id", "profile_version",
            "policy_version", "model", "reasoning_effort", "reply_target", "inputs",
            "request_id", "dedupe_key", "actor_external_user_id", "principal_id",
            "principal_account_id", "conversation_subject_id", "identity_snapshot",
        ):
            if key in kwargs:
                task_values[key] = kwargs[key]
        candidate_input = (
            transcription_candidates
            if transcription_candidates is not None
            else audio_candidates
        )
        if isinstance(candidate_input, Mapping):
            candidate_specs = [dict(candidate_input)]
        else:
            candidate_specs = [dict(item) for item in (candidate_input or ())]
        # A direct store caller may provide only a candidate/command route
        # snapshot instead of the fully materialized task mapping that the
        # TaskManager normally supplies.  Resolve each immutable route field
        # from the same trusted sources, in precedence order, before writing
        # the internal snapshot.  This keeps later media ACL checks and
        # confirmation replay tied to the original mode/policy as well as the
        # original Agent.
        command_values: Mapping[str, Any] = (
            command_snapshot if isinstance(command_snapshot, Mapping) else {}
        )
        synthetic_command_name = str(
            command_values.get("synthetic_command_name") or ""
        )
        if synthetic_command_name not in {"", "__queue_full__"}:
            raise StoreError("unsupported synthetic command snapshot")
        candidate_route_values: Mapping[str, Any] = (
            candidate_specs[0] if candidate_specs else {}
        )

        def route_value(name: str, default: Any = None) -> Any:
            for values in (task_values, command_values, candidate_route_values):
                value = values.get(name)
                if value not in (None, ""):
                    return value
            return default

        def route_int(name: str, default: int = 1) -> int:
            value = route_value(name, default)
            try:
                return int(value)
            except (TypeError, ValueError):
                return default

        # Explicit legacy candidate specs still require the compatibility
        # confirmation path. Current voice ingress supplies ordinary task text
        # and leaves this collection empty.
        if candidate_specs:
            create_task = False
        now = self._now()
        # Commands are not tasks, but their route/mode still needs the same
        # immutable replay semantics.  Store the snapshot alongside the
        # inbound payload; the replay canonicalizer deliberately ignores this
        # reserved diagnostic key so a newer in-memory route cannot turn a
        # duplicate into a conflicting envelope.
        inbound_payload = self._sanitize_inbound_payload(
            message.payload,
            trusted_media_wire_fingerprints=(
                _trusted_media_wire_fingerprints
            ),
        )
        # Reserved snapshots are written only from the trusted acceptance
        # arguments below.  A channel payload cannot inject an Agent route or
        # command authorization hint by using an internal-looking key.
        inbound_payload.pop("__command_snapshot", None)
        inbound_payload.pop("__route_snapshot", None)
        if command_snapshot is not None and not create_task:
            inbound_payload["__command_snapshot"] = dict(command_values)
        # Persist the route selected for this immutable ingress identity.  It
        # is an internal authorization hint (excluded from replay comparison
        # and Agent inputs), and lets a pending audio candidate prove which
        # Agent owns an inbound attachment before a task exists.
        route_agent = str(
            route_value(
                "agent_id",
                "codex" if (create_task or candidate_specs) else "",
            )
            or ""
        ).strip()
        if route_agent:
            inbound_payload["__route_snapshot"] = {
                "agent_id": route_agent,
                "mode_id": str(route_value("mode_id", "chat") or "chat"),
                "profile_version": route_int("profile_version"),
                "policy_version": route_int("policy_version"),
            }

        def op(conn: sqlite3.Connection) -> InboundAcceptance:
            with _transaction(conn):
                identity = self._ensure_inbound_identity_tx(
                    conn, message, now=now
                )
                insert_cursor = conn.execute(
                    """INSERT OR IGNORE INTO inbound_messages
                       (message_id, channel, bot_id, external_user_id,
                        external_message_id, session_id, source_sequence,
                        context_token, text, payload_json, status,
                        received_at, stored_at, principal_id,
                        principal_account_id, conversation_subject_id,
                        identity_snapshot_json)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'stored', ?, ?, ?, ?, ?, ?)""",
                    (
                        message.message_id,
                        message.channel,
                        message.bot_id,
                        message.external_user_id,
                        message.external_message_id,
                        message.session_id,
                        message.source_sequence,
                        message.context_token,
                        message.text,
                        json_dumps(inbound_payload),
                        _utc_text(message.received_at),
                        now,
                        identity["principal_id"],
                        identity["principal_account_id"],
                        identity["conversation_subject_id"],
                        json_dumps(identity["identity_snapshot"]),
                    ),
                )
                row = conn.execute(
                    "SELECT * FROM inbound_messages WHERE channel = ? AND bot_id = ? AND external_message_id = ?",
                    message.dedupe_identity,
                ).fetchone()
                if row is None:
                    raise StoreError("failed to persist inbound message")
                if insert_cursor.rowcount == 0:
                    self._validate_inbound_replay_tx(
                        row,
                        message,
                        trusted_media_wire_fingerprints=(
                            _trusted_media_wire_fingerprints
                        ),
                    )
                if (
                    str(row["external_user_id"] or "")
                    != str(message.external_user_id or "")
                    or str(row["session_id"] or "default")
                    != str(message.session_id or "default")
                ):
                    raise StoreError(
                        "inbound identity conflicts with an existing user/session"
                    )
                # The reply allowance is part of ingress durability.  Create
                # it before routing, validation, command handling, or task
                # publication so every later user response has one allocator.
                self._ensure_reply_scope_for_inbound_row_tx(conn, row)
                persisted = self._inbound_from_row(row)
                duplicate = insert_cursor.rowcount == 0
                existing_task = None
                if persisted.task_id:
                    existing_task = self._fetch_task_tx(conn, persisted.task_id)
                retain_agent_id: str | None = (
                    str(
                        route_value("agent_id", "")
                        or ("codex" if (create_task or candidate_specs) else "")
                    )
                    or None
                )
                if duplicate:
                    # Replays must use the first accepted route when checking
                    # owner-agent metadata.  A later /agent switch is not an
                    # authorization change for the immutable inbound row.
                    stored_payload = json_loads(row["payload_json"], {}) or {}
                    stored_route = (
                        stored_payload.get("__route_snapshot", {})
                        if isinstance(stored_payload, Mapping)
                        else {}
                    )
                    stored_agent = (
                        stored_route.get("agent_id")
                        if isinstance(stored_route, Mapping)
                        else None
                    )
                    if not stored_agent and existing_task is not None:
                        stored_agent = existing_task.agent_id
                    if not stored_agent:
                        candidate_owner = conn.execute(
                            "SELECT agent_id FROM transcription_candidates "
                            "WHERE inbound_message_id=? ORDER BY created_at ASC "
                            "LIMIT 1",
                            (persisted.message_id,),
                        ).fetchone()
                        if candidate_owner is not None:
                            stored_agent = candidate_owner["agent_id"]
                    retain_agent_id = str(stored_agent or "") or None
                self._retain_inbound_attachments_tx(
                    conn,
                    message_id=persisted.message_id,
                    attachments=self._input_attachment_values(
                        json_loads(row["payload_json"], {}) or {}
                    ),
                    channel=str(row["channel"] or ""),
                    bot_id=str(row["bot_id"] or ""),
                    external_user_id=str(row["external_user_id"] or ""),
                    session_id=str(row["session_id"] or "default"),
                    source_message_id=str(row["external_message_id"] or ""),
                    agent_id=retain_agent_id,
                    created_at=row["stored_at"],
                )
                # The channel cursor and inbound ownership move in the same
                # transaction.  A crash can therefore never acknowledge a
                # cursor whose message row was rolled back.
                cursor_scope = (
                    cursor_channel or persisted.channel,
                    cursor_bot_id or persisted.bot_id,
                )
                existing_cursor = conn.execute(
                    "SELECT cursor FROM channel_cursors WHERE channel=? AND bot_id=?",
                    cursor_scope,
                ).fetchone()
                current_cursor = (
                    str(existing_cursor["cursor"])
                    if existing_cursor is not None
                    else None
                )
                if _cursor_should_advance(current_cursor, cursor_value):
                    conn.execute(
                        """INSERT INTO channel_cursors(channel, bot_id, cursor, updated_at)
                           VALUES (?, ?, ?, ?)
                           ON CONFLICT(channel, bot_id)
                           DO UPDATE SET cursor=excluded.cursor, updated_at=excluded.updated_at""",
                        (
                            cursor_scope[0],
                            cursor_scope[1],
                            str(cursor_value),
                            now,
                        ),
                    )
                if duplicate:
                    # The first committed acceptance owns both task meaning
                    # and audio-candidate policy.  A plain ``stored`` row with
                    # no task is the one exception: it may be the durable half
                    # of a store-then-create flow interrupted by a crash, so a
                    # task-creating replay is allowed to repair it below.
                    # Commands are advanced to ``accepted`` and audio ingress
                    # to ``awaiting_confirmation`` on their first acceptance,
                    # preventing either from being reinterpreted as Agent work.
                    prior_candidates = conn.execute(
                        "SELECT confirmation_id FROM transcription_candidates "
                        "WHERE inbound_message_id=? "
                        "ORDER BY created_at ASC, confirmation_id ASC",
                        (persisted.message_id,),
                    ).fetchall()
                    steering_row = conn.execute(
                        "SELECT * FROM task_steering WHERE inbound_message_id=?",
                        (persisted.message_id,),
                    ).fetchone()
                    if steering_row is not None:
                        steering = self._task_steering_from_row(steering_row)
                        linked_task_id = str(persisted.task_id or "")
                        if not linked_task_id and steering is not None:
                            linked_task_id = str(
                                steering.promoted_task_id
                                or steering.target_task_id
                            )
                        linked_task = (
                            self._fetch_task_tx(conn, linked_task_id)
                            if linked_task_id
                            else None
                        )
                        if linked_task is None:
                            raise StoreError(
                                "task steering replay has no linked task"
                            )
                        return InboundAcceptance(
                            persisted,
                            linked_task,
                            created=False,
                            duplicate=True,
                            steering=steering,
                        )
                    if (
                        not create_task
                        or existing_task is not None
                        or persisted.status != InboundState.STORED
                        or prior_candidates
                    ):
                        return InboundAcceptance(
                            persisted,
                            existing_task,
                            created=False,
                            duplicate=True,
                            confirmation_ids=tuple(
                                str(item["confirmation_id"])
                                for item in prior_candidates
                            ),
                        )
                confirmation_ids: list[str] = []
                for ordinal, spec in enumerate(candidate_specs):
                    candidate_text = str(
                        spec.get(
                            "candidate_text",
                            spec.get("text", spec.get("transcript", "")),
                        )
                        or ""
                    ).strip()
                    if not candidate_text:
                        raise ValueError("candidate_text cannot be empty")
                    confirmation_id = str(
                        spec.get("confirmation_id")
                        or uuid.uuid5(
                            uuid.NAMESPACE_URL,
                            "codex-transcription:"
                            + persisted.message_id
                            + ":"
                            + str(spec.get("ordinal", ordinal)),
                        )
                    )
                    expires_at_supplied = "expires_at" in spec
                    expires_value = spec.get("expires_at")
                    candidate_expiry = (
                        _utc_text(expires_value)
                        if expires_at_supplied and expires_value is not None
                        else (
                            None
                            if expires_at_supplied
                            else self._default_transcription_expiry(now)
                        )
                    )
                    self._insert_transcription_candidate_tx(
                        conn,
                        confirmation_id=confirmation_id,
                        channel=persisted.channel,
                        bot_id=persisted.bot_id,
                        external_user_id=persisted.external_user_id,
                        session_id=persisted.session_id,
                        agent_id=str(
                            spec.get("agent_id")
                            or task_values.get("agent_id")
                            or command_values.get("agent_id")
                            or "codex"
                        ),
                        mode_id=str(
                            spec.get("mode_id")
                            or task_values.get("mode_id")
                            or command_values.get("mode_id")
                            or "chat"
                        ),
                        profile_version=int(
                            spec.get("profile_version")
                            or task_values.get("profile_version")
                            or command_values.get("profile_version")
                            or 1
                        ),
                        policy_version=int(
                            spec.get("policy_version")
                            or task_values.get("policy_version")
                            or command_values.get("policy_version")
                            or 1
                        ),
                        metadata=(
                            spec.get("metadata")
                            if spec.get("metadata") is not None
                            else task_values.get("metadata", {})
                        ),
                        attachment_id=(
                            str(spec["attachment_id"])
                            if spec.get("attachment_id")
                            else None
                        ),
                        inbound_message_id=persisted.message_id,
                        candidate_text=candidate_text,
                        source=str(spec.get("source") or "channel"),
                        confidence=(
                            float(spec["confidence"])
                            if spec.get("confidence") is not None
                            else None
                        ),
                        created_at=now,
                        expires_at=candidate_expiry,
                        expires_at_supplied=expires_at_supplied,
                    )
                    confirmation_ids.append(confirmation_id)
                if not create_task:
                    if not confirmation_ids:
                        self._transition_inbound_tx(
                            conn,
                            persisted.message_id,
                            InboundState.ACCEPTED,
                            now=now,
                        )
                    # Candidate insertion above may have advanced the inbound
                    # state; return the refreshed envelope in the same commit.
                    refreshed_inbound = self._inbound_from_row(
                        conn.execute(
                            "SELECT * FROM inbound_messages WHERE message_id=?",
                            (persisted.message_id,),
                        ).fetchone()
                    )
                    return InboundAcceptance(
                        refreshed_inbound,
                        existing_task,
                        created=not duplicate,
                        duplicate=duplicate,
                        confirmation_ids=tuple(confirmation_ids),
                    )
                # Build a task snapshot from the inbound envelope.  The task
                # carries the original reply target even if the active route
                # changes before execution.
                task_values.setdefault("inbound_message_id", persisted.message_id)
                task_values.setdefault("dedupe_key", f"inbound:{persisted.message_id}")
                task_values.setdefault("channel", persisted.channel)
                task_values.setdefault("bot_id", persisted.bot_id)
                task_values.setdefault("session_id", persisted.session_id)
                subject_snapshot = (
                    persisted.identity_snapshot.get("conversation_subject", {})
                    if isinstance(persisted.identity_snapshot, Mapping)
                    else {}
                )
                if not isinstance(subject_snapshot, Mapping):
                    subject_snapshot = {}
                route_user_id = str(
                    subject_snapshot.get("scope_key")
                    or persisted.external_user_id
                )
                task_values["actor_external_user_id"] = persisted.external_user_id
                task_values["principal_id"] = persisted.principal_id
                task_values["principal_account_id"] = persisted.principal_account_id
                task_values["conversation_subject_id"] = (
                    persisted.conversation_subject_id
                )
                task_values["identity_snapshot"] = dict(
                    persisted.identity_snapshot or {}
                )
                if "inputs" not in task_values:
                    fallback_inputs: dict[str, Any] = {"text": persisted.text}
                    for key in ("media", "attachments", "images"):
                        value = persisted.payload.get(key)
                        if value is not None:
                            fallback_inputs[key] = list(
                                canonical_media_inputs(value)
                            )
                    task_values["inputs"] = fallback_inputs
                task_values.setdefault("reply_target", persisted.target())
                snapshot = self._coerce_task(task, task_values)
                # Inline task insertion avoids a nested async call and keeps
                # ingress, task ownership, and inbound status atomic.
                channel_value = persisted.channel
                bot_value = persisted.bot_id
                user_value = route_user_id
                session_value = persisted.session_id
                conversation_id = self._ensure_conversation_tx(
                    conn,
                    snapshot,
                    channel=channel_value,
                    bot_id=bot_value,
                    external_user_id=user_value,
                    session_id=session_value,
                    now=now,
                )
                role_snapshot = self._task_role_snapshot_tx(
                    conn,
                    metadata=snapshot.metadata,
                    channel=channel_value,
                    bot_id=bot_value,
                    external_user_id=user_value,
                    session_id=session_value,
                    agent_id=snapshot.agent_id,
                )
                role_version, role_hash, persona_version = role_binding_key(
                    role_snapshot
                )
                thread_id = self._resolve_task_thread_tx(
                    conn,
                    supplied_thread_id=snapshot.thread_id,
                    conversation_id=conversation_id,
                    mode_id=snapshot.mode_id,
                    profile_version=snapshot.profile_version,
                    policy_version=snapshot.policy_version,
                    role_version=role_version,
                    role_snapshot_hash=role_hash,
                    persona_composition_version=persona_version,
                )
                dedupe = snapshot.dedupe_key or f"inbound:{persisted.message_id}"
                existing = self._fetch_task_by_dedupe_tx(conn, dedupe)
                if existing is not None:
                    self._validate_dedupe_owner(
                        existing,
                        channel=channel_value,
                        bot_id=bot_value,
                        external_user_id=user_value,
                        session_id=session_value,
                        agent_id=snapshot.agent_id,
                        parent_task_id=snapshot.parent_task_id,
                        conversation_id=conversation_id,
                    )
                child_parent_id = None
                if existing is None and snapshot.parent_task_id:
                    child_parent_id = self._validate_child_parent_tx(
                        conn,
                        snapshot,
                        channel=channel_value,
                        bot_id=bot_value,
                        external_user_id=user_value,
                        session_id=session_value,
                    )
                if existing is None:
                    task_id = snapshot.task_id or _uuid()
                    target = self._coerce_reply_target(snapshot.reply_target, fallback=persisted.target())
                    self._validate_reply_target_scope(
                        target,
                        channel=persisted.channel,
                        bot_id=persisted.bot_id,
                        external_user_id=persisted.external_user_id,
                        session_id=persisted.session_id,
                    )
                    agent_incarnation = self._current_agent_incarnation_tx(
                        conn, snapshot.agent_id, int(snapshot.profile_version)
                    )
                    self._promote_terminal_steering_predecessors_tx(
                        conn,
                        agent_id=snapshot.agent_id,
                        agent_incarnation=agent_incarnation,
                        conversation_id=conversation_id,
                        now=now,
                        max_agent_queue=self.max_agent_queue,
                        max_global_queue=self.max_global_queue,
                        max_account_queue=self.max_account_queue,
                        max_account_agent_queue=self.max_account_agent_queue,
                    )
                    active_rows = conn.execute(
                        """SELECT t.*, e.execution_id AS steering_execution_id,
                                  e.state AS steering_execution_state
                             FROM tasks AS t
                             JOIN task_executions AS e
                               ON e.execution_id=t.current_execution_id
                              AND e.task_id=t.task_id
                              AND e.agent_id=t.agent_id
                              AND e.agent_incarnation=t.agent_incarnation
                            WHERE t.agent_id=? AND t.agent_incarnation=?
                              AND t.conversation_id=?
                              AND t.state IN ('dispatching','running')
                              AND e.state IN ('dispatching','running')
                              AND t.claim_token IS NOT NULL
                              AND e.claim_token=t.claim_token
                              AND t.lease_expires_at IS NOT NULL
                              AND e.lease_expires_at IS NOT NULL
                              AND t.lease_expires_at>?
                              AND e.lease_expires_at>?
                            ORDER BY t.created_at,t.task_id""",
                        (
                            snapshot.agent_id,
                            int(agent_incarnation),
                            conversation_id,
                            now,
                            now,
                        ),
                    ).fetchall()
                    compatible_rows = [
                        row
                        for row in active_rows
                        if self._steering_context_compatible(
                            row,
                            snapshot,
                            conversation_id=conversation_id,
                            thread_id=thread_id,
                            agent_incarnation=agent_incarnation,
                        )
                    ]
                    # Steering is an in-place continuation of an active turn,
                    # so it would otherwise jump ahead of an older turn that
                    # is already waiting in the same canonical conversation.
                    # Keep this gate conversation-wide (rather than comparing
                    # mode/model metadata): a context switch queued between
                    # two compatible chat messages must still retain A-B-C
                    # ingress order.
                    has_queued_predecessor = conn.execute(
                        """SELECT 1
                             FROM tasks AS queued
                             JOIN agent_invocations AS invocation
                               ON invocation.invocation_id=
                                  queued.current_execution_id
                              AND invocation.work_kind='task'
                              AND invocation.task_id=queued.task_id
                              AND invocation.execution_id=
                                  queued.current_execution_id
                              AND invocation.agent_id=queued.agent_id
                              AND invocation.agent_incarnation=
                                  queued.agent_incarnation
                            WHERE queued.agent_id=?
                              AND queued.agent_incarnation=?
                              AND queued.conversation_id=?
                              AND queued.state='queued'
                              AND invocation.state='queued'
                            LIMIT 1""",
                        (
                            snapshot.agent_id,
                            int(agent_incarnation),
                            conversation_id,
                        ),
                    ).fetchone() is not None
                    # A child-task request has explicit orchestration meaning
                    # and must never be folded into an unrelated live turn.
                    if (
                        len(compatible_rows) == 1
                        and not snapshot.parent_task_id
                        and not has_queued_predecessor
                    ):
                        active = compatible_rows[0]
                        active_task_id = str(active["task_id"])
                        active_execution_id = str(
                            active["steering_execution_id"]
                        )
                        steering_id = str(
                            uuid.uuid5(
                                uuid.NAMESPACE_URL,
                                "codex-task-steering:" + persisted.message_id,
                            )
                        )
                        fallback_task_id = str(
                            uuid.uuid5(
                                uuid.NAMESPACE_URL,
                                "codex-task-steering-fallback:" + steering_id,
                            )
                        )
                        sequence = int(
                            conn.execute(
                                "SELECT COALESCE(MAX(sequence),0)+1 "
                                "FROM task_steering WHERE target_execution_id=?",
                                (active_execution_id,),
                            ).fetchone()[0]
                        )
                        frozen_task = self._task_snapshot_for_steering(
                            snapshot,
                            inbound=persisted,
                            route_external_user_id=user_value,
                            conversation_id=conversation_id,
                            thread_id=thread_id,
                            agent_incarnation=agent_incarnation,
                            reply_target=target,
                        )
                        self._validate_task_input_attachment_access_tx(
                            conn,
                            task_id=active_task_id,
                            inbound_message_id=persisted.message_id,
                            inputs=snapshot.inputs,
                            agent_id=snapshot.agent_id,
                            channel=channel_value,
                            bot_id=bot_value,
                            external_user_id=user_value,
                            session_id=session_value,
                        )
                        conn.execute(
                            """INSERT INTO task_steering
                               (steering_id,inbound_message_id,target_task_id,
                                target_execution_id,agent_id,agent_incarnation,
                                conversation_id,sequence,task_snapshot_json,state,
                                fallback_task_id,created_at,updated_at)
                               VALUES (?,?,?,?,?,?,?,?,?,'pending',?,?,?)""",
                            (
                                steering_id,
                                persisted.message_id,
                                active_task_id,
                                active_execution_id,
                                snapshot.agent_id,
                                int(agent_incarnation),
                                conversation_id,
                                sequence,
                                json_dumps(frozen_task),
                                fallback_task_id,
                                now,
                                now,
                            ),
                        )
                        self._retain_attachment_refs_tx(
                            conn,
                            owner_kind="task_steering",
                            owner_id=steering_id,
                            attachments=self._input_attachment_values(
                                snapshot.inputs
                            ),
                            role="input",
                            created_at=now,
                        )
                        self._transition_inbound_tx(
                            conn,
                            persisted.message_id,
                            InboundState.ACCEPTED,
                            now=now,
                            task_id=active_task_id,
                        )
                        steering = self._task_steering_from_row(
                            conn.execute(
                                "SELECT * FROM task_steering WHERE steering_id=?",
                                (steering_id,),
                            ).fetchone()
                        )
                        active_task = self._fetch_task_tx(conn, active_task_id)
                        if steering is None or active_task is None:
                            raise StoreError(
                                "task steering acceptance disappeared"
                            )
                        return InboundAcceptance(
                            self._inbound_from_row(
                                conn.execute(
                                    "SELECT * FROM inbound_messages WHERE message_id=?",
                                    (persisted.message_id,),
                                ).fetchone()
                            ),
                            active_task,
                            created=True,
                            duplicate=False,
                            steering=steering,
                        )
                    conn.execute(
                        """INSERT INTO tasks
                           (task_id, dedupe_key, inbound_message_id, channel, bot_id,
                            external_user_id, session_id, agent_id, agent_incarnation, conversation_id,
                            thread_id, mode_id, profile_version, policy_version,
                            model, reasoning_effort, reply_target_json, inputs_json,
                            metadata_json, actor_external_user_id, principal_id,
                            principal_account_id, conversation_subject_id,
                            identity_snapshot_json,
                            state, attempts, next_attempt_at, parent_task_id,
                            child_depth, request_id, created_at, updated_at)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                                   ?, ?, ?, ?, ?,
                                   'queued', 0, ?, ?, ?, ?, ?, ?)""",
                        (
                            task_id, dedupe, persisted.message_id, channel_value,
                            bot_value, user_value, session_value, snapshot.agent_id,
                            agent_incarnation,
                            conversation_id, thread_id, snapshot.mode_id,
                            int(snapshot.profile_version), int(snapshot.policy_version),
                            snapshot.model, snapshot.reasoning_effort,
                            json_dumps(target.to_dict()), json_dumps(_snapshot_value(snapshot.inputs)),
                            json_dumps(_snapshot_value(snapshot.metadata, text_key="value")),
                            snapshot.actor_external_user_id,
                            snapshot.principal_id,
                            snapshot.principal_account_id,
                            snapshot.conversation_subject_id,
                            json_dumps(_snapshot_value(snapshot.identity_snapshot)),
                            None, snapshot.parent_task_id, int(snapshot.child_depth),
                            snapshot.request_id, now, now,
                        ),
                    )
                    # Make the inbound ref resolve to this Agent while the
                    # attachment validator runs.  The surrounding transaction
                    # guarantees a denial cannot leak this provisional link.
                    conn.execute(
                        "UPDATE inbound_messages SET task_id = ?, status = 'task_queued' WHERE message_id = ?",
                        (task_id, persisted.message_id),
                    )
                    self._validate_task_input_attachment_access_tx(
                        conn,
                        task_id=task_id,
                        inbound_message_id=persisted.message_id,
                        inputs=snapshot.inputs,
                        agent_id=snapshot.agent_id,
                        channel=channel_value,
                        bot_id=bot_value,
                        external_user_id=user_value,
                        session_id=session_value,
                    )
                    self._retain_task_input_attachments_tx(
                        conn,
                        task_id=task_id,
                        inputs=snapshot.inputs,
                        created_at=now,
                    )
                    if child_parent_id is not None:
                        self._update_child_counter_tx(
                            conn, child_parent_id, now=now
                        )
                    self._create_queued_task_invocation_tx(
                        conn,
                        task_id=task_id,
                        now=now,
                        max_agent_queue=self.max_agent_queue,
                        max_global_queue=self.max_global_queue,
                        max_account_queue=self.max_account_queue,
                        max_account_agent_queue=self.max_account_agent_queue,
                    )
                    existing = self._fetch_task_tx(conn, task_id)
                    return InboundAcceptance(
                        self._inbound_from_row(
                            conn.execute("SELECT * FROM inbound_messages WHERE message_id = ?", (persisted.message_id,)).fetchone()
                        ),
                        existing,
                        created=True,
                        duplicate=duplicate,
                    )
                conn.execute(
                    "UPDATE inbound_messages SET task_id = ?, status = 'task_queued' WHERE message_id = ?",
                    (existing.task_id, persisted.message_id),
                )
                self._retain_task_input_attachments_tx(
                    conn,
                    task_id=existing.task_id,
                    inputs=existing.inputs,
                    created_at=existing.created_at,
                )
                refreshed = self._inbound_from_row(
                    conn.execute("SELECT * FROM inbound_messages WHERE message_id = ?", (persisted.message_id,)).fetchone()
                )
                return InboundAcceptance(refreshed, existing, created=False, duplicate=duplicate)

        try:
            return await self._call(op)
        except sqlite3.IntegrityError as exc:
            # The entire transaction rolled back.  A concurrent transaction
            # may have already accepted this identity.  Only repair through
            # the replay path when that winner is demonstrably durable.  If
            # the identity is absent, the integrity error came from task or
            # projection insertion and acknowledging a newly stored inbound
            # would lose user work and advance the channel cursor.
            winner = await self.get_inbound(
                message.channel,
                message.bot_id,
                message.external_message_id,
            )
            if winner is None:
                raise StoreError(str(exc)) from exc
            existing = await self.store_inbound(
                message,
                cursor=cursor_value,
                cursor_channel=cursor_channel,
                cursor_bot_id=cursor_bot_id,
            )
            if existing is not None:
                existing_task = await self.get_task_by_inbound(existing.message_id)
                existing_steering = await self.get_task_steering_by_inbound(
                    existing.message_id
                )
                if existing_task is None and existing_steering is not None:
                    existing_task = await self.get_task(
                        existing_steering.promoted_task_id
                        or existing_steering.target_task_id
                    )
                # A durable inbound row is not proof that the requested task
                # projection committed.  In the store-then-create recovery
                # path, an unrelated task constraint (for example a reused
                # task_id) can fail after the existing inbound was found.  Do
                # not acknowledge that failure as a harmless duplicate and
                # strand the message permanently in ``stored``.
                if (
                    create_task
                    and existing_task is None
                    and existing_steering is None
                ):
                    raise StoreError(str(exc)) from exc
                confirmation_ids = await self._call(
                    lambda conn: tuple(
                        str(row["confirmation_id"])
                        for row in conn.execute(
                            "SELECT confirmation_id FROM transcription_candidates "
                            "WHERE inbound_message_id=? "
                            "ORDER BY created_at ASC, confirmation_id ASC",
                            (existing.message_id,),
                        ).fetchall()
                    )
                )
                return InboundAcceptance(
                    existing,
                    existing_task,
                    created=False,
                    duplicate=True,
                    confirmation_ids=confirmation_ids,
                    steering=existing_steering,
                )
            raise StoreError(str(exc)) from exc

    # Compatibility names for gateways and tests.
    ingest_inbound = accept_inbound
    accept_message = accept_inbound

    async def get_inbound(
        self,
        channel_or_message_id: str,
        bot_id: str | None = None,
        external_message_id: str | None = None,
    ) -> InboundMessage | None:
        """Look up ingress by internal id or durable channel identity."""

        def op(conn: sqlite3.Connection) -> InboundMessage | None:
            if bot_id is None and external_message_id is None:
                row = conn.execute(
                    "SELECT * FROM inbound_messages WHERE message_id = ?",
                    (channel_or_message_id,),
                ).fetchone()
            else:
                row = conn.execute(
                    "SELECT * FROM inbound_messages WHERE channel = ? AND bot_id = ? AND external_message_id = ?",
                    (channel_or_message_id, bot_id or "", external_message_id or ""),
                ).fetchone()
            return self._inbound_from_row(row) if row is not None else None

        return await self._call(op)

    get_inbound_message = get_inbound

    async def get_reply_scope(
        self, reply_scope_id: str
    ) -> ReplyScopeRecord | None:
        """Return one immutable inbound reply allowance by its stable ID."""

        return await self._call(
            lambda conn: self._reply_scope_from_row(
                conn.execute(
                    "SELECT * FROM reply_scopes WHERE reply_scope_id=?",
                    (str(reply_scope_id),),
                ).fetchone()
            )
        )

    async def get_reply_scope_for_inbound(
        self, inbound_message_id: str
    ) -> ReplyScopeRecord | None:
        """Return the sole reply scope owned by a stored inbound row."""

        return await self._call(
            lambda conn: self._reply_scope_from_row(
                conn.execute(
                    "SELECT * FROM reply_scopes WHERE inbound_message_id=?",
                    (str(inbound_message_id),),
                ).fetchone()
            )
        )

    async def get_reply_scope_for_target(
        self, target: ReplyTarget | Mapping[str, Any]
    ) -> ReplyScopeRecord | None:
        """Resolve an exact persisted target without using its context token."""

        reply_target = self._coerce_reply_target(target)

        def op(conn: sqlite3.Connection) -> ReplyScopeRecord | None:
            return self._reply_scope_from_row(
                self._reply_scope_for_target_tx(conn, reply_target)
            )

        return await self._call(op)

    async def set_inbound_status(
        self,
        message_id: str,
        status: InboundState | str,
        *,
        task_id: str | None = None,
        now: datetime | str | None = None,
    ) -> bool:
        """Apply an explicit durable inbound state transition."""
        try:
            target = InboundState(str(_enum_value(status)))
        except ValueError as exc:
            raise InvalidTransition(f"unknown inbound state: {status!r}") from exc
        now_text = self._now(now)

        def op(conn: sqlite3.Connection) -> bool:
            with _transaction(conn):
                return self._transition_inbound_tx(
                    conn,
                    message_id,
                    target,
                    now=now_text,
                    task_id=task_id,
                )

        return await self._call(op)

    update_inbound_status = set_inbound_status

    async def list_inbound(self, *, limit: int = 100) -> list[InboundMessage]:
        def op(conn: sqlite3.Connection) -> list[InboundMessage]:
            rows = conn.execute(
                "SELECT * FROM inbound_messages ORDER BY stored_at DESC, message_id DESC LIMIT ?",
                (max(0, int(limit)),),
            ).fetchall()
            return [self._inbound_from_row(row) for row in rows]

        return await self._call(op)

    async def get_task(self, task_id: str) -> TaskRecord | None:
        return await self._call(lambda conn: self._fetch_task_tx(conn, task_id))

    async def require_task(self, task_id: str) -> TaskRecord:
        task = await self.get_task(task_id)
        if task is None:
            raise NotFoundError(f"task not found: {task_id}")
        return task

    async def get_execution(self, execution_id: str) -> TaskExecution | None:
        """Load one concrete execution attempt by its durable ID."""

        return await self._call(
            lambda conn: self._execution_from_row(
                conn.execute(
                    "SELECT * FROM task_executions WHERE execution_id=?",
                    (execution_id,),
                ).fetchone()
            )
        )

    get_task_execution = get_execution

    async def get_task_steering(
        self, steering_id: str
    ) -> TaskSteeringRecord | None:
        return await self._call(
            lambda conn: self._task_steering_from_row(
                conn.execute(
                    "SELECT * FROM task_steering WHERE steering_id=?",
                    (str(steering_id),),
                ).fetchone()
            )
        )

    async def get_task_steering_by_inbound(
        self, inbound_message_id: str
    ) -> TaskSteeringRecord | None:
        return await self._call(
            lambda conn: self._task_steering_from_row(
                conn.execute(
                    "SELECT * FROM task_steering WHERE inbound_message_id=?",
                    (str(inbound_message_id),),
                ).fetchone()
            )
        )

    async def list_pending_task_steering(
        self,
        *,
        task_id: str | None = None,
        execution_id: str | None = None,
        limit: int = 100,
    ) -> list[TaskSteeringRecord]:
        filters = ["state='pending'"]
        params: list[Any] = []
        if task_id is not None:
            filters.append("target_task_id=?")
            params.append(str(task_id))
        if execution_id is not None:
            filters.append("target_execution_id=?")
            params.append(str(execution_id))
        params.append(max(0, int(limit)))

        def op(conn: sqlite3.Connection) -> list[TaskSteeringRecord]:
            rows = conn.execute(
                "SELECT * FROM task_steering WHERE "
                + " AND ".join(filters)
                + " ORDER BY target_execution_id,sequence,steering_id LIMIT ?",
                params,
            ).fetchall()
            return [
                item
                for row in rows
                if (item := self._task_steering_from_row(row)) is not None
            ]

        return await self._call(op)

    async def claim_next_task_steering(
        self,
        task_id: str,
        execution_id: str,
        *,
        task_claim_token: str,
        claimed_by: str,
        lease_seconds: float = 60.0,
        now: datetime | str | None = None,
    ) -> TaskSteeringClaim | None:
        """Claim the next FIFO steer under the exact live execution lease."""

        worker = str(claimed_by or "").strip()
        owner_token = str(task_claim_token or "").strip()
        try:
            lease_value = float(lease_seconds)
        except (TypeError, ValueError) as exc:
            raise ValueError("lease_seconds must be a finite positive number") from exc
        if not worker or not owner_token:
            raise ValueError("task steering claim identity is required")
        if not math.isfinite(lease_value) or lease_value <= 0:
            raise ValueError("lease_seconds must be a finite positive number")
        now_text = self._now(now)
        now_value = text_to_datetime(now_text)
        assert now_value is not None
        lease_expires_at = _utc_text(now_value + timedelta(seconds=lease_value))

        def op(conn: sqlite3.Connection) -> TaskSteeringClaim | None:
            with _transaction(conn):
                # An expired delivery lease cannot prove whether runner input
                # crossed the IPC boundary.  Fence it as uncertain forever;
                # never make it claimable again.
                conn.execute(
                    """UPDATE task_steering
                          SET state='delivery_unknown',claimed_by=NULL,
                              claim_token=NULL,lease_expires_at=NULL,updated_at=?
                        WHERE target_task_id=? AND target_execution_id=?
                          AND state='delivering' AND lease_expires_at<=?""",
                    (now_text, str(task_id), str(execution_id), now_text),
                )
                owner = conn.execute(
                    """SELECT t.state AS task_state,t.claimed_by AS task_worker,
                              t.claim_token AS task_token,
                              t.lease_expires_at AS task_lease,
                              e.state AS execution_state,
                              e.worker_id AS execution_worker,
                              e.claim_token AS execution_token,
                              e.lease_expires_at AS execution_lease,
                              e.finished_at
                         FROM tasks AS t
                         JOIN task_executions AS e
                           ON e.execution_id=t.current_execution_id
                          AND e.task_id=t.task_id
                        WHERE t.task_id=? AND e.execution_id=?""",
                    (str(task_id), str(execution_id)),
                ).fetchone()
                if owner is None:
                    return None
                if (
                    str(owner["task_state"]) not in {"dispatching", "running"}
                    or str(owner["execution_state"])
                    not in {"dispatching", "running"}
                    or owner["finished_at"] is not None
                    or str(owner["task_worker"] or "") != worker
                    or str(owner["execution_worker"] or "") != worker
                    or str(owner["task_token"] or "") != owner_token
                    or str(owner["execution_token"] or "") != owner_token
                    or not self._lease_is_active(owner["task_lease"], now_text)
                    or not self._lease_is_active(
                        owner["execution_lease"], now_text
                    )
                ):
                    return None
                head = conn.execute(
                    """SELECT * FROM task_steering
                        WHERE target_task_id=? AND target_execution_id=?
                          AND state IN
                              ('pending','delivering','delivery_unknown')
                        ORDER BY sequence,steering_id LIMIT 1""",
                    (str(task_id), str(execution_id)),
                ).fetchone()
                if head is None or str(head["state"]) != "pending":
                    return None
                delivery_token = _uuid()
                changed = conn.execute(
                    """UPDATE task_steering
                          SET state='delivering',claimed_by=?,claim_token=?,
                              lease_expires_at=?,updated_at=?
                        WHERE steering_id=? AND state='pending'""",
                    (
                        worker,
                        delivery_token,
                        lease_expires_at,
                        now_text,
                        head["steering_id"],
                    ),
                ).rowcount
                if changed != 1:
                    return None
                claimed = self._task_steering_from_row(
                    conn.execute(
                        "SELECT * FROM task_steering WHERE steering_id=?",
                        (head["steering_id"],),
                    ).fetchone()
                )
                if claimed is None:
                    raise StoreError("claimed task steering disappeared")
                return TaskSteeringClaim(claimed, delivery_token)

        return await self._call(op)

    async def mark_task_steering_applied(
        self,
        steering_id: str,
        *,
        claim_token: str,
        now: datetime | str | None = None,
    ) -> TaskSteeringRecord:
        """Commit a positive runner acknowledgement exactly once."""

        token = str(claim_token or "")
        if not token:
            raise ValueError("task steering claim token is required")
        now_text = self._now(now)

        def op(conn: sqlite3.Connection) -> TaskSteeringRecord:
            with _transaction(conn):
                row = conn.execute(
                    "SELECT * FROM task_steering WHERE steering_id=?",
                    (str(steering_id),),
                ).fetchone()
                if row is None:
                    raise NotFoundError(f"task steering not found: {steering_id}")
                if str(row["state"]) == "applied":
                    result = self._task_steering_from_row(row)
                    assert result is not None
                    return result
                changed = conn.execute(
                    """UPDATE task_steering
                          SET state='applied',applied_at=?,updated_at=?,
                              claimed_by=NULL,claim_token=NULL,
                              lease_expires_at=NULL
                        WHERE steering_id=? AND state='delivering'
                          AND claim_token=?""",
                    (now_text, now_text, str(steering_id), token),
                ).rowcount
                if changed != 1:
                    raise InvalidTransition(
                        "task steering acknowledgement lost its claim fence"
                    )
                result = self._task_steering_from_row(
                    conn.execute(
                        "SELECT * FROM task_steering WHERE steering_id=?",
                        (str(steering_id),),
                    ).fetchone()
                )
                if result is None:
                    raise StoreError("applied task steering disappeared")
                return result

        return await self._call(op)

    async def release_task_steering(
        self,
        steering_id: str,
        *,
        claim_token: str,
        delivery_unknown: bool = False,
        now: datetime | str | None = None,
    ) -> TaskSteeringRecord:
        """Release a proven-unsent claim or permanently fence uncertainty."""

        token = str(claim_token or "")
        if not token:
            raise ValueError("task steering claim token is required")
        now_text = self._now(now)
        target_state = (
            TaskSteeringState.DELIVERY_UNKNOWN
            if delivery_unknown
            else TaskSteeringState.PENDING
        )

        def op(conn: sqlite3.Connection) -> TaskSteeringRecord:
            with _transaction(conn):
                row = conn.execute(
                    "SELECT * FROM task_steering WHERE steering_id=?",
                    (str(steering_id),),
                ).fetchone()
                if row is None:
                    raise NotFoundError(f"task steering not found: {steering_id}")
                if str(row["state"]) == target_state.value:
                    result = self._task_steering_from_row(row)
                    assert result is not None
                    return result
                changed = conn.execute(
                    """UPDATE task_steering
                          SET state=?,claimed_by=NULL,claim_token=NULL,
                              lease_expires_at=NULL,updated_at=?
                        WHERE steering_id=? AND state='delivering'
                          AND claim_token=?""",
                    (target_state.value, now_text, str(steering_id), token),
                ).rowcount
                if changed != 1:
                    raise InvalidTransition(
                        "task steering release lost its claim fence"
                    )
                if target_state is TaskSteeringState.PENDING:
                    self._recover_task_steering_tx(
                        conn,
                        now=now_text,
                        process_boundary=False,
                        max_agent_queue=self.max_agent_queue,
                        max_global_queue=self.max_global_queue,
                        max_account_queue=self.max_account_queue,
                        max_account_agent_queue=self.max_account_agent_queue,
                    )
                result = self._task_steering_from_row(
                    conn.execute(
                        "SELECT * FROM task_steering WHERE steering_id=?",
                        (str(steering_id),),
                    ).fetchone()
                )
                if result is None:
                    raise StoreError("released task steering disappeared")
                return result

        return await self._call(op)

    async def promote_task_steering(
        self,
        steering_id: str,
        *,
        claim_token: str | None = None,
        now: datetime | str | None = None,
    ) -> InboundAcceptance:
        """Promote a pending head iff its exact target execution has ended."""

        now_text = self._now(now)

        def op(conn: sqlite3.Connection) -> InboundAcceptance:
            with _transaction(conn):
                row = conn.execute(
                    "SELECT * FROM task_steering WHERE steering_id=?",
                    (str(steering_id),),
                ).fetchone()
                if row is None:
                    raise NotFoundError(f"task steering not found: {steering_id}")
                if claim_token is not None and row["claim_token"] not in {
                    None,
                    str(claim_token),
                }:
                    raise InvalidTransition("task steering claim token does not match")
                current = self._task_steering_from_row(row)
                assert current is not None
                linked_task_id = str(
                    current.promoted_task_id or current.target_task_id
                )
                linked_task = self._fetch_task_tx(conn, linked_task_id)
                inbound_row = conn.execute(
                    "SELECT * FROM inbound_messages WHERE message_id=?",
                    (current.inbound_message_id,),
                ).fetchone()
                if linked_task is None or inbound_row is None:
                    raise StoreError("task steering promotion ownership is missing")
                if current.state is not TaskSteeringState.PENDING:
                    return InboundAcceptance(
                        self._inbound_from_row(inbound_row),
                        linked_task,
                        created=False,
                        duplicate=False,
                        steering=current,
                    )
                head = conn.execute(
                    """SELECT steering_id,state FROM task_steering
                        WHERE target_task_id=? AND target_execution_id=?
                          AND state IN ('pending','delivering')
                        ORDER BY sequence,steering_id LIMIT 1""",
                    (current.target_task_id, current.target_execution_id),
                ).fetchone()
                if (
                    head is None
                    or str(head["steering_id"]) != current.steering_id
                    or str(head["state"]) != "pending"
                ):
                    return InboundAcceptance(
                        self._inbound_from_row(inbound_row),
                        linked_task,
                        created=False,
                        duplicate=False,
                        steering=current,
                    )
                owner = conn.execute(
                    """SELECT t.state AS task_state,e.state AS execution_state,
                              e.finished_at
                         FROM tasks AS t
                         JOIN task_executions AS e
                           ON e.execution_id=? AND e.task_id=t.task_id
                        WHERE t.task_id=?""",
                    (current.target_execution_id, current.target_task_id),
                ).fetchone()
                if owner is None:
                    raise StoreError("task steering target execution is missing")
                if (
                    str(owner["task_state"])
                    in {"queued", "dispatching", "running", "cancel_requested"}
                    or str(owner["execution_state"])
                    in {"queued", "dispatching", "running", "cancel_requested"}
                    or owner["finished_at"] is None
                ):
                    return InboundAcceptance(
                        self._inbound_from_row(inbound_row),
                        linked_task,
                        created=False,
                        duplicate=False,
                        steering=current,
                    )
                promoted = self._promote_pending_steering_for_execution_tx(
                    conn,
                    task_id=current.target_task_id,
                    execution_id=current.target_execution_id,
                    now=now_text,
                    max_agent_queue=self.max_agent_queue,
                    max_global_queue=self.max_global_queue,
                    max_account_queue=self.max_account_queue,
                    max_account_agent_queue=self.max_account_agent_queue,
                )
                if promoted is None:
                    refreshed = self._task_steering_from_row(
                        conn.execute(
                            "SELECT * FROM task_steering WHERE steering_id=?",
                            (current.steering_id,),
                        ).fetchone()
                    )
                    assert refreshed is not None
                    return InboundAcceptance(
                        self._inbound_from_row(inbound_row),
                        linked_task,
                        created=False,
                        duplicate=False,
                        steering=refreshed,
                    )
                promoted_record, fallback = promoted
                promoted_inbound = conn.execute(
                    "SELECT * FROM inbound_messages WHERE message_id=?",
                    (promoted_record.inbound_message_id,),
                ).fetchone()
                assert promoted_inbound is not None
                return InboundAcceptance(
                    self._inbound_from_row(promoted_inbound),
                    fallback,
                    created=True,
                    duplicate=False,
                    steering=promoted_record,
                )

        return await self._call(op)

    async def recover_task_steering(
        self,
        *,
        now: datetime | str | None = None,
        process_boundary: bool = False,
        limit: int = 100,
    ) -> int:
        """Recover expired delivery claims and terminal-target fallbacks."""

        now_text = self._now(now)

        def op(conn: sqlite3.Connection) -> int:
            with _transaction(conn):
                return self._recover_task_steering_tx(
                    conn,
                    now=now_text,
                    process_boundary=bool(process_boundary),
                    max_agent_queue=self.max_agent_queue,
                    max_global_queue=self.max_global_queue,
                    max_account_queue=self.max_account_queue,
                    max_account_agent_queue=self.max_account_agent_queue,
                    limit=limit,
                )

        return await self._call(op)

    async def get_agent_invocation(
        self, invocation_id: str
    ) -> AgentInvocationRecord | None:
        return await self._call(
            lambda conn: self._invocation_from_row(
                conn.execute(
                    "SELECT * FROM agent_invocations WHERE invocation_id=?",
                    (str(invocation_id),),
                ).fetchone()
            )
        )

    async def list_agent_invocations(
        self,
        *,
        agent_id: str | None = None,
        agent_incarnation: int | None = None,
        state: InvocationState | str | None = None,
        work_kind: InvocationWorkKind | str | None = None,
        limit: int = 100,
    ) -> list[AgentInvocationRecord]:
        filters: list[str] = []
        params: list[Any] = []
        for column, value in (
            ("agent_id", agent_id),
            ("agent_incarnation", agent_incarnation),
            ("state", _enum_value(state) if state is not None else None),
            ("work_kind", _enum_value(work_kind) if work_kind is not None else None),
        ):
            if value is not None:
                filters.append(f"{column}=?")
                params.append(value)
        where = " WHERE " + " AND ".join(filters) if filters else ""
        params.append(max(0, int(limit)))
        return await self._call(
            lambda conn: [
                item
                for row in conn.execute(
                    "SELECT * FROM agent_invocations" + where
                    + " ORDER BY created_at,invocation_id LIMIT ?",
                    params,
                ).fetchall()
                if (item := self._invocation_from_row(row)) is not None
            ]
        )

